                soulProgression.TryGetProperty("totalExperience", out var totalExpEl) &&
                totalExpEl.ValueKind == JsonValueKind.Number &&
                totalExpEl.TryGetInt32(out var soulExp))
            {
                return soulExp;
            }
        }
        catch (JsonException)
        {
            return null;
        }

        return null;
    }

