    private async Task ValidateGuardianNpcBoundaryAsync(List<ValidationIssue> issues, (HashSet<string> Ids, HashSet<string> Names) knownGuardianReferences)
    {
        if (knownGuardianReferences.Ids.Count == 0 && knownGuardianReferences.Names.Count == 0)
            return;

        var json = await _fs.ReadFileAsync("game_state/npcs/npc_core.json");
        if (string.IsNullOrWhiteSpace(json))
            return;

        try
        {
            using var doc = JsonDocument.Parse(json);
            foreach (var sectionName in new[] { "UpdateNPCs", "NPCsInScene" })
            {
                if (!doc.RootElement.TryGetProperty(sectionName, out var arr) || arr.ValueKind != JsonValueKind.Array)
                    continue;

                var index = 0;
                foreach (var npc in arr.EnumerateArray())
                {
                    var context = $"game_state/npcs/npc_core.json.{sectionName}[{index++}]";
                    if (npc.ValueKind != JsonValueKind.Object)
                        continue;

                    var npcId = GetFirstNonEmptyString(npc, "NPCId", "npcId", "id");
                    var npcName = GetFirstNonEmptyString(npc, "name", "npcName", "NPCName");
                    var idCollision = !string.IsNullOrWhiteSpace(npcId) && knownGuardianReferences.Ids.Contains(npcId);
                    var nameCollision = !string.IsNullOrWhiteSpace(npcName) && knownGuardianReferences.Names.Contains(npcName);
                    if (!idCollision && !nameCollision)
                        continue;

                    issues.Add(new ValidationIssue(
                        context,
                        IssueSeverity.Error,
                        "Guardians не должны попадать в NPC surfaces",
                        code: "guardian_leaked_into_npc_surface",
                        section: "Guardians",
                        expected: "Guardians only in UpdateGuardians / guardians.json",
                        actual: idCollision
                            ? $"guardianId collision: {npcId}"
                            : $"guardian name collision: {npcName}",
                        repairHint: "Не используй UpdateNPCs или NPCsInScene для Хранителей. Перенеси сущность в UpdateGuardians / game_state/meta/guardians.json."));
                }
            }
        }
        catch
        {
            // ignored
        }
    }

    private static void CollectGuardianReferencesFromStateRoot(JsonElement root, HashSet<string> ids, HashSet<string> names, bool includeCommandSurfaces = true)
    {
        if (root.TryGetProperty("guardians", out var guardians) && guardians.ValueKind == JsonValueKind.Array)
        {
            foreach (var guardian in guardians.EnumerateArray())
                RegisterGuardianReference(guardian, ids, names);
        }

        if (root.TryGetProperty("activeGuardian", out var activeGuardian) && activeGuardian.ValueKind == JsonValueKind.Object)
            RegisterGuardianReference(activeGuardian, ids, names);

        if (includeCommandSurfaces &&
            root.TryGetProperty("UpdateGuardians", out var updates) &&
            updates.ValueKind == JsonValueKind.Array)
        {
            foreach (var command in updates.EnumerateArray())
            {
                if (command.ValueKind != JsonValueKind.Object)
                    continue;

                var commandName = GetFirstNonEmptyString(command, "command");
                if (string.Equals(commandName, "create", StringComparison.OrdinalIgnoreCase) &&
                    command.TryGetProperty("data", out var data) &&
                    data.ValueKind == JsonValueKind.Object)
                {
                    RegisterGuardianReference(data, ids, names);
                    continue;
                }

                RegisterGuardianReference(command, ids, names);
            }
        }
    }

    private static void RegisterGuardianReference(JsonElement guardian, HashSet<string> ids, HashSet<string> names)
    {
        var guardianId = GetFirstNonEmptyString(guardian, "guardianId", "id");
        var guardianName = GetFirstNonEmptyString(guardian, "name");
        if (!string.IsNullOrWhiteSpace(guardianId))
            ids.Add(guardianId);
        if (!string.IsNullOrWhiteSpace(guardianName))
            names.Add(guardianName);
    }

    private static void CollectCreatedGuardianIdsFromStateRoot(JsonElement root, HashSet<string> ids)
    {
        if (!root.TryGetProperty("UpdateGuardians", out var updates) || updates.ValueKind != JsonValueKind.Array)
            return;

        foreach (var command in updates.EnumerateArray())
        {
            if (command.ValueKind != JsonValueKind.Object)
                continue;

            var commandName = GetFirstNonEmptyString(command, "command");
            if (!string.Equals(commandName, "create", StringComparison.OrdinalIgnoreCase) ||
                !command.TryGetProperty("data", out var data) ||
                data.ValueKind != JsonValueKind.Object)
            {
                continue;
            }

            var guardianId = GetFirstNonEmptyString(data, "guardianId", "id");
            if (!string.IsNullOrWhiteSpace(guardianId))
                ids.Add(guardianId);
        }
    }

    private static void CollectCreatedGuardianReferencesFromStateRoot(JsonElement root, HashSet<string> ids, HashSet<string> names)
    {
        if (!root.TryGetProperty("UpdateGuardians", out var updates) || updates.ValueKind != JsonValueKind.Array)
            return;

        foreach (var command in updates.EnumerateArray())
        {
            if (command.ValueKind != JsonValueKind.Object)
                continue;

            var commandName = GetFirstNonEmptyString(command, "command");
            if (!string.Equals(commandName, "create", StringComparison.OrdinalIgnoreCase) ||
                !command.TryGetProperty("data", out var data) ||
                data.ValueKind != JsonValueKind.Object)
            {
                continue;
            }

            RegisterGuardianReference(data, ids, names);
        }
    }

    private static void CollectCodexEntryIdsFromRoot(JsonElement root, HashSet<string> ids, bool includeStoredEntries)
    {
        if (includeStoredEntries &&
            root.TryGetProperty("entries", out var entries) &&
            entries.ValueKind == JsonValueKind.Array)
        {
            foreach (var entry in entries.EnumerateArray())
            {
                var entryId = GetFirstNonEmptyString(entry, "entryId");
                if (!string.IsNullOrWhiteSpace(entryId))
                    ids.Add(entryId);
            }
        }

        if (root.TryGetProperty("loreCodexUpdates", out var updates) && updates.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in updates.EnumerateArray())
            {
                if (item.ValueKind != JsonValueKind.Object)
                    continue;

                var command = GetFirstNonEmptyString(item, "command");
                var isSameTurnAdd = string.Equals(command, "add", StringComparison.OrdinalIgnoreCase);

                if (!isSameTurnAdd)
                    continue;

                if (item.TryGetProperty("entry", out var entry) && entry.ValueKind == JsonValueKind.Object)
                {
                    var entryId = GetFirstNonEmptyString(entry, "entryId");
                    if (!string.IsNullOrWhiteSpace(entryId))
                        ids.Add(entryId);
                }
            }
        }
    }

    private async Task ValidateSoulQuestGuardianCrossReferencesAsync(List<ValidationIssue> issues, HashSet<string> knownGuardianIds)
    {
        var json = await _fs.ReadFileAsync("game_state/quests/soul_quests.json");
        if (string.IsNullOrWhiteSpace(json))
            return;

        try
        {
            using var doc = JsonDocument.Parse(json);
            string questCollectionName;
            if (doc.RootElement.TryGetProperty("quests", out var quests))
            {
                questCollectionName = "quests";
            }
            else if (doc.RootElement.TryGetProperty("UpdateSoulQuests", out quests))
            {
                questCollectionName = "UpdateSoulQuests";
            }
            else
            {
                return;
            }

            if (quests.ValueKind != JsonValueKind.Array)
                return;

            var index = 0;
            foreach (var quest in quests.EnumerateArray())
            {
                var guardianId = GetFirstNonEmptyString(quest, "guardianId");
                if (!string.IsNullOrWhiteSpace(guardianId) && !knownGuardianIds.Contains(guardianId))
                {
                    issues.Add(new ValidationIssue(
                        $"game_state/quests/soul_quests.json.{questCollectionName}[{index}].guardianId",
                        IssueSeverity.Error,
                        $"Soul Quest ссылается на неизвестного guardianId '{guardianId}'",
                        code: "soul_quest_unknown_guardian_id",
                        section: "CrossReferences",
                        expected: "existing guardianId from canonical guardians state",
                        actual: guardianId,
                        repairHint: "Для Soul Quest используй существующий guardianId из canonical guardians state. Если Хранитель создаётся впервые, сначала сохрани его через UpdateGuardians.create, а затем ссылайся на его permanent guardianId."));
                }
                index++;
            }
        }
        catch
        {
            // ignored
        }
    }

    private static IEnumerable<JsonElement> EnumerateLocationLikeObjects(JsonElement root, bool includeLocationUpdates = true)
    {
        if (root.ValueKind == JsonValueKind.Object &&
            root.TryGetProperty("currentLocationData", out var currentLocationData) &&
            currentLocationData.ValueKind == JsonValueKind.Object)
        {
            yield return currentLocationData;
        }

        if (root.ValueKind == JsonValueKind.Object &&
            (root.TryGetProperty("locationId", out _) || root.TryGetProperty("locationType", out _)))
        {
            yield return root;
        }

        if (root.ValueKind != JsonValueKind.Object)
            yield break;

        if (root.TryGetProperty("worldMapUpdates", out var worldMapUpdates) &&
            worldMapUpdates.ValueKind == JsonValueKind.Object)
        {
            foreach (var item in EnumerateLocationLikeObjects(worldMapUpdates, includeLocationUpdates))
                yield return item;
        }

        foreach (var propName in includeLocationUpdates
                     ? new[] { "newLocations", "locations", "locationUpdates" }
                     : new[] { "newLocations", "locations" })
        {
            if (!root.TryGetProperty(propName, out var arr) || arr.ValueKind != JsonValueKind.Array)
                continue;

            foreach (var item in arr.EnumerateArray())
            {
                if (item.ValueKind == JsonValueKind.Object)
                    yield return item;
            }
        }
    }

    private static void RegisterWorldLocationState(WorldLocationStateIndex index, JsonElement location)
    {
        var locationId = GetFirstNonEmptyString(location, "locationId");
        if (string.IsNullOrWhiteSpace(locationId))
            return;

        var locationType = GetFirstNonEmptyString(location, "locationType");
        if (!string.IsNullOrWhiteSpace(locationType))
            index.LocationTypesByLocationId[locationId] = locationType;

        var biome = GetFirstNonEmptyString(location, "biome");
        if (!string.IsNullOrWhiteSpace(biome))
            index.BiomesByLocationId[locationId] = biome;

        if (location.TryGetProperty("coordinates", out var coordinates) &&
            TryGetNormalizedLocationCoordinatesKey(coordinates, out var coordinateKey))
        {
            AddDictionarySetValue(index.CoordinateKeysByLocationId, locationId, coordinateKey);
        }

        if (location.TryGetProperty("adjacencyMap", out var adjacencyMap) &&
            adjacencyMap.ValueKind == JsonValueKind.Array)
        {
            foreach (var link in adjacencyMap.EnumerateArray())
            {
                if (link.ValueKind != JsonValueKind.Object ||
                    !link.TryGetProperty("targetCoordinates", out var targetCoordinates) ||
                    !TryGetNormalizedLocationCoordinatesKey(targetCoordinates, out var targetCoordinateKey))
                {
                    continue;
                }

                AddDictionarySetValue(index.LinkTargetCoordinateKeysBySourceLocationId, locationId, targetCoordinateKey);
            }
        }

        if (location.TryGetProperty("locationStorages", out var storages) &&
            storages.ValueKind == JsonValueKind.Array)
        {
            foreach (var storage in storages.EnumerateArray())
            {
                var storageId = GetFirstNonEmptyString(storage, "storageId");
                if (!string.IsNullOrWhiteSpace(storageId))
                    AddDictionarySetValue(index.StorageIdsByLocationId, locationId, storageId);
            }
        }

        if (location.TryGetProperty("activeThreats", out var activeThreats) &&
            activeThreats.ValueKind == JsonValueKind.Array)
        {
            foreach (var threat in activeThreats.EnumerateArray())
            {
                var threatId = GetFirstNonEmptyString(threat, "threatId");
                if (!string.IsNullOrWhiteSpace(threatId))
                {
                    AddDictionarySetValue(index.ThreatIdsByLocationId, locationId, threatId);
                    if (threat.TryGetProperty("currentActivity", out var currentActivity) &&
                        currentActivity.ValueKind == JsonValueKind.Object)
                    {
                        AddDictionarySetValue(index.ThreatIdsWithCurrentActivityByLocationId, locationId, threatId);
                    }
                }
            }
        }
    }

    private static bool TryGetNormalizedLocationCoordinatesKey(JsonElement coordinates, out string coordinateKey)
    {
        coordinateKey = string.Empty;
        if (coordinates.ValueKind != JsonValueKind.Object ||
            !TryGetCoordinateInt(coordinates, "x", out var x) ||
            !TryGetCoordinateInt(coordinates, "y", out var y))
        {
            return false;
        }

        var z = 0;
        if (coordinates.TryGetProperty("z", out var zNode))
        {
            if (!TryGetCoordinateInt(coordinates, "z", out z))
                return false;
        }

        coordinateKey = $"{x}:{y}:{z}";
        return true;
    }

    private static bool TryGetCoordinateInt(JsonElement coordinates, string propName, out int value)
    {
        value = 0;
        if (!coordinates.TryGetProperty(propName, out var node) ||
            node.ValueKind != JsonValueKind.Number ||
            !node.TryGetInt32(out value))
        {
            return false;
        }

        return true;
    }

    private static void AddDictionarySetValue(
        Dictionary<string, HashSet<string>> dictionary,
        string key,
        string value)
    {
        if (!dictionary.TryGetValue(key, out var values))
        {
            values = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            dictionary[key] = values;
        }

        values.Add(value);
    }

    private static void CollectFactionIdsFromStateRoot(JsonElement root, HashSet<string> ids, HashSet<string>? preTurnKnownIds)
    {
        if (preTurnKnownIds == null &&
            root.TryGetProperty("factions", out var factions) &&
            factions.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in factions.EnumerateArray())
            {
                var factionId = GetFirstNonEmptyString(item, "factionId");
                if (!string.IsNullOrWhiteSpace(factionId))
                    ids.Add(factionId);
            }
        }

        if (!root.TryGetProperty("factionDataChanges", out var factionDataChanges) ||
            factionDataChanges.ValueKind != JsonValueKind.Array)
        {
            return;
        }

        foreach (var item in factionDataChanges.EnumerateArray())
        {
            if (item.ValueKind != JsonValueKind.Object)
                continue;

            var factionId = GetFirstNonEmptyString(item, "factionId");
            if (string.IsNullOrWhiteSpace(factionId))
                continue;

            var initialId = GetFirstNonEmptyString(item, "initialId");
            var isNewFaction = item.TryGetProperty("isNewFaction", out var isNewFactionNode) &&
                               isNewFactionNode.ValueKind == JsonValueKind.True;

            if (preTurnKnownIds == null ||
                preTurnKnownIds.Contains(factionId) ||
                ((!string.IsNullOrWhiteSpace(initialId) || isNewFaction) && !preTurnKnownIds.Contains(factionId)))
            {
                ids.Add(factionId);
            }
        }
    }

    private static HashSet<string> FlattenCoordinateKeys(Dictionary<string, HashSet<string>> coordinateKeysByLocationId)
    {
        var keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var values in coordinateKeysByLocationId.Values)
            keys.UnionWith(values);

        return keys;
    }

    private static void ValidateNewLocationCoordinateKey(
        string coordinateKey,
        string context,
        HashSet<string> knownCoordinateKeys,
        HashSet<string> sameTurnCoordinateKeys,
        List<ValidationIssue> issues)
    {
        if (knownCoordinateKeys.Contains(coordinateKey))
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "Новая локация использует coordinates, которые уже заняты существующей canonical location",
                code: "world_map_new_location_coordinates_conflict_existing",
                section: "WorldMap",
                expected: "coordinates that do not conflict with existing known locations",
                actual: coordinateKey,
                repairHint: "Для новой локации выбери coordinates, которые не совпадают с уже известной canonical location. Если это existing location, используй её locationId и canonical coordinates вместо создания новой записи."));
            return;
        }

        if (!sameTurnCoordinateKeys.Add(coordinateKey))
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "Две same-turn новые локации используют один и тот же canonical coordinate key",
                code: "world_map_new_location_coordinates_duplicate_same_turn",
                section: "WorldMap",
                expected: "unique coordinates per newly created location",
                actual: coordinateKey,
                repairHint: "Не создавай несколько новых локаций с одинаковыми coordinates в одном accepted turn. Разведи их coordinate keys или объедини в одну canonical location."));
        }
    }

    private static void ValidateAdjacencyTargets(JsonElement location, string context, HashSet<string> knownLocationIds, List<ValidationIssue> issues)
    {
        if (!location.TryGetProperty("adjacencyMap", out var adjacencyMap) || adjacencyMap.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var entry in adjacencyMap.EnumerateArray())
        {
            var targetLocationId = GetFirstNonEmptyString(entry, "targetLocationId");
            if (string.IsNullOrWhiteSpace(targetLocationId))
            {
                index++;
                continue;
            }

            if (!knownLocationIds.Contains(targetLocationId))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.adjacencyMap[{index}].targetLocationId",
                    IssueSeverity.Error,
                    $"adjacencyMap targetLocationId '{targetLocationId}' не найден среди известных локаций",
                    code: "world_map_adjacency_unknown_target",
                    section: "WorldMap",
                    expected: "existing locationId from canonical world state",
                    actual: targetLocationId,
                    repairHint: "Используй уже существующий canonical locationId из world state. Не адресуй adjacencyMap через временный или ещё не материализованный location target."));
            }
            index++;
        }
    }

    private static bool InventorySidecarReferenceExists(JsonElement item, (HashSet<string> Ids, HashSet<string> Names) inventoryRefs)
    {
        foreach (var key in new[] { "existedId", "itemId", "id" })
        {
            var value = GetFirstNonEmptyString(item, key);
            if (!string.IsNullOrWhiteSpace(value))
                return inventoryRefs.Ids.Contains(value);
        }

        var name = GetFirstNonEmptyString(item, "itemName", "name");
        return !string.IsNullOrWhiteSpace(name) && inventoryRefs.Names.Contains(name);
    }

    private static bool InventoryReferenceExists(JsonElement item, (HashSet<string> Ids, HashSet<string> Names) inventoryRefs)
    {
        return InventorySidecarReferenceExists(item, inventoryRefs);
    }

    private static bool NpcReferenceExists(JsonElement item, (HashSet<string> Ids, HashSet<string> Names) knownNpcReferences)
    {
        foreach (var key in new[] { "NPCId", "npcId", "id" })
        {
            var value = GetFirstNonEmptyString(item, key);
            if (!string.IsNullOrWhiteSpace(value))
                return knownNpcReferences.Ids.Contains(value);
        }

        var name = GetFirstNonEmptyString(item, "NPCName", "npcName", "name");
        return !string.IsNullOrWhiteSpace(name) && knownNpcReferences.Names.Contains(name);
    }

    private static bool NpcMemoryIdExists(
        JsonElement item,
        string memoryId,
        Dictionary<string, HashSet<string>> idsByNpc)
    {
        foreach (var alias in GetNpcAliases(item))
        {
            if (idsByNpc.TryGetValue(alias, out var ids) && ids.Contains(memoryId))
                return true;
        }

        return false;
    }

    private static void RegisterNpcMemoryId(
        JsonElement item,
        string memoryId,
        Dictionary<string, HashSet<string>> idsByNpc)
    {
        if (string.IsNullOrWhiteSpace(memoryId))
            return;

        foreach (var alias in GetNpcAliases(item))
        {
            if (!idsByNpc.TryGetValue(alias, out var ids))
            {
                ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                idsByNpc[alias] = ids;
            }

            ids.Add(memoryId);
        }
    }

    private static IEnumerable<string> GetNpcAliases(JsonElement item)
    {
        var aliases = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var key in new[] { "NPCId", "npcId", "id", "NPCName", "npcName", "name" })
        {
            var value = GetFirstNonEmptyString(item, key);
            if (!string.IsNullOrWhiteSpace(value))
                aliases.Add(value);
        }

        return aliases;
    }

    private static void RegisterNpcScopedInventoryReference(
        JsonElement inventoryItem,
        IEnumerable<string> npcAliases,
        Dictionary<string, (HashSet<string> Ids, HashSet<string> Names)> refsByNpc)
    {
        foreach (var alias in npcAliases)
        {
            if (!refsByNpc.TryGetValue(alias, out var refs))
                refs = (new HashSet<string>(StringComparer.OrdinalIgnoreCase), new HashSet<string>(StringComparer.OrdinalIgnoreCase));

            RegisterInventoryReference(inventoryItem, refs.Ids, refs.Names);
            refsByNpc[alias] = refs;
        }
    }

    private static (HashSet<string> Ids, HashSet<string> Names) GetNpcScopedInventoryReferences(
        JsonElement item,
        Dictionary<string, (HashSet<string> Ids, HashSet<string> Names)> refsByNpc)
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var alias in GetNpcAliases(item))
        {
            if (!refsByNpc.TryGetValue(alias, out var refs))
                continue;

            ids.UnionWith(refs.Ids);
            names.UnionWith(refs.Names);
        }

        return (ids, names);
    }

    private static void RegisterNpcScopedContainerId(
        string containerId,
        IEnumerable<string> npcAliases,
        Dictionary<string, HashSet<string>> containerIdsByNpc)
    {
        foreach (var alias in npcAliases)
        {
            if (!containerIdsByNpc.TryGetValue(alias, out var ids))
            {
                ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                containerIdsByNpc[alias] = ids;
            }

            ids.Add(containerId);
        }
    }

    private static HashSet<string> GetNpcScopedContainerIds(
        JsonElement item,
        Dictionary<string, HashSet<string>> containerIdsByNpc)
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var alias in GetNpcAliases(item))
        {
            if (!containerIdsByNpc.TryGetValue(alias, out var aliasIds))
                continue;

            ids.UnionWith(aliasIds);
        }

        return ids;
    }

    private static bool IsContainerInventoryItem(JsonElement inventoryItem)
    {
        return inventoryItem.TryGetProperty("isContainer", out var isContainer) &&
               isContainer.ValueKind == JsonValueKind.True;
    }

    private static void RegisterInventoryReference(JsonElement item, HashSet<string> ids, HashSet<string> names)
    {
        foreach (var key in new[] { "existedId", "itemId", "id" })
        {
            var value = GetFirstNonEmptyString(item, key);
            if (!string.IsNullOrWhiteSpace(value))
                ids.Add(value);
        }

        var name = GetFirstNonEmptyString(item, "itemName", "name");
        if (!string.IsNullOrWhiteSpace(name))
            names.Add(name);
    }

    private static bool TryGetInventoryItemsArrayForKnownReferenceRead(JsonElement root, out JsonElement items, out bool fullObjectOnly)
    {
        if (root.TryGetProperty("items", out items))
        {
            fullObjectOnly = true;
            return true;
        }

        if (root.TryGetProperty("UpdateInventory", out items))
        {
            fullObjectOnly = true;
            return true;
        }

        fullObjectOnly = false;
        return false;
    }

    private static bool ShouldAcceptInventoryReferenceCandidate(
        JsonElement item,
        HashSet<string>? knownExistingItemIds,
        bool currentStateNewItemsOnly)
    {
        if (!currentStateNewItemsOnly)
        {
            var existedId = GetFirstNonEmptyString(item, "existedId");
            return string.IsNullOrWhiteSpace(existedId) ||
                   knownExistingItemIds == null ||
                   knownExistingItemIds.Count == 0 ||
                   knownExistingItemIds.Contains(existedId);
        }

        if (!item.TryGetProperty("itemId", out var itemIdNode) ||
            itemIdNode.ValueKind != JsonValueKind.String ||
            string.IsNullOrWhiteSpace(itemIdNode.GetString()))
        {
            return false;
        }

        var stableItemId = itemIdNode.GetString() ?? string.Empty;
        if (string.IsNullOrWhiteSpace(stableItemId))
            return false;

        var existedIdForCurrentState = GetFirstNonEmptyString(item, "existedId");
        if (!string.IsNullOrWhiteSpace(existedIdForCurrentState))
            return false;

        return knownExistingItemIds == null || !knownExistingItemIds.Contains(stableItemId);
    }

    private static string? GetInventoryReferenceCandidateId(JsonElement item, bool currentStateNewItemsOnly)
    {
        if (!currentStateNewItemsOnly)
            return GetFirstNonEmptyString(item, "existedId", "itemId", "id");

        return item.TryGetProperty("itemId", out var itemIdNode) &&
               itemIdNode.ValueKind == JsonValueKind.String &&
               !string.IsNullOrWhiteSpace(itemIdNode.GetString())
            ? itemIdNode.GetString()
            : null;
    }

    private static void RegisterKnownInventoryItemReferencesFromJson(
        string? json,
        HashSet<string> ids,
        HashSet<string> names,
        HashSet<string>? knownExistingItemIds,
        bool currentStateNewItemsOnly)
    {
        if (string.IsNullOrWhiteSpace(json))
            return;

        try
        {
            using var doc = JsonDocument.Parse(json);
            if (!TryGetInventoryItemsArrayForKnownReferenceRead(doc.RootElement, out var items, out var fullObjectOnly) ||
                items.ValueKind != JsonValueKind.Array)
            {
                return;
            }

            foreach (var item in items.EnumerateArray())
            {
                if (item.ValueKind != JsonValueKind.Object)
                    continue;

                if (fullObjectOnly && !IsLikelyFullInventoryItemObject(item))
                    continue;

                if (!ShouldAcceptInventoryReferenceCandidate(item, knownExistingItemIds, currentStateNewItemsOnly))
                    continue;

                RegisterInventoryReference(item, ids, names);
            }
        }
        catch
        {
            // ignored
        }
    }

    private static InventoryEquipProfile? TryResolveInventoryItemEquipProfileFromJson(
        string? json,
        string itemId,
        HashSet<string>? knownExistingItemIds,
        bool currentStateNewItemsOnly)
    {
        if (string.IsNullOrWhiteSpace(json) || string.IsNullOrWhiteSpace(itemId))
            return null;

        try
        {
            using var doc = JsonDocument.Parse(json);
            if (!TryGetInventoryItemsArrayForKnownReferenceRead(doc.RootElement, out var items, out var fullObjectOnly) ||
                items.ValueKind != JsonValueKind.Array)
            {
                return null;
            }

            foreach (var currentItem in items.EnumerateArray())
            {
                if (currentItem.ValueKind != JsonValueKind.Object)
                    continue;

                var currentItemId = GetInventoryReferenceCandidateId(currentItem, currentStateNewItemsOnly);
                if (!string.Equals(currentItemId, itemId, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (fullObjectOnly && !IsLikelyFullInventoryItemObject(currentItem))
                    continue;

                if (!ShouldAcceptInventoryReferenceCandidate(currentItem, knownExistingItemIds, currentStateNewItemsOnly))
                    continue;

                return ReadInventoryEquipProfile(currentItem);
            }
        }
        catch
        {
            // ignored
        }

        return null;
    }

    private async Task ValidateLifeEvaluationRewardCycleAsync(List<ValidationIssue> issues)
    {
        var manifest = await LoadValidationPendingTurnSnapshotManifestAsync();
        if (manifest == null || !LifeEvaluationRewardAnalyzer.IsLifeEvaluationSourceLabel(manifest.SourceLabel))
            return;

        const string soulStatePath = "game_state/meta/soul_state.json";
        var preSoulStateJson = await ReadPreTurnTrackedFileAsync(soulStatePath);
        var postSoulStateJson = await _fs.ReadFileAsync(soulStatePath);

        if (!LifeEvaluationRewardAnalyzer.TryComputeDelta(preSoulStateJson, postSoulStateJson, out var delta, out var error) ||
            delta == null)
        {
            issues.Add(new ValidationIssue(
                soulStatePath,
                IssueSeverity.Error,
                $"Не удалось вычислить reward delta для life evaluation: {error ?? "unknown error"}",
                code: "life_evaluation_reward_delta_unreadable",
                section: "LifeEvaluation",
                expected: "валидный pre/post diff по soul_state.json",
                repairHint: "Убедись, что pending turn snapshot сохранил pre-turn soul_state.json, а текущий soul_state.json корректно обновлён после оценки жизни."));
            return;
        }

        if (delta.InkFeathersEarned < 10)
        {
            issues.Add(new ValidationIssue(
                soulStatePath,
                IssueSeverity.Error,
                "Life evaluation обязан начислить минимум 10 Чернильных Перьев.",
                code: "life_evaluation_missing_ink_feather_reward",
                section: "LifeEvaluation",
                expected: "ink feathers delta >= 10",
                actual: delta.InkFeathersEarned.ToString(),
                repairHint: "После завершения смертной жизни увеличь soul_state.inkFeathers.current минимум на 10 и отрази survival minimum / основной расчёт награды в GM response."));
        }

        if (delta.NewRelics.Count == 0)
        {
            issues.Add(new ValidationIssue(
                soulStatePath,
                IssueSeverity.Error,
                "Life evaluation обязан добавить хотя бы одну новую Реликвию Души.",
                code: "life_evaluation_missing_soul_relic_reward",
                section: "LifeEvaluation",
                expected: "at least one new soulRelic.relicId",
                actual: "0 new relics",
                repairHint: "Создай минимум одну новую Soul Relic с новым relicId в soulRelics.stored[] или soulRelics.equipped[]."));
        }

        const string playerChroniclePath = "lore/chaos_sea/player_chronicle.json";
        var preChronicleJson = await ReadPreTurnTrackedFileAsync(playerChroniclePath);
        var postChronicleJson = await _fs.ReadFileAsync(playerChroniclePath);
        if (!DidChronicleGainMeaningfulSummaryEntry(preChronicleJson, postChronicleJson))
        {
            issues.Add(new ValidationIssue(
                playerChroniclePath,
                IssueSeverity.Error,
                "Life evaluation обязан добавить life summary в lore/chaos_sea/player_chronicle.json.",
                code: "life_evaluation_missing_player_chronicle_update",
                section: "LifeEvaluation",
                expected: "player_chronicle appends a new non-empty summary entry for the completed life",
                repairHint: "Добавь в конец player_chronicle.json новую непустую summary entry с итогами завершённой жизни и не перезаписывай предыдущие записи."));
        }
    }

    private async Task ValidateNoLifeEvaluationRewardsOnTriggerTurnAsync(List<ValidationIssue> issues)
    {
        var manifest = await LoadValidationPendingTurnSnapshotManifestAsync();
        if (manifest == null || LifeEvaluationRewardAnalyzer.IsLifeEvaluationSourceLabel(manifest.SourceLabel))
            return;

        const string lifeTransitionsPath = "game_state/control/life_transitions.json";
        var lifeTransitionsJson = await _fs.ReadFileAsync(lifeTransitionsPath);
        if (string.IsNullOrWhiteSpace(lifeTransitionsJson))
            return;

        try
        {
            using var doc = JsonDocument.Parse(lifeTransitionsJson);
            if (!TryReadLifeTransitionControlPayload(doc.RootElement, out _, out _))
                return;
        }
        catch (JsonException)
        {
            return;
        }

        const string soulStatePath = "game_state/meta/soul_state.json";
        var preSoulStateJson = await ReadPreTurnTrackedFileAsync(soulStatePath);
        var postSoulStateJson = await _fs.ReadFileAsync(soulStatePath);
        if (LifeEvaluationRewardAnalyzer.TryComputeDelta(preSoulStateJson, postSoulStateJson, out var delta, out _) &&
            delta != null)
        {
            if (delta.InkFeathersEarned > 0)
            {
                issues.Add(new ValidationIssue(
                    soulStatePath,
                    IssueSeverity.Error,
                    "TriggerLifeEnd turn не должен начислять финальную Ink Feather награду; она принадлежит отдельному Life Evaluation turn.",
                    code: "life_trigger_turn_awarded_ink_feathers",
                    section: "LifeEvaluation",
                    expected: "ink feathers delta = 0 on TriggerLifeEnd turn",
                    actual: delta.InkFeathersEarned.ToString(),
                    repairHint: "Оставь TriggerLifeEnd turn только для запуска lifecycle. Финальные Ink Feather rewards начисляй на следующем отдельном Life Evaluation turn."));
            }

            if (delta.NewRelics.Count > 0)
            {
                issues.Add(new ValidationIssue(
                    soulStatePath,
                    IssueSeverity.Error,
                    "TriggerLifeEnd turn не должен выдавать Soul Relic reward; она принадлежит отдельному Life Evaluation turn.",
                    code: "life_trigger_turn_awarded_soul_relic",
                    section: "LifeEvaluation",
                    expected: "0 new soul relics on TriggerLifeEnd turn",
                    actual: delta.NewRelics.Count.ToString(),
                    repairHint: "Не смешивай TriggerLifeEnd с финальной наградой. Новые Soul Relics создавай только на отдельном Life Evaluation turn."));
            }
        }

        const string playerChroniclePath = "lore/chaos_sea/player_chronicle.json";
        var preChronicleJson = await ReadPreTurnTrackedFileAsync(playerChroniclePath);
        var postChronicleJson = await _fs.ReadFileAsync(playerChroniclePath);
        if (DidChronicleGainEntries(preChronicleJson, postChronicleJson))
        {
            issues.Add(new ValidationIssue(
                playerChroniclePath,
                IssueSeverity.Error,
                "TriggerLifeEnd turn не должен писать финальный life summary в player_chronicle; это отдельный Life Evaluation outcome.",
                code: "life_trigger_turn_updated_player_chronicle",
                section: "LifeEvaluation",
                expected: "no new player_chronicle entry on TriggerLifeEnd turn",
                actual: "player_chronicle entry added",
                repairHint: "Оставь player_chronicle update на отдельный Life Evaluation turn после принятого TriggerLifeEnd."));
        }
    }

    private async Task ValidateClientOwnedControlFilesAsync(List<ValidationIssue> issues)
    {
        var manifest = await LoadValidationPendingTurnSnapshotManifestAsync();
        await ValidateValidationRepairReadyAsync(issues);

        if (manifest == null)
            return;

        if (!string.IsNullOrWhiteSpace(manifest.ManifestPayloadHash))
        {
            var actualHash = ComputeManifestPayloadHash(manifest);
            if (!string.Equals(actualHash, manifest.ManifestPayloadHash, StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    PendingTurnSnapshotManifestPath,
                    IssueSeverity.Error,
                    "pending_turn_snapshot.json был изменён после создания клиентом и больше не совпадает с исходным snapshot manifest.",
                    code: "client_owned_pending_snapshot_manifest_modified",
                    section: "PendingTurnSnapshot",
                    expected: manifest.ManifestPayloadHash,
                    actual: actualHash,
                    repairHint: "Не изменяй pending_turn_snapshot.json в GM turn; это client-owned transient control file."));
            }
        }

        foreach (var (originalPath, snapshotPath) in manifest.Files)
        {
            if (!manifest.SnapshotFileHashes.TryGetValue(originalPath, out var expectedHash) || string.IsNullOrWhiteSpace(expectedHash))
                continue;

            var currentSnapshotContent = await _fs.ReadFileAsync(snapshotPath);
            var actualHash = currentSnapshotContent == null ? string.Empty : ComputeSha256(currentSnapshotContent);
            if (!string.Equals(actualHash, expectedHash, StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    snapshotPath,
                    IssueSeverity.Error,
                    $"Файл client-owned snapshot '{snapshotPath}' был изменён после создания pending turn snapshot.",
                    code: "client_owned_pending_snapshot_file_modified",
                    section: "PendingTurnSnapshot",
                    expected: expectedHash,
                    actual: actualHash,
                    repairHint: "Не изменяй содержимое game_state/control/pending_turn_snapshot/* в GM turn."));
            }
        }

        foreach (var (baselinePath, expectedHash) in manifest.ClientOwnedValidationHashes)
        {
            // validation_repair_request.json and terminal_protocol_failure_request.json are
            // runtime-authored protocol surfaces. They can legitimately change while the client
            // advances the repair/protocol loop, so blaming the GM for their hash drift creates a
            // self-sustaining deadlock. Only history surfaces remain in the GM-blame hash pass.
            if (!IsClientOwnedHistoryValidationPath(baselinePath))
                continue;

            var currentContent = await _fs.ReadFileAsync(baselinePath);
            var actualHash = currentContent == null ? string.Empty : ComputeSha256(currentContent);
            if (string.Equals(actualHash, expectedHash, StringComparison.OrdinalIgnoreCase))
                continue;

            issues.Add(new ValidationIssue(
                baselinePath,
                IssueSeverity.Error,
                $"{Path.GetFileName(baselinePath)} является client-maintained history surface и не должен изменяться GM-ходом.",
                code: "client_owned_history_surface_modified",
                section: "ClientHistory",
                expected: "unchanged client-maintained chat/story history surface",
                actual: actualHash,
                repairHint: "Не записывай chat_log.json или stories/*.jsonl в GM response. Эти continuity/history surfaces поддерживаются клиентом."));
        }

        var baselineHistoryPaths = new HashSet<string>(
            manifest.ClientOwnedValidationHashes.Keys.Where(IsClientOwnedHistoryValidationPath),
            StringComparer.OrdinalIgnoreCase);
        foreach (var storyPath in EnumerateStoryContinuityFiles())
        {
            if (baselineHistoryPaths.Contains(storyPath))
                continue;

            issues.Add(new ValidationIssue(
                storyPath,
                IssueSeverity.Error,
                "stories/*.jsonl являются client-maintained continuity history и не должны создаваться GM-ходом.",
                code: "client_owned_story_continuity_created_by_gm",
                section: "ClientHistory",
                expected: "no new GM-authored stories/*.jsonl files",
                actual: storyPath,
                repairHint: "Не создавай и не переписывай stories/*.jsonl в GM response; их поддерживает клиент как narrative continuity surface."));
        }

        foreach (var clientOwnedPath in new[]
                 {
                     WorldDirectiveService.PendingSetupPath,
                     WorldDirectiveService.ActiveDirectivesPath
                 })
        {
            if (!await DidFileChangeAgainstManifestAsync(manifest, clientOwnedPath))
                continue;

            issues.Add(new ValidationIssue(
                clientOwnedPath,
                IssueSeverity.Error,
                $"{Path.GetFileName(clientOwnedPath)} является client-authored world setup state и не должен изменяться GM-ходом.",
                code: "client_owned_world_setup_state_modified",
                section: "WorldSetup",
                repairHint: $"Не записывай {clientOwnedPath} в GM response; этот файл поддерживается клиентом/игроком и должен читаться GM как входной контракт."));
        }
    }

    private async Task ValidateValidationRepairReadyAsync(List<ValidationIssue> issues)
    {
        const string readyPath = "game_state/control/validation_repair_ready.json";
        const string requestPath = "game_state/control/validation_repair_request.json";

        var readyJson = await _fs.ReadFileAsync(readyPath);
        if (string.IsNullOrWhiteSpace(readyJson))
            return;

        JsonElement readyRoot;
        try
        {
            using var readyDoc = JsonDocument.Parse(readyJson);
            if (readyDoc.RootElement.ValueKind != JsonValueKind.Object)
            {
                issues.Add(new ValidationIssue(
                    readyPath,
                    IssueSeverity.Error,
                    "validation_repair_ready.json должен быть JSON object",
                    code: "invalid_repair_ready_json",
                    section: "validation_repair_ready",
                    expected: "JSON object with sessionId/requestId/turnNumber",
                    actual: readyDoc.RootElement.ValueKind.ToString(),
                    repairHint: "Перезапиши validation_repair_ready.json как valid JSON object и скопируй в него точные sessionId/requestId/turnNumber из validation_repair_request.json."));
                return;
            }

            readyRoot = readyDoc.RootElement.Clone();
        }
        catch (JsonException ex)
        {
            issues.Add(new ValidationIssue(
                readyPath,
                IssueSeverity.Error,
                $"validation_repair_ready.json не является валидным JSON: {ex.Message}",
                code: "invalid_repair_ready_json",
                section: "validation_repair_ready",
                repairHint: "Перезапиши validation_repair_ready.json валидным JSON и скопируй в него точные sessionId/requestId/turnNumber из validation_repair_request.json."));
            return;
        }

        var requestJson = await _fs.ReadFileAsync(requestPath);
        if (string.IsNullOrWhiteSpace(requestJson))
        {
            issues.Add(new ValidationIssue(
                readyPath,
                IssueSeverity.Error,
                "validation_repair_ready.json не должен существовать без текущего validation_repair_request.json",
                code: "repair_ready_without_request",
                section: "validation_repair_ready",
                repairHint: "Используй validation_repair_ready.json только как ответ на активный validation_repair_request.json."));
            return;
        }

        try
        {
            using var requestDoc = JsonDocument.Parse(requestJson);
            if (requestDoc.RootElement.ValueKind != JsonValueKind.Object)
                return;

            var expectedSessionId = GetFirstNonEmptyString(requestDoc.RootElement, "sessionId") ?? string.Empty;
            var expectedRequestId = GetFirstNonEmptyString(requestDoc.RootElement, "requestId") ?? string.Empty;
            var expectedTurnNumber = requestDoc.RootElement.TryGetProperty("turnNumber", out var turnNumberNode) &&
                                     turnNumberNode.ValueKind == JsonValueKind.Number &&
                                     turnNumberNode.TryGetInt32(out var parsedTurn)
                ? parsedTurn
                : (int?)null;

            var actualSessionId = GetFirstNonEmptyString(readyRoot, "sessionId") ?? string.Empty;
            var actualRequestId = GetFirstNonEmptyString(readyRoot, "requestId") ?? string.Empty;
            var actualTurnNumber = readyRoot.TryGetProperty("turnNumber", out var readyTurnNode) &&
                                   readyTurnNode.ValueKind == JsonValueKind.Number &&
                                   readyTurnNode.TryGetInt32(out var parsedReadyTurn)
                ? parsedReadyTurn
                : (int?)null;

            if (!string.Equals(expectedSessionId, actualSessionId, StringComparison.Ordinal) ||
                !string.Equals(expectedRequestId, actualRequestId, StringComparison.Ordinal) ||
                expectedTurnNumber != actualTurnNumber)
            {
                issues.Add(new ValidationIssue(
                    readyPath,
                    IssueSeverity.Error,
                    "validation_repair_ready.json должен копировать точные sessionId/requestId/turnNumber из validation_repair_request.json",
                    code: "mismatched_repair_ready_context",
                    section: "validation_repair_ready",
                    expected: $"sessionId={expectedSessionId}, requestId={expectedRequestId}, turnNumber={expectedTurnNumber?.ToString() ?? "missing"}",
                    actual: $"sessionId={actualSessionId}, requestId={actualRequestId}, turnNumber={actualTurnNumber?.ToString() ?? "missing"}",
                    repairHint: "Скопируй sessionId/requestId/turnNumber ровно из текущего validation_repair_request.json без переиспользования старого ready signal."));
            }
        }
        catch
        {
            // ignored; request file shape is client-owned and validated elsewhere in client flow
        }
    }

    private async Task ValidateRealmSegregationAsync(List<ValidationIssue> issues)
    {
        var manifest = await LoadValidationPendingTurnSnapshotManifestAsync();
        if (manifest == null)
            return;

        if (IsRealmTransitionSourceLabel(manifest.SourceLabel) ||
            LifeEvaluationRewardAnalyzer.IsLifeEvaluationSourceLabel(manifest.SourceLabel))
        {
            return;
        }

        var preTurnRealm = await TryResolvePreTurnRealmAsync();
        if (string.IsNullOrWhiteSpace(preTurnRealm))
            return;
        var changedFiles = await GetChangedTrackedFilesAgainstManifestAsync(manifest);
        if (changedFiles.Count == 0)
            return;

        var forbiddenFiles = IsChaosSeaRealm(preTurnRealm)
            ? changedFiles.Where(IsForbiddenChaosSeaChangedFile).ToList()
            : changedFiles.Where(IsForbiddenMortalWorldChangedFile).ToList();

        if (forbiddenFiles.Count == 0)
            return;

        var expected = IsChaosSeaRealm(preTurnRealm)
            ? "Afterlife turn should mutate only soul/guardian/meta/codex/achievement/story surfaces and explicit cross-realm exceptions"
            : "Mortal World turn should mutate only mortal-world systems plus explicitly allowed meta exceptions";
        var forbiddenGroups = DescribeRealmSegregationGroups(forbiddenFiles);
        var actual = string.Join(", ", forbiddenFiles);
        if (forbiddenGroups.Count > 0)
            actual += $" | surfaces: {string.Join(", ", forbiddenGroups)}";
        var repairHint = IsChaosSeaRealm(preTurnRealm)
            ? "Убери mortal-world state mutations из afterlife-хода. В Chaos Sea/Shining Abode допустимы только soul_state, guardians, lore/chaos_sea, codex, achievements, story outputs и явные lifecycle/cross-realm исключения."
            : "Убери guardian / Chaos Sea / afterlife-only mutations из mortal-world хода. Оставь NPC, world, combat, quest, inventory, faction системы и только явно разрешённые meta-исключения.";

        issues.Add(new ValidationIssue(
            "game_state/meta/soul_state.json.currentRealm",
            IssueSeverity.Error,
            $"Нарушение Realm Segregation: pre-turn realm '{preTurnRealm}' несовместим с изменениями файлов {string.Join(", ", forbiddenFiles)}",
            code: "realm_segregation_violation",
            section: "RealmSegregation",
            expected: expected,
            actual: actual,
            repairHint: repairHint));
    }

