        if (root.TryGetProperty("playerEffortTrackerChange", out var effort) &&
            effort.ValueKind != JsonValueKind.Null)
        {
            ValidateEffortTrackerObject(effort, $"{contextPrefix}.playerEffortTrackerChange", issues);
        }
    }

