        {
            ["itemJournalUpdates"] = journalUpdates
        };
        using var doc = JsonDocument.Parse(JsonSerializer.Serialize(wrapper));
        ValidateItemJournalStateFile(doc.RootElement, contextPrefix, issues);
    }

    private void ValidateMetaStateUpdates(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("metaStateUpdates", out var metaState))
            return;

        var context = $"{contextPrefix}.metaStateUpdates";
        if (metaState.ValueKind == JsonValueKind.Null)
            return;

        if (!RequireObject(metaState, context, issues))
            return;

        if (metaState.TryGetProperty("inkFeatherChanges", out var feathers) && !RequireObject(feathers, $"{context}.inkFeatherChanges", issues))
            return;
        if (metaState.TryGetProperty("enlightenmentProgression", out var enlightenment) && !RequireObject(enlightenment, $"{context}.enlightenmentProgression", issues))
            return;
        if (metaState.TryGetProperty("soulRelicOperations", out var relicOps) && !RequireObject(relicOps, $"{context}.soulRelicOperations", issues))
            return;
        if (metaState.TryGetProperty("lifeTransitions", out var lifeTransitions) && !RequireObject(lifeTransitions, $"{context}.lifeTransitions", issues))
            return;
        if (metaState.TryGetProperty("memoryLegacyGrant", out var memoryLegacyGrant) && !RequireObject(memoryLegacyGrant, $"{context}.memoryLegacyGrant", issues))
            return;

        if (metaState.TryGetProperty("lifeTransitions", out var transitionsWithRecordCheck) &&
            transitionsWithRecordCheck.ValueKind == JsonValueKind.Object &&
            transitionsWithRecordCheck.TryGetProperty("recordLifeCompletion", out _) &&
            (!root.TryGetProperty("TriggerLifeEnd", out var triggerLifeEnd) || triggerLifeEnd.ValueKind != JsonValueKind.Object))
        {
            issues.Add(new ValidationIssue(
                $"{context}.lifeTransitions.recordLifeCompletion",
                IssueSeverity.Error,
                "recordLifeCompletion допустим только в canonical TriggerLifeEnd turn",
                code: "life_transition_record_without_trigger_life_end",
                section: "Lifecycle",
                expected: "recordLifeCompletion together with TriggerLifeEnd object on a mortal-life end turn",
                actual: "recordLifeCompletion without TriggerLifeEnd",
                repairHint: "Используй recordLifeCompletion только на accepted turn, который реально содержит TriggerLifeEnd(reason=Death|Voluntary). Для later Life Evaluation turn не дублируй lifeTransitions record повторно."));
        }

        if (metaState.TryGetProperty("lifeTransitions", out var transitions) && transitions.ValueKind == JsonValueKind.Object)
            ValidateMetaLifeTransitionsObject(transitions, $"{context}.lifeTransitions", issues);
        if (metaState.TryGetProperty("memoryLegacyGrant", out var grant) && grant.ValueKind == JsonValueKind.Object)
            ValidateMemoryLegacyGrantObject(grant, $"{context}.memoryLegacyGrant", issues);
    }

    private void ValidatePendingMemoryLegacy(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("pendingMemoryLegacy", out var pendingLegacy))
            return;

        var context = $"{contextPrefix}.pendingMemoryLegacy";
        if (pendingLegacy.ValueKind == JsonValueKind.Null)
            return;
        if (!RequireObject(pendingLegacy, context, issues))
            return;

        var missingPendingLegacyFields = GetMissingRequiredNonEmptyStringProperties(
            pendingLegacy,
            "legacyId",
            "legacyType",
            "sourceLifeHint",
            "grantSource",
            "applicationState",
            "grantedAtUtc");
        if (!pendingLegacy.TryGetProperty("grantSnapshot", out var requiredGrantSnapshot) || requiredGrantSnapshot.ValueKind != JsonValueKind.Object)
            missingPendingLegacyFields.Add("grantSnapshot");
        if (missingPendingLegacyFields.Count > 0)
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "pendingMemoryLegacy не содержит обязательные корневые поля",
                code: "pending_memory_legacy_missing_required_fields",
                section: "MemoryLegacy",
                expected: "Non-empty legacyId, legacyType, sourceLifeHint, grantSource, applicationState, grantedAtUtc, and grantSnapshot object",
                actual: string.Join(", ", missingPendingLegacyFields),
                repairHint: "Сначала собери полный корневой canonical pendingMemoryLegacy contract: legacyId, legacyType, sourceLifeHint, grantSource, applicationState, grantedAtUtc и grantSnapshot обязательны ещё до type-specific полей."));
            return;
        }

        var grantSource = GetFirstNonEmptyString(pendingLegacy, "grantSource") ?? string.Empty;
        var applicationState = GetFirstNonEmptyString(pendingLegacy, "applicationState") ?? string.Empty;

        var legacyType = pendingLegacy.TryGetProperty("legacyType", out var typeEl) && typeEl.ValueKind == JsonValueKind.String
            ? typeEl.GetString() ?? string.Empty
            : string.Empty;

        if (!string.IsNullOrWhiteSpace(grantSource) &&
            !string.Equals(grantSource, "memoryLegacyGrant", StringComparison.Ordinal))
        {
            issues.Add(new ValidationIssue(
                $"{context}.grantSource",
                IssueSeverity.Error,
                "grantSource в pendingMemoryLegacy должен быть 'memoryLegacyGrant'",
                code: "pending_memory_legacy_invalid_grant_source",
                section: "MemoryLegacy",
                expected: "memoryLegacyGrant",
                actual: grantSource,
                repairHint: "Не записывай pendingMemoryLegacy как независимый итог. Сохрани его как canonical projection от structured metaStateUpdates.memoryLegacyGrant."));
        }

        if (!string.Equals(applicationState, "pending", StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(applicationState, "applied-awaiting-turn-accept", StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                $"{context}.applicationState",
                IssueSeverity.Error,
                "applicationState в pendingMemoryLegacy должен быть 'pending' или 'applied-awaiting-turn-accept'",
                code: "pending_memory_legacy_invalid_application_state",
                section: "MemoryLegacy",
                expected: "pending | applied-awaiting-turn-accept",
                actual: string.IsNullOrWhiteSpace(applicationState) ? "missing" : applicationState,
                repairHint: "Используй canonical applicationState для pendingMemoryLegacy: до локального применения legacy это pending, после локального применения перед accepted incarnation turn это applied-awaiting-turn-accept."));
        }

        if (!pendingLegacy.TryGetProperty("grantSnapshot", out var grantSnapshot))
        {
            issues.Add(new ValidationIssue(
                $"{context}.grantSnapshot",
                IssueSeverity.Error,
                "pendingMemoryLegacy должен содержать обязательный объект grantSnapshot",
                code: "pending_memory_legacy_missing_grant_snapshot",
                section: "MemoryLegacy",
                expected: "grantSnapshot object",
                actual: "missing",
                repairHint: "Canonical pendingMemoryLegacy должен сохранять structured grantSnapshot рядом с итоговыми полями legacy, чтобы клиент мог сверить semantic consistency."));
        }
        else if (!RequireObject(grantSnapshot, $"{context}.grantSnapshot", issues))
        {
            return;
        }
        else
        {
            ValidateMemoryLegacyGrantObject(grantSnapshot, $"{context}.grantSnapshot", issues);
            ValidatePendingMemoryLegacyMatchesGrantSnapshot(pendingLegacy, grantSnapshot, context, issues);
        }

        if (string.Equals(applicationState, "applied-awaiting-turn-accept", StringComparison.OrdinalIgnoreCase))
        {
            if (!pendingLegacy.TryGetProperty("applicationAudit", out var audit) || !RequireObject(audit, $"{context}.applicationAudit", issues))
                return;
        }
        else if (pendingLegacy.TryGetProperty("applicationAudit", out var pendingAudit) && pendingAudit.ValueKind != JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{context}.applicationAudit",
                IssueSeverity.Error,
                "applicationAudit допустим только при applicationState = applied-awaiting-turn-accept",
                code: "pending_memory_legacy_application_audit_in_wrong_state",
                section: "MemoryLegacy",
                repairHint: "Убери applicationAudit из pending legacy до локального применения награды. Это поле допустимо только в applied-awaiting-turn-accept."));
        }

        if (string.Equals(legacyType, "startingCharacteristicBonus", StringComparison.OrdinalIgnoreCase))
        {
            var missingCharacteristicLegacyFields = GetMissingRequiredNonEmptyStringProperties(pendingLegacy, "characteristic");
            if (missingCharacteristicLegacyFields.Count > 0 || !pendingLegacy.TryGetProperty("bonus", out _))
            {
                var actualMissing = new List<string>(missingCharacteristicLegacyFields);
                if (!pendingLegacy.TryGetProperty("bonus", out _))
                    actualMissing.Add("bonus");

                issues.Add(new ValidationIssue(
                    context,
                    IssueSeverity.Error,
                    "startingCharacteristicBonus pendingMemoryLegacy не содержит type-specific обязательные поля",
                    code: "pending_memory_legacy_characteristic_fields_missing",
                    section: "MemoryLegacy",
                    expected: "characteristic and bonus for startingCharacteristicBonus",
                    actual: string.Join(", ", actualMissing),
                    repairHint: "Для legacyType=startingCharacteristicBonus сохрани characteristic и bonus=2 в canonical pendingMemoryLegacy."));
                return;
            }

            var characteristic = GetFirstNonEmptyString(pendingLegacy, "characteristic") ?? string.Empty;
        ValidatePositiveIntegerField(pendingLegacy, context, issues, "bonus");

            if (!string.IsNullOrWhiteSpace(characteristic) &&
                !Characteristics.All.Contains(characteristic, StringComparer.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.characteristic",
                    IssueSeverity.Error,
                    "characteristic в pendingMemoryLegacy должен быть допустимым именем характеристики",
                    code: "pending_memory_legacy_invalid_characteristic",
                    section: "MemoryLegacy",
                    expected: "valid characteristic name",
                    actual: characteristic,
                    repairHint: "Используй canonical имя характеристики из rules/spec для startingCharacteristicBonus legacy."));
            }

            if (pendingLegacy.TryGetProperty("bonus", out var bonusEl) &&
                bonusEl.ValueKind == JsonValueKind.Number &&
                bonusEl.TryGetInt32(out var bonus) &&
                bonus != 2)
            {
                issues.Add(new ValidationIssue(
                    $"{context}.bonus",
                    IssueSeverity.Error,
                    "Для startingCharacteristicBonus bonus должен быть ровно 2",
                    code: "pending_memory_legacy_invalid_characteristic_bonus",
                    section: "MemoryLegacy",
                    expected: "2",
                    actual: bonus.ToString(),
                    repairHint: "Memory Legacy типа startingCharacteristicBonus всегда даёт ровно +2 к одной характеристике."));
            }
        }
        else if (string.Equals(legacyType, "startingPassiveKnowledgeSkill", StringComparison.OrdinalIgnoreCase))
        {
            var missingSkillLegacyFields = GetMissingRequiredNonEmptyStringProperties(
                pendingLegacy,
                "skillName",
                "skillDescription",
                "group",
                "playerStatBonus");
            if (missingSkillLegacyFields.Count > 0 || !pendingLegacy.TryGetProperty("structuredBonuses", out _))
            {
                var actualMissing = new List<string>(missingSkillLegacyFields);
                if (!pendingLegacy.TryGetProperty("structuredBonuses", out _))
                    actualMissing.Add("structuredBonuses");

                issues.Add(new ValidationIssue(
                    context,
                    IssueSeverity.Error,
                    "startingPassiveKnowledgeSkill pendingMemoryLegacy не содержит type-specific обязательные поля",
                    code: "pending_memory_legacy_skill_fields_missing",
                    section: "MemoryLegacy",
                    expected: "skillName, skillDescription, group, playerStatBonus, structuredBonuses",
                    actual: string.Join(", ", actualMissing),
                    repairHint: "Для legacyType=startingPassiveKnowledgeSkill сохрани canonical skill payload и непустой structuredBonuses в pendingMemoryLegacy."));
                return;
            }

            ValidateOptionalString(pendingLegacy, context, issues, "rarity");
            ValidateOptionalString(pendingLegacy, context, issues, "type");
            ValidatePositiveIntegerField(pendingLegacy, context, issues, "masteryLevel");
            ValidatePositiveIntegerField(pendingLegacy, context, issues, "maxMasteryLevel");

            if (pendingLegacy.TryGetProperty("group", out var groupEl) &&
                groupEl.ValueKind == JsonValueKind.String &&
                !string.Equals(groupEl.GetString(), "Knowledge", StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.group",
                    IssueSeverity.Error,
                    "startingPassiveKnowledgeSkill должен иметь group = 'Knowledge'",
                    code: "pending_memory_legacy_invalid_skill_group",
                    section: "MemoryLegacy",
                    expected: "Knowledge",
                    actual: groupEl.GetString() ?? string.Empty,
                    repairHint: "Passive-skill Memory Legacy должен использовать canonical group=Knowledge, как это требует contract для startingPassiveKnowledgeSkill."));
            }

            if (!pendingLegacy.TryGetProperty("structuredBonuses", out var bonuses))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.structuredBonuses",
                    IssueSeverity.Error,
                    "startingPassiveKnowledgeSkill должен содержать structuredBonuses",
                    code: "pending_memory_legacy_missing_structured_bonuses",
                    section: "MemoryLegacy",
                    expected: "non-empty structuredBonuses array",
                    actual: "missing",
                    repairHint: "Passive-skill Memory Legacy должен хранить canonical structuredBonuses рядом с skillName/skillDescription/group/playerStatBonus."));
            }
            else
            {
                RequireArrayOfObjects(bonuses, $"{context}.structuredBonuses", issues);
                if (bonuses.ValueKind == JsonValueKind.Array && bonuses.GetArrayLength() == 0)
                {
                    issues.Add(new ValidationIssue(
                        $"{context}.structuredBonuses",
                        IssueSeverity.Error,
                        "structuredBonuses для startingPassiveKnowledgeSkill не должен быть пустым",
                        code: "pending_memory_legacy_empty_structured_bonuses",
                        section: "MemoryLegacy",
                        expected: "non-empty structuredBonuses array",
                        actual: "empty array",
                        repairHint: "Не оставляй passive-skill Memory Legacy без механических бонусов. Сохрани непустой canonical structuredBonuses array."));
                }
            }

            if (string.Equals(applicationState, "applied-awaiting-turn-accept", StringComparison.OrdinalIgnoreCase) &&
                pendingLegacy.TryGetProperty("applicationAudit", out var skillAudit) &&
                skillAudit.ValueKind == JsonValueKind.Object)
            {
                RequireString(skillAudit, $"{context}.applicationAudit", issues, "expectedPassiveSkillName");
                RequireString(skillAudit, $"{context}.applicationAudit", issues, "expectedGroup");
                RequireString(skillAudit, $"{context}.applicationAudit", issues, "expectedPlayerStatBonus");
                ValidatePositiveNumberField(skillAudit, $"{context}.applicationAudit", issues, "expectedStructuredBonusesCount");
                RequireString(skillAudit, $"{context}.applicationAudit", issues, "expectedStructuredBonusesCanonical");
            }
        }
        else if (!string.IsNullOrWhiteSpace(legacyType))
        {
            issues.Add(new ValidationIssue(
                $"{context}.legacyType",
                IssueSeverity.Error,
                "Неподдерживаемый legacyType в pendingMemoryLegacy",
                code: "pending_memory_legacy_unsupported_legacy_type",
                section: "MemoryLegacy",
                expected: "startingCharacteristicBonus | startingPassiveKnowledgeSkill",
                actual: string.IsNullOrWhiteSpace(legacyType) ? "missing" : legacyType,
                repairHint: "Используй только canonical legacyType для Memory Gates: startingCharacteristicBonus или startingPassiveKnowledgeSkill."));
        }
    }

    private void ValidatePendingMemoryLegacyMatchesGrantSnapshot(JsonElement pendingLegacy, JsonElement grantSnapshot, string context, List<ValidationIssue> issues)
    {
        foreach (var fieldName in new[] { "legacyId", "legacyType", "sourceLifeHint" })
        {
            var pendingValue = GetFirstNonEmptyString(pendingLegacy, fieldName) ?? string.Empty;
            var snapshotValue = GetFirstNonEmptyString(grantSnapshot, fieldName) ?? string.Empty;
            if (!string.IsNullOrWhiteSpace(snapshotValue) &&
                !string.Equals(pendingValue, snapshotValue, StringComparison.Ordinal))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.{fieldName}",
                    IssueSeverity.Error,
                    $"{fieldName} в pendingMemoryLegacy должен совпадать с grantSnapshot",
                    code: "pending_memory_legacy_grant_snapshot_mismatch",
                    section: "MemoryLegacy",
                    expected: snapshotValue,
                    actual: string.IsNullOrWhiteSpace(pendingValue) ? "missing" : pendingValue,
                    repairHint: "Синхронизируй canonical pendingMemoryLegacy с данными structured memoryLegacyGrant/grantSnapshot."));
            }
        }

        var legacyType = GetFirstNonEmptyString(pendingLegacy, "legacyType") ?? string.Empty;
        if (string.Equals(legacyType, "startingCharacteristicBonus", StringComparison.OrdinalIgnoreCase))
        {
            var pendingCharacteristic = GetFirstNonEmptyString(pendingLegacy, "characteristic") ?? string.Empty;
            var snapshotCharacteristic = GetFirstNonEmptyString(grantSnapshot, "characteristic") ?? string.Empty;
            if (!string.IsNullOrWhiteSpace(snapshotCharacteristic) &&
                !string.Equals(pendingCharacteristic, snapshotCharacteristic, StringComparison.Ordinal))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.characteristic",
                    IssueSeverity.Error,
                    "characteristic в pendingMemoryLegacy должен совпадать с grantSnapshot",
                    code: "pending_memory_legacy_grant_snapshot_characteristic_mismatch",
                    section: "MemoryLegacy",
                    expected: snapshotCharacteristic,
                    actual: string.IsNullOrWhiteSpace(pendingCharacteristic) ? "missing" : pendingCharacteristic));
            }

            if (TryReadInt(grantSnapshot, "bonus", out var snapshotBonus) &&
                TryReadInt(pendingLegacy, "bonus", out var pendingBonus) &&
                pendingBonus != snapshotBonus)
            {
                issues.Add(new ValidationIssue(
                    $"{context}.bonus",
                    IssueSeverity.Error,
                    "bonus в pendingMemoryLegacy должен совпадать с grantSnapshot",
                    code: "pending_memory_legacy_grant_snapshot_bonus_mismatch",
                    section: "MemoryLegacy",
                    expected: snapshotBonus.ToString(),
                    actual: pendingBonus.ToString()));
            }
        }
        else if (string.Equals(legacyType, "startingPassiveKnowledgeSkill", StringComparison.OrdinalIgnoreCase))
        {
            foreach (var fieldName in new[] { "skillName", "skillDescription", "group" })
            {
                var pendingValue = GetFirstNonEmptyString(pendingLegacy, fieldName) ?? string.Empty;
                var snapshotValue = GetFirstNonEmptyString(grantSnapshot, fieldName) ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(snapshotValue) &&
                    !string.Equals(pendingValue, snapshotValue, StringComparison.Ordinal))
                {
                    issues.Add(new ValidationIssue(
                        $"{context}.{fieldName}",
                        IssueSeverity.Error,
                        $"{fieldName} в pendingMemoryLegacy должен совпадать с grantSnapshot",
                        code: "pending_memory_legacy_grant_snapshot_skill_field_mismatch",
                        section: "MemoryLegacy",
                        expected: snapshotValue,
                        actual: string.IsNullOrWhiteSpace(pendingValue) ? "missing" : pendingValue));
                }
            }

            var pendingPlayerStatBonus = GetFirstNonEmptyString(pendingLegacy, "playerStatBonus") ?? string.Empty;
            var snapshotPlayerStatBonus = GetFirstNonEmptyString(grantSnapshot, "playerStatBonus") ?? string.Empty;
            if (!string.IsNullOrWhiteSpace(snapshotPlayerStatBonus) &&
                string.IsNullOrWhiteSpace(pendingPlayerStatBonus))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.playerStatBonus",
                    IssueSeverity.Error,
                    "playerStatBonus в pendingMemoryLegacy не должен исчезать относительно grantSnapshot",
                    code: "pending_memory_legacy_grant_snapshot_player_stat_bonus_missing",
                    section: "MemoryLegacy",
                    expected: "non-empty playerStatBonus summary",
                    actual: "missing or empty",
                    repairHint: "Сохрани в pendingMemoryLegacy непустой playerStatBonus summary и не убирай это поле относительно grantSnapshot."));
            }

            if (pendingLegacy.TryGetProperty("structuredBonuses", out var pendingStructuredBonuses) &&
                grantSnapshot.TryGetProperty("structuredBonuses", out var snapshotStructuredBonuses) &&
                pendingStructuredBonuses.ValueKind == JsonValueKind.Array &&
                snapshotStructuredBonuses.ValueKind == JsonValueKind.Array)
            {
                var pendingCanonical = StructuredBonusCanonicalizer.Canonicalize(pendingStructuredBonuses);
                var snapshotCanonical = StructuredBonusCanonicalizer.Canonicalize(snapshotStructuredBonuses);
                if (!string.Equals(pendingCanonical, snapshotCanonical, StringComparison.Ordinal))
                {
                    issues.Add(new ValidationIssue(
                        $"{context}.structuredBonuses",
                        IssueSeverity.Error,
                        "structuredBonuses в pendingMemoryLegacy должны совпадать с grantSnapshot",
                        code: "pending_memory_legacy_grant_snapshot_structured_bonuses_mismatch",
                        section: "MemoryLegacy",
                        repairHint: "Не меняй structuredBonuses между structured grantSnapshot и canonical pendingMemoryLegacy."));
                }
            }
        }
    }

    private void ValidateMetaLifeTransitionsObject(JsonElement lifeTransitions, string context, List<ValidationIssue> issues)
    {
        if (!lifeTransitions.TryGetProperty("recordLifeCompletion", out var recordLifeCompletion))
            return;

        if (!RequireObject(recordLifeCompletion, $"{context}.recordLifeCompletion", issues))
            return;

        var recordContext = $"{context}.recordLifeCompletion";
        RequireObjectProperty(recordLifeCompletion, recordContext, issues, "characterFinalState");
        if (recordLifeCompletion.TryGetProperty("majorAchievements", out var majorAchievements))
            RequireArrayOfStrings(majorAchievements, $"{recordContext}.majorAchievements", issues);
        else
            issues.Add(new ValidationIssue(
                $"{recordContext}.majorAchievements",
                IssueSeverity.Error,
                "recordLifeCompletion должен содержать majorAchievements array",
                code: "life_transition_record_missing_major_achievements",
                section: "Lifecycle",
                expected: "majorAchievements array",
                actual: "missing",
                repairHint: "При записи recordLifeCompletion сохрани массив majorAchievements, даже если он пустой."));
        if (recordLifeCompletion.TryGetProperty("relationshipsFormed", out var relationshipsFormed))
            RequireArrayOfObjects(relationshipsFormed, $"{recordContext}.relationshipsFormed", issues);
        else
            issues.Add(new ValidationIssue(
                $"{recordContext}.relationshipsFormed",
                IssueSeverity.Error,
                "recordLifeCompletion должен содержать relationshipsFormed array",
                code: "life_transition_record_missing_relationships",
                section: "Lifecycle",
                expected: "relationshipsFormed array",
                actual: "missing",
                repairHint: "При записи recordLifeCompletion сохрани массив relationshipsFormed, даже если он пустой."));
        if (recordLifeCompletion.TryGetProperty("moralChoices", out var moralChoices))
            RequireArrayOfObjects(moralChoices, $"{recordContext}.moralChoices", issues);
        else
            issues.Add(new ValidationIssue(
                $"{recordContext}.moralChoices",
                IssueSeverity.Error,
                "recordLifeCompletion должен содержать moralChoices array",
                code: "life_transition_record_missing_moral_choices",
                section: "Lifecycle",
                expected: "moralChoices array",
                actual: "missing",
                repairHint: "При записи recordLifeCompletion сохрани массив moralChoices, даже если он пустой."));
        if (recordLifeCompletion.TryGetProperty("skillsLearned", out var skillsLearned))
            RequireArrayOfStrings(skillsLearned, $"{recordContext}.skillsLearned", issues);
        else
            issues.Add(new ValidationIssue(
                $"{recordContext}.skillsLearned",
                IssueSeverity.Error,
                "recordLifeCompletion должен содержать skillsLearned array",
                code: "life_transition_record_missing_skills_learned",
                section: "Lifecycle",
                expected: "skillsLearned array",
                actual: "missing",
                repairHint: "При записи recordLifeCompletion сохрани массив skillsLearned, даже если он пустой."));

        if (!recordLifeCompletion.TryGetProperty("enlightenmentGained", out _))
        {
            issues.Add(new ValidationIssue(
                $"{recordContext}.enlightenmentGained",
                IssueSeverity.Error,
                "recordLifeCompletion должен содержать enlightenmentGained",
                code: "life_transition_record_missing_enlightenment_gained",
                section: "Lifecycle",
                expected: "enlightenmentGained number",
                actual: "missing",
                repairHint: "При записи recordLifeCompletion укажи enlightenmentGained, даже если прирост равен 0."));
        }
        else
        {
            ValidateNonNegativeNumberField(recordLifeCompletion, recordContext, issues, "enlightenmentGained");
        }
    }

    private bool ValidateMemoryLegacyGrantObject(JsonElement grant, string context, List<ValidationIssue> issues)
    {
        var missingGrantFields = GetMissingRequiredNonEmptyStringProperties(grant, "legacyId", "legacyType", "sourceLifeHint");
        if (missingGrantFields.Count > 0)
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "memoryLegacyGrant не содержит обязательные корневые поля",
                code: "memory_legacy_grant_missing_required_fields",
                section: "MemoryLegacy",
                expected: "Non-empty legacyId, legacyType, sourceLifeHint",
                actual: string.Join(", ", missingGrantFields),
                repairHint: "Сначала собери canonical memoryLegacyGrant root contract с sourceLifeHint, затем добавляй type-specific payload."));
            return false;
        }

        var legacyType = grant.TryGetProperty("legacyType", out var typeEl) && typeEl.ValueKind == JsonValueKind.String
            ? typeEl.GetString() ?? string.Empty
            : string.Empty;

        if (string.Equals(legacyType, "startingCharacteristicBonus", StringComparison.OrdinalIgnoreCase))
        {
            var missingCharacteristicGrantFields = GetMissingRequiredNonEmptyStringProperties(grant, "characteristic");
            if (missingCharacteristicGrantFields.Count > 0 || !grant.TryGetProperty("bonus", out _))
            {
                var actualMissing = new List<string>(missingCharacteristicGrantFields);
                if (!grant.TryGetProperty("bonus", out _))
                    actualMissing.Add("bonus");

                issues.Add(new ValidationIssue(
                    context,
                    IssueSeverity.Error,
                    "startingCharacteristicBonus memoryLegacyGrant не содержит type-specific обязательные поля",
                    code: "memory_legacy_grant_characteristic_fields_missing",
                    section: "MemoryLegacy",
                    expected: "characteristic and bonus for startingCharacteristicBonus",
                    actual: string.Join(", ", actualMissing),
                    repairHint: "Для legacyType=startingCharacteristicBonus передай characteristic и bonus=2 в structured memoryLegacyGrant."));
                return false;
            }

            var characteristic = GetFirstNonEmptyString(grant, "characteristic") ?? string.Empty;
            ValidatePositiveIntegerField(grant, context, issues, "bonus");

            if (!string.IsNullOrWhiteSpace(characteristic) &&
                !Characteristics.All.Contains(characteristic, StringComparer.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.characteristic",
                    IssueSeverity.Error,
                    "memoryLegacyGrant.characteristic должен быть допустимым именем характеристики",
                    code: "memory_legacy_grant_invalid_characteristic",
                    section: "MemoryLegacy",
                    expected: "valid characteristic name",
                    actual: characteristic,
                    repairHint: "Используй canonical имя характеристики из rules/spec для startingCharacteristicBonus grant."));
                return false;
            }

            if (grant.TryGetProperty("bonus", out var bonusEl) &&
                bonusEl.ValueKind == JsonValueKind.Number &&
                bonusEl.TryGetInt32(out var bonus) &&
                bonus != 2)
            {
                issues.Add(new ValidationIssue(
                    $"{context}.bonus",
                    IssueSeverity.Error,
                    "memoryLegacyGrant для startingCharacteristicBonus должен давать ровно +2",
                    code: "memory_legacy_grant_invalid_characteristic_bonus",
                    section: "MemoryLegacy",
                    expected: "2",
                    actual: bonus.ToString(),
                    repairHint: "Structured memoryLegacyGrant для startingCharacteristicBonus всегда должен задавать bonus=2."));
                return false;
            }
        }
        else if (string.Equals(legacyType, "startingPassiveKnowledgeSkill", StringComparison.OrdinalIgnoreCase))
        {
            var missingSkillGrantFields = GetMissingRequiredNonEmptyStringProperties(
                grant,
                "skillName",
                "skillDescription",
                "group",
                "playerStatBonus");
            if (missingSkillGrantFields.Count > 0 || !grant.TryGetProperty("structuredBonuses", out _))
            {
                var actualMissing = new List<string>(missingSkillGrantFields);
                if (!grant.TryGetProperty("structuredBonuses", out _))
                    actualMissing.Add("structuredBonuses");

                issues.Add(new ValidationIssue(
                    context,
                    IssueSeverity.Error,
                    "startingPassiveKnowledgeSkill memoryLegacyGrant не содержит type-specific обязательные поля",
                    code: "memory_legacy_grant_skill_fields_missing",
                    section: "MemoryLegacy",
                    expected: "skillName, skillDescription, group, playerStatBonus, structuredBonuses",
                    actual: string.Join(", ", actualMissing),
                    repairHint: "Для legacyType=startingPassiveKnowledgeSkill передай полный canonical skill grant и непустой structuredBonuses."));
                return false;
            }

            ValidateOptionalString(grant, context, issues, "rarity");
            ValidateOptionalString(grant, context, issues, "type");
            ValidatePositiveIntegerField(grant, context, issues, "masteryLevel");
            ValidatePositiveIntegerField(grant, context, issues, "maxMasteryLevel");

            if (grant.TryGetProperty("group", out var groupEl) &&
                groupEl.ValueKind == JsonValueKind.String &&
                !string.Equals(groupEl.GetString(), "Knowledge", StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.group",
                    IssueSeverity.Error,
                    "memoryLegacyGrant для passive skill должен иметь group = 'Knowledge'",
                    code: "memory_legacy_grant_invalid_skill_group",
                    section: "MemoryLegacy",
                    expected: "Knowledge",
                    actual: groupEl.GetString() ?? string.Empty,
                    repairHint: "Passive-skill memoryLegacyGrant должен использовать canonical group=Knowledge."));
                return false;
            }

            if (!grant.TryGetProperty("structuredBonuses", out var bonuses))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.structuredBonuses",
                    IssueSeverity.Error,
                    "memoryLegacyGrant для passive skill должен содержать structuredBonuses",
                    code: "memory_legacy_grant_missing_structured_bonuses",
                    section: "MemoryLegacy",
                    expected: "non-empty structuredBonuses array",
                    actual: "missing",
                    repairHint: "Добавь в passive-skill memoryLegacyGrant непустой structuredBonuses array."));
                return false;
            }
            else
            {
                RequireArrayOfObjects(bonuses, $"{context}.structuredBonuses", issues);
                if (bonuses.ValueKind == JsonValueKind.Array && bonuses.GetArrayLength() == 0)
                {
                    issues.Add(new ValidationIssue(
                        $"{context}.structuredBonuses",
                        IssueSeverity.Error,
                        "structuredBonuses для passive skill legacy не должен быть пустым",
                        code: "memory_legacy_grant_empty_structured_bonuses",
                        section: "MemoryLegacy",
                        expected: "non-empty structuredBonuses array",
                        actual: "empty array",
                        repairHint: "Не оставляй passive-skill memoryLegacyGrant без механических бонусов. Сохрани непустой structuredBonuses array."));
                    return false;
                }
            }
        }
        else
        {
            issues.Add(new ValidationIssue(
                $"{context}.legacyType",
                IssueSeverity.Error,
                "memoryLegacyGrant должен использовать legacyType startingCharacteristicBonus или startingPassiveKnowledgeSkill",
                code: "memory_legacy_grant_unsupported_legacy_type",
                section: "MemoryLegacy",
                expected: "startingCharacteristicBonus | startingPassiveKnowledgeSkill",
                actual: string.IsNullOrWhiteSpace(legacyType) ? "missing" : legacyType,
                repairHint: "Используй только canonical legacyType для structured memoryLegacyGrant."));
            return false;
        }

        return true;
    }

    private void ValidateGuardianCommands(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("UpdateGuardians", out var updates))
            return;
        if (updates.ValueKind == JsonValueKind.Null)
            return;
        if (!TryGetArray(root, "UpdateGuardians", $"{contextPrefix}.UpdateGuardians", issues, out var arr))
            return;

        var knownGuardianIds = CollectKnownGuardianIds(root);
        var guardianSequentialStates = CollectKnownGuardianSequentialStatesForCommandValidation();
        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.UpdateGuardians[{index++}]";
            if (!RequireObject(item, itemContext, issues)) continue;
            var command = RequireString(item, itemContext, issues, "command");

            if (string.Equals(command, "create", StringComparison.OrdinalIgnoreCase))
            {
                if (!item.TryGetProperty("data", out var data) || !RequireObject(data, $"{itemContext}.data", issues))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.data",
                        IssueSeverity.Error,
                        "UpdateGuardians.create должен использовать nested data object с полным объектом Хранителя",
                        code: "guardian_create_missing_data",
                        section: "UpdateGuardians.create",
                        expected: "Nested data object",
                        actual: item.TryGetProperty("data", out var actualData) ? actualData.ValueKind.ToString() : "missing",
                        repairHint: "Используй create как special-case команду: command=create и data={ полный Guardian object }."));
                    continue;
                }

                var issuesBeforeCreateValidation = issues.Count;
                ValidateGuardianCanonicalObject(data, $"{itemContext}.data", issues);
                var createdGuardianId = GetFirstNonEmptyString(data, "guardianId");
                if (issues.Count == issuesBeforeCreateValidation &&
                    !string.IsNullOrWhiteSpace(createdGuardianId))
                {
                    knownGuardianIds.Add(createdGuardianId);
                    guardianSequentialStates[createdGuardianId] = ParseGuardianSequentialState(data);
                }
                continue;
            }

            var guardianId = RequireString(item, itemContext, issues, "guardianId");
            if (!string.IsNullOrWhiteSpace(guardianId) && !knownGuardianIds.Contains(guardianId))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.guardianId",
                    IssueSeverity.Error,
                    $"UpdateGuardians.{command} не может ссылаться на неизвестный guardianId '{guardianId}'",
                    code: "guardian_non_create_unknown_guardian",
                    section: $"UpdateGuardians.{command}",
                    expected: "existing guardianId from guardians.json or earlier create command in the same array",
                    actual: guardianId,
                    repairHint: "Используй существующий guardianId или сначала создай нового Хранителя через UpdateGuardians.create раньше в этом же массиве."));
            }

            switch (command)
            {
                case "updateReputation":
                    ValidateIntegerField(item, itemContext, issues, "reputationChange");
                    RequireString(item, itemContext, issues, "reason");
                    if (!string.IsNullOrWhiteSpace(guardianId) &&
                        guardianSequentialStates.TryGetValue(guardianId, out var guardianState) &&
                        item.TryGetProperty("reputationChange", out var reputationDeltaNode) &&
                        reputationDeltaNode.ValueKind == JsonValueKind.Number &&
                        reputationDeltaNode.TryGetInt32(out var reputationDelta) &&
                        guardianState.CurrentReputation.HasValue)
                    {
                        guardianState.CurrentReputation += reputationDelta;
                    }
                    RejectLegacyGuardianDataShape(item, itemContext, issues, command,
                        "Top-level reputationChange + reason",
                        "Убери data и вынеси reputationChange/reason на верхний уровень updateReputation.");
                    break;

                case "completeQuest":
                    var questId = RequireString(item, itemContext, issues, "questId");
                    var outcome = RequireString(item, itemContext, issues, "outcome");
                    if (!string.IsNullOrWhiteSpace(outcome) && !AllowedGuardianQuestOutcomes.Contains(outcome))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.outcome",
                            IssueSeverity.Error,
                            "completeQuest.outcome должен быть success, failure или partial",
                            code: "guardian_complete_quest_invalid_outcome",
                            section: "UpdateGuardians.completeQuest",
                            expected: "success | failure | partial",
                            actual: outcome));
                    }
                    if (!string.IsNullOrWhiteSpace(guardianId) &&
                        !string.IsNullOrWhiteSpace(questId) &&
                        guardianSequentialStates.TryGetValue(guardianId, out var questState))
                    {
                        var knownQuest =
                            questState.AvailableQuestIds.Contains(questId) ||
                            questState.ActiveQuestIds.Contains(questId);
                        if (!knownQuest)
                        {
                            issues.Add(new ValidationIssue(
                                $"{itemContext}.questId",
                                IssueSeverity.Error,
                                "UpdateGuardians.completeQuest ссылается на questId, которого нет в canonical questManagement этого Хранителя",
                                code: "guardian_complete_quest_unknown_quest_id",
                                section: "UpdateGuardians.completeQuest",
                                expected: "questId from this Guardian's tracked questManagement state",
                                actual: questId,
                                repairHint: "Завершай только тот guardian quest, который реально существует у этого Хранителя в canonical questManagement. Сначала добавь квест в questManagement этого Хранителя, затем закрывай его через completeQuest."));
                        }
                        else
                        {
                            questState.AvailableQuestIds.Remove(questId);
                            questState.ActiveQuestIds.Remove(questId);
                        }
                    }
                    RejectLegacyGuardianDataShape(item, itemContext, issues, command,
                        "Top-level questId + outcome",
                        "Убери data и вынеси questId/outcome на верхний уровень completeQuest.");
                    break;

                case "processGacha":
                    ValidatePositiveNumberField(item, itemContext, issues, "inkFeathersSpent");
                    if (!string.IsNullOrWhiteSpace(guardianId) &&
                        guardianSequentialStates.TryGetValue(guardianId, out var gachaState) &&
                        gachaState.CurrentReputation.HasValue)
                    {
                        var chargesPerReturn = GetExpectedGuardianGachaCharges(gachaState.CurrentReputation.Value);
                        if (gachaState.ChargesUsedThisReturn >= chargesPerReturn)
                        {
                            issues.Add(new ValidationIssue(
                                $"{itemContext}.guardianId",
                                IssueSeverity.Error,
                                "processGacha нельзя вызывать для Хранителя без оставшихся charges в текущем return cycle",
                                code: "guardian_process_gacha_no_remaining_charges",
                                section: "UpdateGuardians.processGacha",
                                expected: $"chargesUsedThisReturn < chargesPerReturn ({gachaState.ChargesUsedThisReturn} < {chargesPerReturn})",
                                actual: $"chargesUsedThisReturn={gachaState.ChargesUsedThisReturn}, chargesPerReturn={chargesPerReturn}, currentReputation={gachaState.CurrentReputation.Value}",
                                repairHint: "Не эмить processGacha, если у этого Хранителя уже нет оставшихся попыток в текущем возвращении. Используй другого Хранителя или direct /gacha без guardian-mediated command."));
                        }
                        else
                        {
                            gachaState.ChargesUsedThisReturn++;
                        }
                    }

                    if (!item.TryGetProperty("result", out var result) || !RequireObject(result, $"{itemContext}.result", issues))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.result",
                            IssueSeverity.Error,
                            "processGacha должен использовать top-level поле result с объектом реликвии",
                            code: "guardian_process_gacha_missing_result",
                            section: "UpdateGuardians.processGacha",
                            expected: "Top-level result object",
                            actual: item.TryGetProperty("result", out var actualResult) ? actualResult.ValueKind.ToString() : "missing",
                            repairHint: "Используй processGacha с top-level полями inkFeathersSpent и result, а не legacy nested data shape."));
                    }
                    else
                    {
                        ValidateMinimalSoulRelicObject(result, $"{itemContext}.result", issues, "UpdateGuardians.processGacha");

                        var baseRarity = TryReadCurrentTurnGachaBaseRaritySync();
                        var finalRarity = GetFirstNonEmptyString(result, "rarity", "quality");
                        if (!string.IsNullOrWhiteSpace(baseRarity))
                        {
                            if (string.IsNullOrWhiteSpace(finalRarity))
                            {
                                issues.Add(new ValidationIssue(
                                    $"{itemContext}.result.rarity",
                                    IssueSeverity.Error,
                                    "processGacha.result должен явно сохранять final rarity реликвии",
                                    code: "guardian_process_gacha_missing_result_rarity",
                                    section: "UpdateGuardians.processGacha",
                                    expected: $"rarity >= {baseRarity}",
                                    actual: "missing rarity/quality",
                                    repairHint: "Сохрани в result финальную редкость реликвии и не опускай её ниже client-computed gachaBaseResult.baseRarity."));
                            }
                            else if (GetRarityRank(finalRarity) < GetRarityRank(baseRarity))
                            {
                                issues.Add(new ValidationIssue(
                                    $"{itemContext}.result.rarity",
                                    IssueSeverity.Error,
                                    "processGacha не может понизить редкость ниже client-computed gachaBaseResult.baseRarity",
                                    code: "guardian_process_gacha_result_below_base_rarity",
                                    section: "UpdateGuardians.processGacha",
                                    expected: $">= {baseRarity}",
                                    actual: finalRarity,
                                    repairHint: "Используй gachaBaseResult.baseRarity как минимум. Guardian modifiers могут только повышать итоговую редкость, но не понижать её."));
                            }
                        }
                    }

                    RejectLegacyGuardianDataShape(item, itemContext, issues, command,
                        "Top-level inkFeathersSpent + result",
                        "Убери data и вынеси inkFeathersSpent/result на верхний уровень processGacha.");
                    break;

                case "addMusings":
                    ValidateGuardianMusingsCommand(item, itemContext, issues);
                    break;

                case "updateProject":
                    if (!item.TryGetProperty("currentProject", out var currentProject) ||
                        !RequireObject(currentProject, $"{itemContext}.currentProject", issues))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.currentProject",
                            IssueSeverity.Error,
                            "updateProject должен содержать top-level объект currentProject",
                            code: "guardian_update_project_missing_current_project",
                            section: "UpdateGuardians.updateProject",
                            expected: "Top-level currentProject object",
                            actual: item.TryGetProperty("currentProject", out var actualProject) ? actualProject.ValueKind.ToString() : "missing",
                            repairHint: "Для UpdateGuardians.updateProject передай currentProject как top-level объект с projectId, name/projectName, description, progressPercent, estimatedTurnsLeft или estimatedCompletionTurn и playerCanAssist."));
                    }
                    else
                    {
                        ValidateGuardianCurrentProjectObject(currentProject, $"{itemContext}.currentProject", issues);
                    }
                    break;

                case "unlockLore":
                    if (!item.TryGetProperty("loreFragment", out var loreFragment) ||
                        !RequireObject(loreFragment, $"{itemContext}.loreFragment", issues))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.loreFragment",
                            IssueSeverity.Error,
                            "unlockLore должен содержать top-level объект loreFragment",
                            code: "guardian_unlock_lore_missing_fragment",
                            section: "UpdateGuardians.unlockLore",
                            expected: "Top-level loreFragment object",
                            actual: item.TryGetProperty("loreFragment", out var actualFragment) ? actualFragment.ValueKind.ToString() : "missing",
                            repairHint: "Передай unlockLore как top-level loreFragment object с fragmentId, category, title, content и requiredReputation, а не как произвольный текст или nested legacy shape."));
                    }
                    else
                    {
                        ValidateGuardianLoreFragmentObject(loreFragment, $"{itemContext}.loreFragment", issues, allowNullableContent: false);
                    }
                    break;

                case "setMood":
                    if (!item.TryGetProperty("mood", out var mood) ||
                        !RequireObject(mood, $"{itemContext}.mood", issues))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.mood",
                            IssueSeverity.Error,
                            "setMood должен содержать top-level объект mood",
                            code: "guardian_set_mood_missing_object",
                            section: "UpdateGuardians.setMood",
                            expected: "Top-level mood object",
                            actual: item.TryGetProperty("mood", out var actualMood) ? actualMood.ValueKind.ToString() : "missing",
                            repairHint: "Передай setMood как top-level mood object с current, intensity, reason и since, чтобы canonical guardian mood можно было синхронно обновить."));
                    }
                    else
                    {
                        ValidateGuardianMoodObject(mood, $"{itemContext}.mood", issues);
                    }
                    break;

                default:
                    issues.Add(new ValidationIssue(
                        itemContext,
                        IssueSeverity.Error,
                        $"Неподдерживаемая guardian command: {command}",
                        code: "guardian_unsupported_command",
                        section: "UpdateGuardians",
                        expected: "Supported commands: create, updateReputation, completeQuest, processGacha, addMusings, updateProject, unlockLore, setMood",
                        actual: command,
                        repairHint: "Используй только те guardian commands, которые реально поддерживаются current CLI contract."));
                    break;
            }
        }
    }

    private Dictionary<string, GuardianSequentialState> CollectKnownGuardianSequentialStatesForCommandValidation()
    {
        var states = new Dictionary<string, GuardianSequentialState>(StringComparer.OrdinalIgnoreCase);
        var preTurnGuardiansJson = ReadPreTurnTrackedFileSync("game_state/meta/guardians.json");
        if (string.IsNullOrWhiteSpace(preTurnGuardiansJson))
            return states;

        try
        {
            using var doc = JsonDocument.Parse(preTurnGuardiansJson);
            CollectGuardianSequentialStatesFromRoot(doc.RootElement, states);
        }
        catch
        {
            // ignored: higher-level JSON integrity validation already covers malformed pre-turn state
        }

        return states;
    }

    private static void CollectGuardianSequentialStatesFromRoot(JsonElement root, Dictionary<string, GuardianSequentialState> states)
    {
        if (root.TryGetProperty("guardians", out var guardians) && guardians.ValueKind == JsonValueKind.Array)
        {
            foreach (var guardian in guardians.EnumerateArray())
                MergeGuardianSequentialState(states, guardian);
        }

        if (root.TryGetProperty("activeGuardian", out var activeGuardian) && activeGuardian.ValueKind == JsonValueKind.Object)
            MergeGuardianSequentialState(states, activeGuardian);
    }

    private static void MergeGuardianSequentialState(Dictionary<string, GuardianSequentialState> states, JsonElement guardian)
    {
        var guardianId = GetFirstNonEmptyString(guardian, "guardianId", "id");
        if (string.IsNullOrWhiteSpace(guardianId))
            return;

        states[guardianId] = ParseGuardianSequentialState(guardian);
    }

    private static GuardianSequentialState ParseGuardianSequentialState(JsonElement guardian)
    {
        int? currentReputation = null;
        if (guardian.TryGetProperty("relationshipData", out var relationshipData) &&
            relationshipData.ValueKind == JsonValueKind.Object &&
            relationshipData.TryGetProperty("currentReputation", out var currentReputationNode) &&
            currentReputationNode.ValueKind == JsonValueKind.Number &&
            currentReputationNode.TryGetInt32(out var parsedReputation))
        {
            currentReputation = parsedReputation;
        }

        var availableQuestIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var activeQuestIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (guardian.TryGetProperty("questManagement", out var questManagement) &&
            questManagement.ValueKind == JsonValueKind.Object)
        {
            CollectQuestIdsFromGuardianQuestArray(questManagement, "availableQuests", availableQuestIds);
            CollectQuestIdsFromGuardianQuestArray(questManagement, "activeQuests", activeQuestIds);
        }

        var chargesUsedThisReturn = 0;
        if (guardian.TryGetProperty("gachaSystem", out var gachaSystem) &&
            gachaSystem.ValueKind == JsonValueKind.Object &&
            gachaSystem.TryGetProperty("chargesUsedThisReturn", out var chargesUsedNode) &&
            chargesUsedNode.ValueKind == JsonValueKind.Number &&
            chargesUsedNode.TryGetInt32(out var parsedChargesUsed))
        {
            chargesUsedThisReturn = Math.Max(0, parsedChargesUsed);
        }

        var state = new GuardianSequentialState
        {
            CurrentReputation = currentReputation,
            ChargesUsedThisReturn = chargesUsedThisReturn
        };
        state.AvailableQuestIds.UnionWith(availableQuestIds);
        state.ActiveQuestIds.UnionWith(activeQuestIds);
        return state;
    }

    private static void CollectQuestIdsFromGuardianQuestArray(JsonElement questManagement, string propName, HashSet<string> target)
    {
        if (!questManagement.TryGetProperty(propName, out var questArray) || questArray.ValueKind != JsonValueKind.Array)
            return;

        foreach (var quest in questArray.EnumerateArray())
        {
            if (quest.ValueKind != JsonValueKind.Object)
                continue;

            var questId = GetFirstNonEmptyString(quest, "questId");
            if (!string.IsNullOrWhiteSpace(questId))
                target.Add(questId);
        }
    }

    private void RejectLegacyGuardianDataShape(JsonElement item, string itemContext, List<ValidationIssue> issues,
        string command, string expected, string repairHint)
    {
        if (!item.TryGetProperty("data", out _))
            return;

        issues.Add(new ValidationIssue(
            itemContext,
            IssueSeverity.Error,
            $"Legacy nested data shape больше не допустим для UpdateGuardians.{command}",
            code: $"guardian_{command.ToLowerInvariant()}_legacy_shape",
            section: $"UpdateGuardians.{command}",
            expected: expected,
            actual: "Nested data object",
            repairHint: repairHint));
    }

    private HashSet<string> CollectKnownGuardianIds(JsonElement root)
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var preTurnGuardiansJson = ReadPreTurnTrackedFileSync("game_state/meta/guardians.json");
        if (!string.IsNullOrWhiteSpace(preTurnGuardiansJson))
        {
            try
            {
                using var doc = JsonDocument.Parse(preTurnGuardiansJson);
                CollectGuardianIdsFromStateRoot(doc.RootElement, ids, includeCommandSurfaces: false);
            }
            catch
            {
                // ignored
            }
        }

        var ignoredNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        CollectCreatedGuardianReferencesFromStateRoot(root, ids, ignoredNames);

        return ids;
    }

    private static void CollectGuardianIdsFromStateRoot(JsonElement root, HashSet<string> ids, bool includeCommandSurfaces = true)
    {
        if (root.TryGetProperty("guardians", out var guardians) && guardians.ValueKind == JsonValueKind.Array)
        {
            foreach (var guardian in guardians.EnumerateArray())
            {
                var guardianId = GetFirstNonEmptyString(guardian, "guardianId", "id");
                if (!string.IsNullOrWhiteSpace(guardianId))
                    ids.Add(guardianId);
            }
        }

        if (root.TryGetProperty("activeGuardian", out var activeGuardian) && activeGuardian.ValueKind == JsonValueKind.Object)
        {
            var guardianId = GetFirstNonEmptyString(activeGuardian, "guardianId", "id");
                if (!string.IsNullOrWhiteSpace(guardianId))
                    ids.Add(guardianId);
        }

        if (includeCommandSurfaces &&
            root.TryGetProperty("UpdateGuardians", out var updates) &&
            updates.ValueKind == JsonValueKind.Array)
        {
            foreach (var command in updates.EnumerateArray())
            {
                if (command.ValueKind != JsonValueKind.Object)
                    continue;

                var commandName = GetFirstNonEmptyString(command, "command");
                var payload = string.Equals(commandName, "create", StringComparison.OrdinalIgnoreCase) &&
                              command.TryGetProperty("data", out var data) &&
                              data.ValueKind == JsonValueKind.Object
                    ? data
                    : command;

                var guardianId = GetFirstNonEmptyString(payload, "guardianId", "id");
                if (!string.IsNullOrWhiteSpace(guardianId))
                    ids.Add(guardianId);
            }
        }
    }

    private void ValidateGuardianMusingsCommand(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        if (!item.TryGetProperty("musings", out var musings))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.musings",
                IssueSeverity.Error,
                "addMusings должен содержать top-level массив musings",
                code: "guardian_add_musings_missing_array",
                section: "UpdateGuardians.addMusings",
                expected: "Top-level musings array",
                actual: "missing musings",
                repairHint: "Передай addMusings как массив musings[] с объектами turn/topic/mood/text, а не как одиночную строку или nested data shape."));
            return;
        }

        RequireArrayOfObjects(musings, $"{itemContext}.musings", issues);
        if (musings.ValueKind != JsonValueKind.Array)
            return;

        if (musings.GetArrayLength() == 0 || musings.GetArrayLength() > 2)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.musings",
                IssueSeverity.Error,
                "addMusings должен содержать 1 или 2 новых размышления Хранителя за ход",
                code: "guardian_add_musings_invalid_count",
                section: "UpdateGuardians.addMusings",
                expected: "1..2 musings per turn",
                actual: musings.GetArrayLength().ToString(),
                repairHint: "Передавай в addMusings только 1-2 новые записи за текущий ход. Старые размышления хранятся в canonical guardians.json и не должны пересылаться заново."));
            if (musings.GetArrayLength() == 0)
                return;
        }

        var index = 0;
        foreach (var musing in musings.EnumerateArray())
        {
            var musingContext = $"{itemContext}.musings[{index++}]";
            if (!RequireObject(musing, musingContext, issues))
                continue;

            if (!musing.TryGetProperty("turn", out var turn) ||
                turn.ValueKind != JsonValueKind.Number ||
                !turn.TryGetInt32(out _))
            {
                issues.Add(new ValidationIssue(
                    $"{musingContext}.turn",
                    IssueSeverity.Error,
                    "Guardian musing должен содержать integer turn",
                    code: "guardian_musing_missing_turn",
                    section: "UpdateGuardians.addMusings",
                    expected: "Integer turn",
                    actual: musing.TryGetProperty("turn", out var actualTurn) ? actualTurn.ValueKind.ToString() : "missing",
                    repairHint: "Каждая запись musings[] должна явно указывать номер хода в поле turn, чтобы журнал размышлений был отсортирован и воспроизводим."));
            }

            var topic = RequireString(musing, musingContext, issues, "topic");
            var mood = RequireString(musing, musingContext, issues, "mood");
            if (!string.IsNullOrWhiteSpace(topic) && !AllowedGuardianMusingTopics.Contains(topic))
            {
                issues.Add(new ValidationIssue(
                    $"{musingContext}.topic",
                    IssueSeverity.Error,
                    "Guardian musing.topic должен быть одним из canonical topic enums",
                    code: "guardian_musing_invalid_topic",
                    section: "UpdateGuardians.addMusings",
                    expected: string.Join(" | ", AllowedGuardianMusingTopics),
                    actual: topic,
                    repairHint: "Используй topic только из guardian inner-life contract: soul_assessment, domain_insight, guardian_politics, chaos_sea, personal_reflection, quest_planning."));
            }

            if (!string.IsNullOrWhiteSpace(mood) && !AllowedGuardianMusingMoods.Contains(mood))
            {
                issues.Add(new ValidationIssue(
                    $"{musingContext}.mood",
                    IssueSeverity.Error,
                    "Guardian musing.mood должен быть одним из canonical mood enums",
                    code: "guardian_musing_invalid_mood",
                    section: "UpdateGuardians.addMusings",
                    expected: string.Join(" | ", AllowedGuardianMusingMoods),
                    actual: mood,
                    repairHint: "Используй mood только из documented musings mood palette, а не произвольную строку."));
            }
            if (!HasAnyNonEmptyString(musing, "thought", "text"))
            {
                issues.Add(new ValidationIssue(
                    musingContext,
                    IssueSeverity.Error,
                    "Guardian musing должен содержать thought или text",
                    code: "guardian_musing_missing_text",
                    section: "UpdateGuardians.addMusings",
                    expected: "thought or text",
                    actual: "missing textual musing payload",
                    repairHint: "Заполни thought или text у каждой записи musings[], чтобы клиенту было что показывать в журнале размышлений Хранителя."));
            }
        }
    }

    private void ValidateGuardianCurrentProjectObject(JsonElement currentProject, string projectContext, List<ValidationIssue> issues)
    {
        RequireString(currentProject, projectContext, issues, "projectId");
        if (!HasAnyNonEmptyString(currentProject, "projectName", "name"))
        {
            issues.Add(new ValidationIssue(
                projectContext,
                IssueSeverity.Error,
                "currentProject должен содержать projectName или name"));
        }

        RequireString(currentProject, projectContext, issues, "description");
        ValidateNonNegativeIntegerField(currentProject, projectContext, issues, "progressPercent", "UpdateGuardians.updateProject");
        if (currentProject.TryGetProperty("progressPercent", out var progressPercent) &&
            progressPercent.ValueKind == JsonValueKind.Number &&
            progressPercent.TryGetInt32(out var parsedProgressPercent) &&
            (parsedProgressPercent < 0 || parsedProgressPercent > 100))
        {
            issues.Add(new ValidationIssue(
                $"{projectContext}.progressPercent",
                IssueSeverity.Error,
                "progressPercent должен быть в диапазоне 0..100"));
        }

        if (!currentProject.TryGetProperty("estimatedTurnsLeft", out _) &&
            !currentProject.TryGetProperty("estimatedCompletionTurn", out _))
        {
            issues.Add(new ValidationIssue(
                projectContext,
                IssueSeverity.Error,
                "currentProject должен содержать estimatedTurnsLeft или estimatedCompletionTurn"));
        }

        if (currentProject.TryGetProperty("estimatedTurnsLeft", out _))
            ValidateNonNegativeIntegerField(currentProject, projectContext, issues, "estimatedTurnsLeft", "UpdateGuardians.updateProject");
        if (currentProject.TryGetProperty("estimatedCompletionTurn", out _))
            ValidateNonNegativeIntegerField(currentProject, projectContext, issues, "estimatedCompletionTurn", "UpdateGuardians.updateProject");

        if (!currentProject.TryGetProperty("playerCanAssist", out var playerCanAssist) ||
            playerCanAssist.ValueKind is not (JsonValueKind.True or JsonValueKind.False))
        {
            issues.Add(new ValidationIssue(
                $"{projectContext}.playerCanAssist",
                IssueSeverity.Error,
                "currentProject должен содержать boolean playerCanAssist"));
        }

        ValidateOptionalString(currentProject, projectContext, issues, "assistDescription");
    }

    private void ValidateGuardianLoreFragmentObject(JsonElement loreFragment, string fragmentContext, List<ValidationIssue> issues, bool allowNullableContent)
    {
        RequireString(loreFragment, fragmentContext, issues, "fragmentId");
        var category = RequireString(loreFragment, fragmentContext, issues, "category");
        RequireString(loreFragment, fragmentContext, issues, "title");
        if (!allowNullableContent)
        {
            RequireString(loreFragment, fragmentContext, issues, "content");
        }
        else if (loreFragment.TryGetProperty("content", out var content) &&
                 content.ValueKind != JsonValueKind.Null &&
                 (content.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(content.GetString())))
        {
            issues.Add(new ValidationIssue(
                $"{fragmentContext}.content",
                IssueSeverity.Error,
                "Stored guardian lore fragment content должен быть непустой строкой или null для ещё не раскрытого fragment",
                code: "guardian_lore_fragment_invalid_content",
                section: "Guardians",
                repairHint: "Для locked pre-planned lore fragment оставляй content = null; для unlocked fragment передавай непустой content."));
        }
        ValidateNonNegativeIntegerField(loreFragment, fragmentContext, issues, "requiredReputation", "UpdateGuardians.unlockLore");

        if (!string.IsNullOrWhiteSpace(category) && !AllowedGuardianLoreFragmentCategories.Contains(category))
        {
            issues.Add(new ValidationIssue(
                $"{fragmentContext}.category",
                IssueSeverity.Error,
                "Guardian loreFragment.category должен быть одним из canonical enum значений",
                code: "guardian_lore_fragment_invalid_category",
                section: "UpdateGuardians.unlockLore",
                expected: string.Join(" | ", AllowedGuardianLoreFragmentCategories),
                actual: category,
                repairHint: "Используй category только из guardian lore fragment contract."));
        }

        if (TryReadInt(loreFragment, "requiredReputation", out var requiredReputation) &&
            !AllowedGuardianLoreFragmentReputationThresholds.Contains(requiredReputation))
        {
            issues.Add(new ValidationIssue(
                $"{fragmentContext}.requiredReputation",
                IssueSeverity.Error,
                "Guardian loreFragment.requiredReputation должен совпадать с canonical reputation unlock threshold",
                code: "guardian_lore_fragment_invalid_required_reputation",
                section: "UpdateGuardians.unlockLore",
                expected: "0 | 50 | 130 | 230",
                actual: requiredReputation.ToString(),
                repairHint: "Используй только reputation thresholds 0, 50, 130 или 230 для unlockLore fragments."));
        }
    }

    private void ValidateGuardianMoodObject(JsonElement mood, string moodContext, List<ValidationIssue> issues)
    {
        var current = RequireString(mood, moodContext, issues, "current");
        ValidatePositiveIntegerField(mood, moodContext, issues, "intensity");
        RequireString(mood, moodContext, issues, "reason");
        if (!mood.TryGetProperty("since", out _))
        {
            issues.Add(new ValidationIssue(
                $"{moodContext}.since",
                IssueSeverity.Error,
                "Guardian mood object должен содержать since",
                code: "guardian_mood_missing_since",
                section: "UpdateGuardians.setMood",
                expected: "non-negative since marker",
                actual: "missing",
                repairHint: "Добавь mood.since в canonical guardian mood object, как это описано в guardian inner-life contract."));
        }
        else
        {
            ValidateNonNegativeIntegerField(mood, moodContext, issues, "since", "UpdateGuardians.setMood");
        }

        if (!string.IsNullOrWhiteSpace(current) && !AllowedGuardianMoodStates.Contains(current))
        {
            issues.Add(new ValidationIssue(
                $"{moodContext}.current",
                IssueSeverity.Error,
                "Guardian mood.current должен быть одним из canonical enum значений",
                code: "guardian_mood_invalid_current",
                section: "UpdateGuardians.setMood",
                expected: string.Join(" | ", AllowedGuardianMoodStates),
                actual: current,
                repairHint: "Используй mood.current только из guardian mood contract."));
        }

        if (TryReadInt(mood, "intensity", out var intensity) && (intensity < 1 || intensity > 100))
        {
            issues.Add(new ValidationIssue(
                $"{moodContext}.intensity",
                IssueSeverity.Error,
                "Guardian mood.intensity должен быть в диапазоне 1..100",
                code: "guardian_mood_intensity_out_of_bounds",
                section: "UpdateGuardians.setMood",
                expected: "1..100",
                actual: intensity.ToString(),
                repairHint: "Используй canonical 1-100 intensity scale для guardian mood."));
        }
    }

    private void ValidateGuardianStoredInnerLifeState(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("currentProject", out var currentProject) || currentProject.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.currentProject",
                IssueSeverity.Error,
                "Canonical guardian state должен всегда содержать currentProject",
                code: "guardian_state_missing_current_project",
                section: "Guardians",
                repairHint: "Для каждого Хранителя сохраняй ровно один active currentProject в stored guardian state."));
        }
        else if (RequireObject(currentProject, $"{guardianContext}.currentProject", issues))
        {
            ValidateGuardianCurrentProjectObject(currentProject, $"{guardianContext}.currentProject", issues);
        }

        if (!guardian.TryGetProperty("mood", out var mood) || mood.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.mood",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать mood object",
                code: "guardian_state_missing_mood",
                section: "Guardians",
                repairHint: "Сохраняй в guardian state текущий mood object с current, intensity, reason и при наличии since."));
        }
        else if (RequireObject(mood, $"{guardianContext}.mood", issues))
        {
            ValidateGuardianMoodObject(mood, $"{guardianContext}.mood", issues);
        }

        if (!guardian.TryGetProperty("loreFragments", out var loreFragments) || loreFragments.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.loreFragments",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать pre-planned loreFragments array",
                code: "guardian_state_missing_lore_fragments",
                section: "Guardians",
                repairHint: "Сохраняй в guardian state массив loreFragments с полным набором pre-planned fragment objects."));
        }
        else
        {
            RequireArrayOfObjects(loreFragments, $"{guardianContext}.loreFragments", issues);
            if (loreFragments.ValueKind == JsonValueKind.Array)
            {
                if (loreFragments.GetArrayLength() < 7)
                {
                    issues.Add(new ValidationIssue(
                        $"{guardianContext}.loreFragments",
                        IssueSeverity.Error,
                        "Canonical guardian state должен хранить как минимум 7 pre-planned lore fragments",
                        code: "guardian_state_lore_fragments_below_minimum",
                        section: "Guardians",
                        expected: ">= 7 lore fragments",
                        actual: loreFragments.GetArrayLength().ToString(),
                        repairHint: "Добавь pre-planned lore fragments в guardian state до минимального набора из 7 записей."));
                }

                var index = 0;
                foreach (var loreFragment in loreFragments.EnumerateArray())
                    ValidateGuardianLoreFragmentObject(loreFragment, $"{guardianContext}.loreFragments[{index++}]", issues, allowNullableContent: true);
            }
        }

        if (guardian.TryGetProperty("musings", out var musings) &&
            musings.ValueKind != JsonValueKind.Null)
        {
            RequireArrayOfObjects(musings, $"{guardianContext}.musings", issues);
            if (musings.ValueKind == JsonValueKind.Array)
            {
                if (musings.GetArrayLength() > 15)
                {
                    issues.Add(new ValidationIssue(
                        $"{guardianContext}.musings",
                        IssueSeverity.Error,
                        "Canonical guardian musings не должны хранить более 15 последних записей",
                        code: "guardian_state_musings_limit_exceeded",
                        section: "Guardians",
                        expected: "<= 15 musings entries",
                        actual: musings.GetArrayLength().ToString(),
                        repairHint: "Обрежь canonical musings[] до 15 самых новых записей, как требует Guardian inner-life contract."));
                }

                var index = 0;
                foreach (var musing in musings.EnumerateArray())
                {
                    var musingContext = $"{guardianContext}.musings[{index++}]";
                    if (!RequireObject(musing, musingContext, issues))
                        continue;

                    if (!musing.TryGetProperty("turn", out var turn) ||
                        turn.ValueKind != JsonValueKind.Number ||
                        !turn.TryGetInt32(out _))
                    {
                        issues.Add(new ValidationIssue(
                            $"{musingContext}.turn",
                            IssueSeverity.Error,
                            "Guardian musing должен содержать integer turn",
                            code: "guardian_musing_missing_turn",
                            section: "Guardians",
                            expected: "Integer turn",
                            actual: musing.TryGetProperty("turn", out var actualTurn) ? actualTurn.ValueKind.ToString() : "missing",
                            repairHint: "Каждая canonical musings[] entry должна явно указывать turn, чтобы журнал размышлений был отсортирован и воспроизводим."));
                    }

                    var topic = RequireString(musing, musingContext, issues, "topic");
                    var moodValue = RequireString(musing, musingContext, issues, "mood");
                    if (!string.IsNullOrWhiteSpace(topic) && !AllowedGuardianMusingTopics.Contains(topic))
                    {
                        issues.Add(new ValidationIssue(
                            $"{musingContext}.topic",
                            IssueSeverity.Error,
                            "Guardian musing.topic должен быть одним из canonical topic enums",
                            code: "guardian_musing_invalid_topic",
                            section: "Guardians",
                            expected: string.Join(" | ", AllowedGuardianMusingTopics),
                            actual: topic,
                            repairHint: "Используй topic только из guardian inner-life contract: soul_assessment, domain_insight, guardian_politics, chaos_sea, personal_reflection, quest_planning."));
                    }

                    if (!string.IsNullOrWhiteSpace(moodValue) && !AllowedGuardianMusingMoods.Contains(moodValue))
                    {
                        issues.Add(new ValidationIssue(
                            $"{musingContext}.mood",
                            IssueSeverity.Error,
                            "Guardian musing.mood должен быть одним из canonical mood enums",
                            code: "guardian_musing_invalid_mood",
                            section: "Guardians",
                            expected: string.Join(" | ", AllowedGuardianMusingMoods),
                            actual: moodValue,
                            repairHint: "Используй mood только из documented musings mood palette, а не произвольную строку."));
                    }

                    if (!HasAnyNonEmptyString(musing, "thought", "text"))
                    {
                        issues.Add(new ValidationIssue(
                            musingContext,
                            IssueSeverity.Error,
                            "Guardian musing должен содержать thought или text",
                            code: "guardian_musing_missing_text",
                            section: "Guardians",
                            expected: "thought or text",
                            actual: "missing textual musing payload",
                            repairHint: "Заполни thought или text у каждой canonical musings[] entry, чтобы клиенту было что показывать в журнале размышлений Хранителя."));
                    }
                }
            }
        }
    }

    private void ValidateGuardianStateData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        var guardiansById = new Dictionary<string, (JsonElement Guardian, string Context)>(StringComparer.OrdinalIgnoreCase);

        if (root.TryGetProperty("guardians", out var guardians) && guardians.ValueKind == JsonValueKind.Array)
        {
            var index = 0;
            foreach (var guardian in guardians.EnumerateArray())
            {
                var guardianContext = $"{contextPrefix}.guardians[{index++}]";
                if (!RequireObject(guardian, guardianContext, issues))
                    continue;

                ValidateGuardianCanonicalObject(guardian, guardianContext, issues);

                if (guardian.TryGetProperty("guardianId", out var guardianIdNode) &&
                    guardianIdNode.ValueKind == JsonValueKind.String &&
                    !string.IsNullOrWhiteSpace(guardianIdNode.GetString()))
                {
                    guardiansById[guardianIdNode.GetString()!] = (guardian, guardianContext);
                }
            }
        }

        if (root.TryGetProperty("activeGuardian", out var activeGuardian) && activeGuardian.ValueKind == JsonValueKind.Object)
        {
            const string activeGuardianContextSuffix = ".activeGuardian";
            var activeGuardianContext = $"{contextPrefix}{activeGuardianContextSuffix}";
            ValidateGuardianCanonicalObject(activeGuardian, activeGuardianContext, issues);

            if (activeGuardian.TryGetProperty("guardianId", out var activeGuardianIdNode) &&
                activeGuardianIdNode.ValueKind == JsonValueKind.String &&
                !string.IsNullOrWhiteSpace(activeGuardianIdNode.GetString()) &&
                guardiansById.TryGetValue(activeGuardianIdNode.GetString()!, out var guardianMatch))
            {
                CompareGuardianGachaState(activeGuardian, activeGuardianContext, guardianMatch.Guardian, guardianMatch.Context, issues);
                CompareGuardianTradeState(activeGuardian, activeGuardianContext, guardianMatch.Guardian, guardianMatch.Context, issues);
            }
        }
    }

    private void ValidateGuardianGachaState(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("gachaSystem", out var gachaSystem) || gachaSystem.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.gachaSystem",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать gachaSystem",
                code: "guardian_state_missing_gacha_system",
                section: "Guardians",
                repairHint: "Сохраняй в guardian state gachaSystem с chargesPerReturn, chargesUsedThisReturn и gachaHistory."));
            return;
        }

        if (!RequireObject(gachaSystem, $"{guardianContext}.gachaSystem", issues))
            return;

        var gachaContext = $"{guardianContext}.gachaSystem";
        ValidateNonNegativeNumberField(gachaSystem, gachaContext, issues, "chargesPerReturn");
        ValidateNonNegativeNumberField(gachaSystem, gachaContext, issues, "chargesUsedThisReturn");

        if (!gachaSystem.TryGetProperty("gachaHistory", out var gachaHistory) || gachaHistory.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{gachaContext}.gachaHistory",
                IssueSeverity.Error,
                "Canonical guardian gachaSystem должен содержать gachaHistory array",
                code: "guardian_gacha_history_missing",
                section: "Guardians",
                repairHint: "Сохраняй gachaHistory как canonical массив попыток с timestamp, costInFeathers, relicId и finalRarity."));
        }
        else
        {
            RequireArrayOfObjects(gachaHistory, $"{gachaContext}.gachaHistory", issues);
            if (gachaHistory.ValueKind == JsonValueKind.Array)
            {
                var historyIndex = 0;
                foreach (var entry in gachaHistory.EnumerateArray())
                {
                    var entryContext = $"{gachaContext}.gachaHistory[{historyIndex++}]";
                    if (!RequireObject(entry, entryContext, issues))
                        continue;

                    var timestamp = RequireString(entry, entryContext, issues, "timestamp");
                    ValidatePositiveNumberField(entry, entryContext, issues, "costInFeathers");
                    RequireString(entry, entryContext, issues, "relicId");
                    var finalRarity = RequireString(entry, entryContext, issues, "finalRarity");

                    if (!string.IsNullOrWhiteSpace(timestamp) && !DateTimeOffset.TryParse(timestamp, out _))
                    {
                        issues.Add(new ValidationIssue(
                            $"{entryContext}.timestamp",
                            IssueSeverity.Error,
                            "Guardian gachaHistory.timestamp должен быть ISO 8601 timestamp",
                            code: "guardian_gacha_history_invalid_timestamp",
                            section: "Guardians",
                            expected: "ISO 8601 timestamp",
                            actual: timestamp,
                            repairHint: "Сохраняй timestamp в gachaHistory как ISO 8601 строку."));
                    }

                    if (!string.IsNullOrWhiteSpace(finalRarity) && GetRarityRank(finalRarity) == 0)
                    {
                        issues.Add(new ValidationIssue(
                            $"{entryContext}.finalRarity",
                            IssueSeverity.Error,
                            "Guardian gachaHistory.finalRarity должен быть canonical rarity",
                            code: "guardian_gacha_history_invalid_final_rarity",
                            section: "Guardians",
                            expected: "common | uncommon | rare | epic | legendary",
                            actual: finalRarity,
                            repairHint: "Сохраняй finalRarity как одну из canonical rarity tiers."));
                    }
                }
            }
        }

        if (guardian.TryGetProperty("relationshipData", out var relationshipData) &&
            relationshipData.ValueKind == JsonValueKind.Object &&
            relationshipData.TryGetProperty("currentReputation", out var currentReputation) &&
            currentReputation.ValueKind == JsonValueKind.Number &&
            currentReputation.TryGetInt32(out var parsedReputation) &&
            gachaSystem.TryGetProperty("chargesPerReturn", out var chargesPerReturnNode) &&
            chargesPerReturnNode.ValueKind == JsonValueKind.Number &&
            chargesPerReturnNode.TryGetInt32(out var chargesPerReturn))
        {
            var expectedCharges = GetExpectedGuardianGachaCharges(parsedReputation);
            if (chargesPerReturn != expectedCharges)
            {
                issues.Add(new ValidationIssue(
                    $"{gachaContext}.chargesPerReturn",
                    IssueSeverity.Error,
                    "Guardian gachaSystem.chargesPerReturn должен совпадать с reputation tier",
                    code: "guardian_gacha_charges_tier_mismatch",
                    section: "Guardians",
                    expected: expectedCharges.ToString(),
                    actual: chargesPerReturn.ToString(),
                    repairHint: "Синхронизируй chargesPerReturn с guardian reputation tier: Hostile=0, Wary/Neutral=1, Friendly=2, Devoted/Legendary=3."));
            }
        }

        if (gachaSystem.TryGetProperty("chargesPerReturn", out var chargesPerReturnNodeForUsage) &&
            gachaSystem.TryGetProperty("chargesUsedThisReturn", out var chargesUsedNode) &&
            chargesPerReturnNodeForUsage.ValueKind == JsonValueKind.Number &&
            chargesUsedNode.ValueKind == JsonValueKind.Number &&
            chargesPerReturnNodeForUsage.TryGetInt32(out var chargesPerReturnForUsage) &&
            chargesUsedNode.TryGetInt32(out var chargesUsedThisReturn) &&
            chargesUsedThisReturn > chargesPerReturnForUsage)
        {
            issues.Add(new ValidationIssue(
                $"{gachaContext}.chargesUsedThisReturn",
                IssueSeverity.Error,
                "chargesUsedThisReturn не может превышать chargesPerReturn"));
        }
    }

    private void ValidateGuardianCanonicalObject(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        RequireString(guardian, guardianContext, issues, "guardianId");
        RequireString(guardian, guardianContext, issues, "name");
        var domain = RequireString(guardian, guardianContext, issues, "domain");
        if (!string.IsNullOrWhiteSpace(domain) && !AllowedGuardianDomains.Contains(domain))
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.domain",
                IssueSeverity.Error,
                "Guardian domain должен быть одним из canonical enum значений",
                code: "guardian_invalid_domain",
                section: "Guardians",
                expected: string.Join(" | ", AllowedGuardianDomains),
                actual: domain,
                repairHint: "Используй для Хранителя только canonical domain: Combat, Magic, Trade, Social, Crafting, Survival или Knowledge."));
        }

        ValidateGuardianPersonalityProfile(guardian, guardianContext, issues);
        ValidateGuardianRelationshipData(guardian, guardianContext, issues);
        ValidateGuardianQuestManagement(guardian, guardianContext, issues);
        ValidateGuardianGachaState(guardian, guardianContext, issues);
        ValidateGuardianTradeState(guardian, guardianContext, issues);
        ValidateGuardianStoredInnerLifeState(guardian, guardianContext, issues);
    }

    private static int GetExpectedGuardianGachaCharges(int currentReputation)
    {
        if (currentReputation <= -51)
            return 0;
        if (currentReputation <= 49)
            return 1;
        if (currentReputation <= 129)
            return 2;
        return 3;
    }

    private void ValidateGuardianPersonalityProfile(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("personalityProfile", out var personalityProfile) ||
            personalityProfile.ValueKind != JsonValueKind.Object)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.personalityProfile",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать personalityProfile object",
                code: "guardian_missing_personality_profile",
                section: "Guardians",
                expected: "personalityProfile object with archetype, speechPattern, coreValues",
                actual: guardian.TryGetProperty("personalityProfile", out var actualProfile) ? actualProfile.ValueKind.ToString() : "missing",
                repairHint: "Сохраняй для каждого Хранителя personalityProfile с archetype, speechPattern и массивом coreValues, как требует Block 32."));
            return;
        }

        var profileContext = $"{guardianContext}.personalityProfile";
        RequireString(personalityProfile, profileContext, issues, "archetype");
        RequireString(personalityProfile, profileContext, issues, "speechPattern");

        if (!personalityProfile.TryGetProperty("coreValues", out var coreValues) || coreValues.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{profileContext}.coreValues",
                IssueSeverity.Error,
                "Guardian personalityProfile должен содержать coreValues array",
                code: "guardian_personality_missing_core_values",
                section: "Guardians",
                expected: "array of 3..5 strings",
                actual: "missing",
                repairHint: "Сохраняй coreValues как массив из 3-5 ценностей, согласованных с доменом и архетипом Хранителя."));
            return;
        }

        RequireArrayOfStrings(coreValues, $"{profileContext}.coreValues", issues);
        if (coreValues.ValueKind == JsonValueKind.Array)
        {
            var count = coreValues.GetArrayLength();
            if (count < 3 || count > 5)
            {
                issues.Add(new ValidationIssue(
                    $"{profileContext}.coreValues",
                    IssueSeverity.Error,
                    "Guardian personalityProfile.coreValues должен содержать 3-5 ценностей",
                    code: "guardian_personality_core_values_count_invalid",
                    section: "Guardians",
                    expected: "3..5 strings",
                    actual: count.ToString(),
                    repairHint: "Используй для coreValues ровно 3-5 значимых ценностей, а не пустой или перегруженный список."));
            }
        }
    }

    private void ValidateGuardianRelationshipData(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("relationshipData", out var relationshipData) ||
            relationshipData.ValueKind != JsonValueKind.Object)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.relationshipData",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать relationshipData object",
                code: "guardian_missing_relationship_data",
                section: "Guardians",
                expected: "relationshipData object with currentReputation, reputationHistory, lastInteraction",
                actual: guardian.TryGetProperty("relationshipData", out var actualRelationshipData) ? actualRelationshipData.ValueKind.ToString() : "missing",
                repairHint: "Сохраняй relationshipData с currentReputation, reputationHistory и lastInteraction для каждого Хранителя."));
            return;
        }

        var relationshipContext = $"{guardianContext}.relationshipData";
        if (!relationshipData.TryGetProperty("currentReputation", out var currentReputation) ||
            currentReputation.ValueKind != JsonValueKind.Number ||
            !currentReputation.TryGetInt32(out var parsedReputation))
        {
            issues.Add(new ValidationIssue(
                $"{relationshipContext}.currentReputation",
                IssueSeverity.Error,
                "Guardian relationshipData должен содержать integer currentReputation",
                code: "guardian_relationship_missing_reputation",
                section: "Guardians",
                expected: "Integer currentReputation within -100..300",
                actual: relationshipData.TryGetProperty("currentReputation", out var actualValue) ? actualValue.ValueKind.ToString() : "missing",
                repairHint: "Сохраняй canonical guardian relationshipData.currentReputation как integer из диапазона -100..300."));
            return;
        }

        if (parsedReputation < -100 || parsedReputation > 300)
        {
            issues.Add(new ValidationIssue(
                $"{relationshipContext}.currentReputation",
                IssueSeverity.Error,
                "Guardian currentReputation должен быть в диапазоне -100..300",
                code: "guardian_relationship_reputation_out_of_bounds",
                section: "Guardians",
                expected: "-100..300",
                actual: parsedReputation.ToString(),
                repairHint: "Не выводи репутацию Хранителя за пределы canonical guardian scale -100..300."));
        }

        if (!relationshipData.TryGetProperty("reputationHistory", out var reputationHistory) ||
            reputationHistory.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{relationshipContext}.reputationHistory",
                IssueSeverity.Error,
                "Guardian relationshipData должен содержать reputationHistory array",
                code: "guardian_relationship_missing_history",
                section: "Guardians",
                expected: "reputationHistory array",
                actual: "missing",
                repairHint: "Сохраняй reputationHistory как массив изменений репутации, даже если он пока пустой."));
        }
        else
        {
            RequireArrayOfObjects(reputationHistory, $"{relationshipContext}.reputationHistory", issues);
            if (reputationHistory.ValueKind == JsonValueKind.Array)
            {
                var historyIndex = 0;
                foreach (var entry in reputationHistory.EnumerateArray())
                {
                    var entryContext = $"{relationshipContext}.reputationHistory[{historyIndex++}]";
                    if (!RequireObject(entry, entryContext, issues))
                        continue;

                    var timestamp = RequireString(entry, entryContext, issues, "timestamp");
                    ValidateIntegerField(entry, entryContext, issues, "change");
                    RequireString(entry, entryContext, issues, "reason");
                    ValidateOptionalString(entry, entryContext, issues, "questId");
                    if (!string.IsNullOrWhiteSpace(timestamp) && !DateTimeOffset.TryParse(timestamp, out _))
                    {
                        issues.Add(new ValidationIssue(
                            $"{entryContext}.timestamp",
                            IssueSeverity.Error,
                            "Guardian reputationHistory.timestamp должен быть ISO 8601 timestamp",
                            code: "guardian_relationship_history_invalid_timestamp",
                            section: "Guardians",
                            expected: "ISO 8601 timestamp",
                            actual: timestamp,
                            repairHint: "Сохраняй timestamp в reputationHistory как ISO 8601 строку для воспроизводимой chronology."));
                    }
                }
            }
        }

        if (!relationshipData.TryGetProperty("lastInteraction", out var lastInteraction))
        {
            issues.Add(new ValidationIssue(
                $"{relationshipContext}.lastInteraction",
                IssueSeverity.Error,
                "Guardian relationshipData должен содержать lastInteraction",
                code: "guardian_relationship_missing_last_interaction",
                section: "Guardians",
                expected: "ISO 8601 timestamp or null",
                actual: "missing",
                repairHint: "Сохраняй lastInteraction как ISO timestamp последнего meaningful interaction или null, если контакта ещё не было."));
        }
        else if (lastInteraction.ValueKind != JsonValueKind.Null)
        {
            var lastInteractionValue = RequireString(relationshipData, relationshipContext, issues, "lastInteraction");
            if (!string.IsNullOrWhiteSpace(lastInteractionValue) && !DateTimeOffset.TryParse(lastInteractionValue, out _))
            {
                issues.Add(new ValidationIssue(
                    $"{relationshipContext}.lastInteraction",
                    IssueSeverity.Error,
                    "Guardian relationshipData.lastInteraction должен быть ISO 8601 timestamp или null",
                    code: "guardian_relationship_invalid_last_interaction",
                    section: "Guardians",
                    expected: "ISO 8601 timestamp or null",
                    actual: lastInteractionValue,
                    repairHint: "Используй для lastInteraction ISO 8601 timestamp или null, если взаимодействий ещё не было."));
            }
        }
    }

    private void ValidateGuardianQuestManagement(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("questManagement", out var questManagement) ||
            questManagement.ValueKind != JsonValueKind.Object)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.questManagement",
                IssueSeverity.Error,
                "Canonical guardian state должен содержать questManagement object",
                code: "guardian_missing_quest_management",
                section: "Guardians",
                expected: "questManagement object with availableQuests, activeQuests and completedQuests",
                actual: guardian.TryGetProperty("questManagement", out var actualQuestManagement) ? actualQuestManagement.ValueKind.ToString() : "missing",
                repairHint: "Сохраняй questManagement с массивами availableQuests, activeQuests и completedQuests даже для нового Хранителя."));
            return;
        }

        var questContext = $"{guardianContext}.questManagement";
        if (!questManagement.TryGetProperty("availableQuests", out var availableQuests) ||
            availableQuests.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{questContext}.availableQuests",
                IssueSeverity.Error,
                "Guardian questManagement должен содержать availableQuests array",
                code: "guardian_quest_management_missing_available_quests",
                section: "Guardians",
                expected: "availableQuests array",
                actual: "missing",
                repairHint: "Сохраняй availableQuests как массив, даже если у Хранителя сейчас нет доступных квестов."));
        }
        else
        {
            RequireArrayOfObjects(availableQuests, $"{questContext}.availableQuests", issues);
            if (availableQuests.ValueKind == JsonValueKind.Array && availableQuests.GetArrayLength() > 3)
            {
                issues.Add(new ValidationIssue(
                    $"{questContext}.availableQuests",
                    IssueSeverity.Error,
                    "Guardian questManagement не может держать больше 3 доступных квестов",
                    code: "guardian_available_quests_limit_exceeded",
                    section: "Guardians",
                    expected: "0..3 available quests",
                    actual: availableQuests.GetArrayLength().ToString(),
                    repairHint: "Оставляй у одного Хранителя не более 3 одновременных availableQuests в canonical guardian state."));
            }
        }

        if (!questManagement.TryGetProperty("activeQuests", out var activeQuests) ||
            activeQuests.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{questContext}.activeQuests",
                IssueSeverity.Error,
                "Guardian questManagement должен содержать activeQuests array",
                code: "guardian_quest_management_missing_active_quests",
                section: "Guardians",
                expected: "activeQuests array",
                actual: "missing",
                repairHint: "Сохраняй activeQuests как массив, даже если у Хранителя сейчас нет активных квестов."));
        }
        else
        {
            RequireArrayOfObjects(activeQuests, $"{questContext}.activeQuests", issues);
        }

        if (!questManagement.TryGetProperty("completedQuests", out var completedQuests) ||
            completedQuests.ValueKind == JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{questContext}.completedQuests",
                IssueSeverity.Error,
                "Guardian questManagement должен содержать completedQuests array",
                code: "guardian_quest_management_missing_completed_quests",
                section: "Guardians",
                expected: "completedQuests array",
                actual: "missing",
                repairHint: "Сохраняй completedQuests как массив завершённых квестов, даже если он пока пустой."));
        }
        else
        {
            RequireArrayOfObjects(completedQuests, $"{questContext}.completedQuests", issues);
            if (completedQuests.ValueKind == JsonValueKind.Array)
            {
                var completedIndex = 0;
                foreach (var completedQuest in completedQuests.EnumerateArray())
                {
                    var completedContext = $"{questContext}.completedQuests[{completedIndex++}]";
                    if (!RequireObject(completedQuest, completedContext, issues))
                        continue;

                    RequireString(completedQuest, completedContext, issues, "questId");
                    var result = GetFirstNonEmptyString(completedQuest, "result");
                    if (!string.IsNullOrWhiteSpace(result) && !AllowedGuardianQuestOutcomes.Contains(result))
                    {
                        issues.Add(new ValidationIssue(
                            $"{completedContext}.result",
                            IssueSeverity.Error,
                            "Guardian completedQuests.result должен быть success, failure или partial",
                            code: "guardian_completed_quest_invalid_result",
                            section: "Guardians",
                            expected: "success | failure | partial",
                            actual: result,
                            repairHint: "Для completedQuests сохраняй result только как canonical guardian quest outcome: success, failure или partial."));
                    }

                    var completionDate = RequireString(completedQuest, completedContext, issues, "completionDate");
                    if (!string.IsNullOrWhiteSpace(completionDate) && !DateTimeOffset.TryParse(completionDate, out _))
                    {
                        issues.Add(new ValidationIssue(
                            $"{completedContext}.completionDate",
                            IssueSeverity.Error,
                            "Guardian completedQuests.completionDate должен быть ISO 8601 timestamp",
                            code: "guardian_completed_quest_invalid_completion_date",
                            section: "Guardians",
                            expected: "ISO 8601 timestamp",
                            actual: completionDate,
                            repairHint: "Для completedQuests сохраняй completionDate в ISO 8601 формате, чтобы chronological unlock logic и audit trail оставались стабильными."));
                    }
                }
            }
        }
    }

    private void ValidateGuardianTradeState(JsonElement guardian, string guardianContext, List<ValidationIssue> issues)
    {
        if (!guardian.TryGetProperty("tradeInventory", out var tradeInventory))
            return;

        if (tradeInventory.ValueKind != JsonValueKind.Object)
        {
            issues.Add(new ValidationIssue(
                $"{guardianContext}.tradeInventory",
                IssueSeverity.Warning,
                "Persisted guardian tradeInventory повреждён и будет regenerated client-side",
                code: "guardian_trade_inventory_root_malformed",
                section: "tradeInventory",
                expected: "object or omitted tradeInventory",
                actual: tradeInventory.ValueKind.ToString(),
                repairHint: "Не чини malformed persisted tradeInventory вручную через GM repair loop; клиент должен пересобрать stock для текущего trade cycle."));
            return;
        }

        var tradeContext = $"{guardianContext}.tradeInventory";
        var guardianDomain = GetFirstNonEmptyString(guardian, "domain");
        var tradeCycleId = GetFirstNonEmptyString(tradeInventory, "tradeCycleId");
        if (string.IsNullOrWhiteSpace(tradeCycleId))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.tradeCycleId",
                IssueSeverity.Warning,
                "Persisted guardian tradeInventory не содержит tradeCycleId и будет regenerated client-side",
                code: "guardian_trade_inventory_missing_trade_cycle_id",
                section: "tradeInventory",
                expected: "non-empty tradeCycleId",
                actual: "missing or empty",
                repairHint: "Не зацикливай GM на malformed persisted tradeInventory; клиент должен регенерировать stock по текущему trade cycle."));
            return;
        }

        var generatedAtUtc = GetFirstNonEmptyString(tradeInventory, "generatedAtUtc");
        if (string.IsNullOrWhiteSpace(generatedAtUtc))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.generatedAtUtc",
                IssueSeverity.Warning,
                "Persisted guardian tradeInventory не содержит generatedAtUtc и будет regenerated client-side",
                code: "guardian_trade_inventory_missing_generated_at",
                section: "tradeInventory",
                expected: "non-empty generatedAtUtc",
                actual: "missing or empty",
                repairHint: "Не чини malformed persisted guardian tradeInventory вручную; клиент должен пересобрать его для текущего цикла торговли."));
            return;
        }
        var generationTier = GetFirstNonEmptyString(tradeInventory, "generationReputationTier");
        if (string.IsNullOrWhiteSpace(generationTier))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.generationReputationTier",
                IssueSeverity.Warning,
                "Persisted guardian tradeInventory не содержит generationReputationTier и будет regenerated client-side",
                code: "guardian_trade_inventory_missing_generation_tier",
                section: "tradeInventory",
                expected: "non-empty generationReputationTier",
                actual: "missing or empty",
                repairHint: "Не чини malformed persisted guardian tradeInventory вручную; клиент должен пересобрать его для текущего цикла торговли."));
            return;
        }

        var pricingTier = GetFirstNonEmptyString(tradeInventory, "pricingReputationTier");
        if (string.IsNullOrWhiteSpace(pricingTier))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.pricingReputationTier",
                IssueSeverity.Warning,
                "Persisted guardian tradeInventory не содержит pricingReputationTier и будет regenerated client-side",
                code: "guardian_trade_inventory_missing_pricing_tier",
                section: "tradeInventory",
                expected: "non-empty pricingReputationTier",
                actual: "missing or empty",
                repairHint: "Не чини malformed persisted guardian tradeInventory вручную; клиент должен пересобрать его для текущего цикла торговли."));
            return;
        }

        if (!string.IsNullOrWhiteSpace(generationTier) && !GuardianTradeService.IsValidTradeTierCode(generationTier))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.generationReputationTier",
                IssueSeverity.Warning,
                "tradeInventory.generationReputationTier должен быть допустимым trade tier",
                code: "guardian_trade_inventory_generation_tier_invalid",
                section: "tradeInventory",
                expected: "Hostile | Neutral | Friendly | Devoted | Legendary",
                actual: generationTier));
        }

        if (!string.IsNullOrWhiteSpace(pricingTier) && !GuardianTradeService.IsValidTradeTierCode(pricingTier))
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.pricingReputationTier",
                IssueSeverity.Warning,
                "tradeInventory.pricingReputationTier должен быть допустимым trade tier",
                code: "guardian_trade_inventory_pricing_tier_invalid",
                section: "tradeInventory",
                expected: "Hostile | Neutral | Friendly | Devoted | Legendary",
                actual: pricingTier));
        }

        if (!tradeInventory.TryGetProperty("items", out var items) || items.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.items",
                IssueSeverity.Warning,
                "tradeInventory.items должен быть массивом из 4 торговых слотов"));
            return;
        }

        if (items.GetArrayLength() != 4)
        {
            issues.Add(new ValidationIssue(
                $"{tradeContext}.items",
                IssueSeverity.Warning,
                "tradeInventory.items должен содержать ровно 4 торговых слота"));
        }

        var index = 0;
        foreach (var item in items.EnumerateArray())
        {
            var itemContext = $"{tradeContext}.items[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            RequireString(item, itemContext, issues, "slotId");
            var domainTag = RequireString(item, itemContext, issues, "domainTag");
            ValidateNonNegativeNumberField(item, itemContext, issues, "priceInFeathers");

            if (!string.IsNullOrWhiteSpace(guardianDomain) &&
                !string.IsNullOrWhiteSpace(domainTag) &&
                !string.Equals(domainTag, guardianDomain, StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.domainTag",
                    IssueSeverity.Warning,
                    "tradeInventory item.domainTag должен совпадать с domain Хранителя",
                    code: "guardian_trade_inventory_domain_mismatch",
                    section: "tradeInventory",
                    expected: guardianDomain,
                    actual: domainTag));
            }

            if (!item.TryGetProperty("soldOut", out var soldOut) ||
                (soldOut.ValueKind != JsonValueKind.True && soldOut.ValueKind != JsonValueKind.False))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.soldOut",
                    IssueSeverity.Warning,
                    "tradeInventory item.soldOut должен быть boolean"));
            }

            if (!item.TryGetProperty("relicData", out var relicData) || !RequireObject(relicData, $"{itemContext}.relicData", issues))
                continue;

            var relicContext = $"{itemContext}.relicData";
            RequireString(relicData, relicContext, issues, "relicId");
            RequireString(relicData, relicContext, issues, "name");
            var rarity = GetFirstNonEmptyString(relicData, "quality", "rarity");
            if (!relicData.TryGetProperty("quality", out var quality) &&
                !relicData.TryGetProperty("rarity", out quality))
            {
                issues.Add(new ValidationIssue(
                    relicContext,
                    IssueSeverity.Warning,
                    "relicData должен содержать quality или rarity"));
            }

            if (!string.IsNullOrWhiteSpace(rarity) &&
                !string.IsNullOrWhiteSpace(generationTier) &&
                GuardianTradeService.IsValidTradeTierCode(generationTier) &&
                !GuardianTradeService.IsRarityAllowedForGenerationTier(rarity, generationTier))
            {
                issues.Add(new ValidationIssue(
                    $"{relicContext}.quality",
                    IssueSeverity.Warning,
                    "tradeInventory item rarity превышает допустимый потолок редкости для generationReputationTier",
                    code: "guardian_trade_inventory_rarity_cap_mismatch",
                    section: "tradeInventory",
                    expected: generationTier,
                    actual: rarity));
            }

            if (!string.IsNullOrWhiteSpace(rarity) &&
                item.TryGetProperty("priceInFeathers", out var priceNode) &&
                priceNode.ValueKind == JsonValueKind.Number &&
                priceNode.TryGetInt32(out var actualPrice) &&
                !string.IsNullOrWhiteSpace(pricingTier) &&
                GuardianTradeService.IsValidTradeTierCode(pricingTier))
            {
                var expectedPrice = GuardianTradeService.ComputeBuyPriceForTierCode(rarity, pricingTier);
                if (actualPrice != expectedPrice)
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.priceInFeathers",
                        IssueSeverity.Warning,
                        "tradeInventory item.priceInFeathers должен совпадать с канонической ценой для pricingReputationTier",
                        code: "guardian_trade_inventory_price_mismatch",
                        section: "tradeInventory",
                        expected: expectedPrice.ToString(),
                        actual: actualPrice.ToString()));
                }
            }
        }
    }

    private void CompareGuardianGachaState(JsonElement activeGuardian, string activeGuardianContext,
        JsonElement guardianFromArray, string guardianArrayContext, List<ValidationIssue> issues)
    {
        if (!activeGuardian.TryGetProperty("gachaSystem", out var activeGachaSystem) || activeGachaSystem.ValueKind != JsonValueKind.Object)
            return;
        if (!guardianFromArray.TryGetProperty("gachaSystem", out var arrayGachaSystem) || arrayGachaSystem.ValueKind != JsonValueKind.Object)
            return;

        if (TryReadIntField(activeGachaSystem, "chargesPerReturn", out var activeChargesPerReturn) &&
            TryReadIntField(arrayGachaSystem, "chargesPerReturn", out var arrayChargesPerReturn) &&
            activeChargesPerReturn != arrayChargesPerReturn)
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.gachaSystem.chargesPerReturn",
                IssueSeverity.Error,
                $"activeGuardian расходится с {guardianArrayContext}.gachaSystem.chargesPerReturn"));
        }

        if (TryReadIntField(activeGachaSystem, "chargesUsedThisReturn", out var activeChargesUsed) &&
            TryReadIntField(arrayGachaSystem, "chargesUsedThisReturn", out var arrayChargesUsed) &&
            activeChargesUsed != arrayChargesUsed)
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.gachaSystem.chargesUsedThisReturn",
                IssueSeverity.Error,
                $"activeGuardian расходится с {guardianArrayContext}.gachaSystem.chargesUsedThisReturn"));
        }
    }

    private void CompareGuardianTradeState(JsonElement activeGuardian, string activeGuardianContext,
        JsonElement guardianFromArray, string guardianArrayContext, List<ValidationIssue> issues)
    {
        var activeHasTrade = activeGuardian.TryGetProperty("tradeInventory", out var activeTradeInventory) &&
                             activeTradeInventory.ValueKind == JsonValueKind.Object;
        var arrayHasTrade = guardianFromArray.TryGetProperty("tradeInventory", out var arrayTradeInventory) &&
                            arrayTradeInventory.ValueKind == JsonValueKind.Object;

        if (!activeHasTrade && !arrayHasTrade)
            return;

        if (activeHasTrade != arrayHasTrade)
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory",
                code: "guardian_trade_inventory_presence_mismatch",
                section: "tradeInventory",
                expected: "same tradeInventory presence in activeGuardian and guardians[]",
                actual: activeHasTrade ? "present only in activeGuardian" : "present only in guardians[]"));
            return;
        }

        var activeCycle = GetFirstNonEmptyString(activeTradeInventory, "tradeCycleId");
        var arrayCycle = GetFirstNonEmptyString(arrayTradeInventory, "tradeCycleId");
        if (!string.Equals(activeCycle, arrayCycle, StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory.tradeCycleId",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.tradeCycleId",
                code: "guardian_trade_inventory_cycle_mismatch",
                section: "tradeInventory",
                expected: arrayCycle ?? "null",
                actual: activeCycle ?? "null"));
        }

        var activeGenerated = GetFirstNonEmptyString(activeTradeInventory, "generatedAtUtc");
        var arrayGenerated = GetFirstNonEmptyString(arrayTradeInventory, "generatedAtUtc");
        if (!string.Equals(activeGenerated, arrayGenerated, StringComparison.Ordinal))
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory.generatedAtUtc",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.generatedAtUtc",
                code: "guardian_trade_inventory_generated_at_mismatch",
                section: "tradeInventory",
                expected: arrayGenerated ?? "null",
                actual: activeGenerated ?? "null"));
        }

        var activeGenerationTier = GetFirstNonEmptyString(activeTradeInventory, "generationReputationTier");
        var arrayGenerationTier = GetFirstNonEmptyString(arrayTradeInventory, "generationReputationTier");
        if (!string.Equals(activeGenerationTier, arrayGenerationTier, StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory.generationReputationTier",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.generationReputationTier",
                code: "guardian_trade_inventory_generation_tier_mismatch",
                section: "tradeInventory",
                expected: arrayGenerationTier ?? "null",
                actual: activeGenerationTier ?? "null"));
        }

        var activePricingTier = GetFirstNonEmptyString(activeTradeInventory, "pricingReputationTier");
        var arrayPricingTier = GetFirstNonEmptyString(arrayTradeInventory, "pricingReputationTier");
        if (!string.Equals(activePricingTier, arrayPricingTier, StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory.pricingReputationTier",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.pricingReputationTier",
                code: "guardian_trade_inventory_pricing_tier_mismatch",
                section: "tradeInventory",
                expected: arrayPricingTier ?? "null",
                actual: activePricingTier ?? "null"));
        }

        if (!activeTradeInventory.TryGetProperty("items", out var activeItems) || activeItems.ValueKind != JsonValueKind.Array ||
            !arrayTradeInventory.TryGetProperty("items", out var arrayItems) || arrayItems.ValueKind != JsonValueKind.Array)
        {
            return;
        }

        var activeBySlot = activeItems.EnumerateArray()
            .Where(item => item.ValueKind == JsonValueKind.Object)
            .Select(item => (SlotId: GetFirstNonEmptyString(item, "slotId"), Signature: BuildGuardianTradeSlotSignature(item)))
            .Where(item => !string.IsNullOrWhiteSpace(item.SlotId))
            .ToDictionary(item => item.SlotId!, item => item.Signature, StringComparer.OrdinalIgnoreCase);

        var arrayBySlot = arrayItems.EnumerateArray()
            .Where(item => item.ValueKind == JsonValueKind.Object)
            .Select(item => (SlotId: GetFirstNonEmptyString(item, "slotId"), Signature: BuildGuardianTradeSlotSignature(item)))
            .Where(item => !string.IsNullOrWhiteSpace(item.SlotId))
            .ToDictionary(item => item.SlotId!, item => item.Signature, StringComparer.OrdinalIgnoreCase);

        if (activeBySlot.Count != arrayBySlot.Count)
        {
            issues.Add(new ValidationIssue(
                $"{activeGuardianContext}.tradeInventory.items",
                IssueSeverity.Warning,
                $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.items по числу слотов",
                code: "guardian_trade_inventory_slot_count_mismatch",
                section: "tradeInventory",
                expected: arrayBySlot.Count.ToString(),
                actual: activeBySlot.Count.ToString()));
            return;
        }

        foreach (var (slotId, expectedSignature) in arrayBySlot)
        {
            if (!activeBySlot.TryGetValue(slotId, out var actualSignature) || !string.Equals(actualSignature, expectedSignature, StringComparison.Ordinal))
            {
                issues.Add(new ValidationIssue(
                    $"{activeGuardianContext}.tradeInventory.items",
                    IssueSeverity.Warning,
                    $"activeGuardian расходится с {guardianArrayContext}.tradeInventory.items[{slotId}]",
                    code: "guardian_trade_inventory_slot_mismatch",
                    section: "tradeInventory",
                    expected: expectedSignature,
                    actual: actualSignature ?? "missing slot"));
            }
        }
    }

    private static string BuildGuardianTradeSlotSignature(JsonElement item)
    {
        var slotId = GetFirstNonEmptyString(item, "slotId") ?? "";
        var domainTag = GetFirstNonEmptyString(item, "domainTag") ?? "";
        var price = item.TryGetProperty("priceInFeathers", out var priceNode) && priceNode.ValueKind == JsonValueKind.Number
            ? priceNode.GetInt32().ToString()
            : "";
        var soldOut = item.TryGetProperty("soldOut", out var soldOutNode) &&
                      (soldOutNode.ValueKind == JsonValueKind.True || soldOutNode.ValueKind == JsonValueKind.False)
            ? soldOutNode.GetBoolean().ToString()
            : "";

        if (!item.TryGetProperty("relicData", out var relicData) || relicData.ValueKind != JsonValueKind.Object)
            return $"{slotId}|{domainTag}|{price}|{soldOut}|";

        return $"{slotId}|{domainTag}|{price}|{soldOut}|{BuildCanonicalJsonSignature(relicData)}";
    }

    private static string BuildCanonicalJsonSignature(JsonElement element)
    {
        return element.ValueKind switch
        {
            JsonValueKind.Object => "{" + string.Join(",", element.EnumerateObject()
                .OrderBy(p => p.Name, StringComparer.Ordinal)
                .Select(p => $"{p.Name}:{BuildCanonicalJsonSignature(p.Value)}")) + "}",
            JsonValueKind.Array => "[" + string.Join(",", element.EnumerateArray().Select(BuildCanonicalJsonSignature)) + "]",
            JsonValueKind.String => JsonSerializer.Serialize(element.GetString() ?? string.Empty),
            JsonValueKind.Number => element.ToString(),
            JsonValueKind.True => "true",
            JsonValueKind.False => "false",
            JsonValueKind.Null => "null",
            _ => element.GetRawText()
        };
    }

    private static bool TryReadIntField(JsonElement root, string propertyName, out int value)
    {
        value = 0;
        return root.TryGetProperty(propertyName, out var prop) &&
               prop.ValueKind == JsonValueKind.Number &&
               prop.TryGetInt32(out value);
    }

    private void ValidatePlayerBehavior(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (root.TryGetProperty("historyManipulationCoefficient", out var coeff) &&
            coeff.ValueKind != JsonValueKind.Number)
        {
            issues.Add(new ValidationIssue($"{contextPrefix}.historyManipulationCoefficient", IssueSeverity.Error,
                "historyManipulationCoefficient должен быть числом"));
        }

        if (!root.TryGetProperty("playerBehaviorAssessment", out var assessment))
            return;

        var context = $"{contextPrefix}.playerBehaviorAssessment";
        if (!RequireObject(assessment, context, issues))
            return;

        if (assessment.TryGetProperty("historyManipulationCoefficient", out var nestedCoeff) &&
            nestedCoeff.ValueKind != JsonValueKind.Number)
        {
            issues.Add(new ValidationIssue($"{context}.historyManipulationCoefficient", IssueSeverity.Error,
                "historyManipulationCoefficient должен быть числом"));
        }
    }

    private void ValidateCharacterChronicle(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (root.TryGetProperty("characterChronicleUpdates", out var updates))
        {
            if (updates.ValueKind != JsonValueKind.Null)
            {
                RequireArrayOfObjects(updates, $"{contextPrefix}.characterChronicleUpdates", issues);
                if (updates.ValueKind == JsonValueKind.Array)
                {
                    var index = 0;
                    foreach (var item in updates.EnumerateArray())
                    {
                        var itemContext = $"{contextPrefix}.characterChronicleUpdates[{index++}]";
                        if (!RequireObject(item, itemContext, issues))
                            continue;

                        ValidateCharacterChronicleUpdateObject(item, itemContext, issues);
                    }
                }
            }
        }

        if (root.TryGetProperty("entries", out var entries))
            ValidateLooseStringOrObjectArray(entries, $"{contextPrefix}.entries", issues);
    }

    private void ValidateAchievementData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        var hasUnlockCommands = root.TryGetProperty("achievementUnlocks", out var unlockCommands) &&
                                unlockCommands.ValueKind != JsonValueKind.Null;
        if (contextPrefix.EndsWith("game_state/meta/achievements.json", StringComparison.OrdinalIgnoreCase) &&
            !hasUnlockCommands)
        {
            foreach (var requiredProp in new[] { "unlockedAchievements", "trackedProgress", "stats" })
            {
                if (!root.TryGetProperty(requiredProp, out _))
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.{requiredProp}",
                        IssueSeverity.Error,
                        "Canonical achievements file не содержит обязательный top-level ключ",
                        code: "achievements_missing_required_top_level_key",
                        section: "Achievements",
                        expected: "unlockedAchievements + trackedProgress + stats",
                        actual: $"missing {requiredProp}",
                        repairHint: "Сохраняй canonical achievements.json с top-level ключами unlockedAchievements, trackedProgress и stats даже если некоторые секции пока пустые."));
                }
            }
        }

        ValidateAchievementEntryArray(root, contextPrefix, issues, "achievementUnlocks", persisted: false);
        ValidateAchievementEntryArray(root, contextPrefix, issues, "unlockedAchievements", persisted: true);
        ValidateAchievementTrackedProgress(root, contextPrefix, issues);
        ValidateAchievementStatsObject(root, contextPrefix, issues);
    }

    private void ValidateCodexData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        var hasCodexCommands = root.TryGetProperty("loreCodexUpdates", out var codexCommands) &&
                               codexCommands.ValueKind != JsonValueKind.Null;
        if (contextPrefix.EndsWith("lore/codex_entries.json", StringComparison.OrdinalIgnoreCase) &&
            !hasCodexCommands)
        {
            foreach (var requiredProp in new[] { "entries", "totalEntries", "categories" })
            {
                if (!root.TryGetProperty(requiredProp, out _))
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.{requiredProp}",
                        IssueSeverity.Error,
                        "Canonical codex file не содержит обязательный top-level ключ",
                        code: "codex_missing_required_top_level_key",
                        section: "Codex",
                        expected: "entries + totalEntries + categories",
                        actual: $"missing {requiredProp}",
                        repairHint: "Сохраняй canonical lore/codex_entries.json с top-level ключами entries, totalEntries и categories даже если часть разделов пока пустая."));
                }
            }
        }

        ValidateCodexEntryArray(root, contextPrefix, issues, "loreCodexUpdates");
        ValidateCodexEntryArray(root, contextPrefix, issues, "entries");

        if (root.TryGetProperty("totalEntries", out var totalEntries) &&
            (totalEntries.ValueKind != JsonValueKind.Number || !totalEntries.TryGetInt32(out _)))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.totalEntries",
                IssueSeverity.Error,
                "totalEntries должен быть числом"));
        }

        if (root.TryGetProperty("categories", out var categories))
        {
            if (!RequireObject(categories, $"{contextPrefix}.categories", issues))
                return;

            foreach (var requiredCategory in AllowedCodexCategories)
            {
                if (!categories.TryGetProperty(requiredCategory, out var bucketValue) ||
                    bucketValue.ValueKind != JsonValueKind.Number ||
                    !bucketValue.TryGetInt32(out _))
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.categories.{requiredCategory}",
                        IssueSeverity.Error,
                        "Canonical codex categories должны содержать полный набор category buckets",
                        code: "codex_missing_category_bucket",
                        section: "Codex",
                        expected: string.Join(", ", AllowedCodexCategories),
                        actual: requiredCategory,
                        repairHint: "Сохраняй lore/codex_entries.json.categories с полным canonical набором buckets, даже если значение конкретной категории равно 0."));
                }
            }

            foreach (var category in categories.EnumerateObject())
            {
                if (!AllowedCodexCategories.Contains(category.Name))
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.categories.{category.Name}",
                        IssueSeverity.Error,
                        "categories содержит неподдерживаемый codex bucket",
                        code: "codex_unknown_category_bucket",
                        section: "Codex",
                        expected: string.Join(" | ", AllowedCodexCategories),
                        actual: category.Name,
                        repairHint: "Используй в lore/codex_entries.json.categories только canonical codex category buckets."));
                }
                else if (category.Value.ValueKind != JsonValueKind.Number || !category.Value.TryGetInt32(out _))
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.categories.{category.Name}",
                        IssueSeverity.Error,
                        "Значение категории codex должно быть числом"));
                }
            }
        }

        if (root.TryGetProperty("entries", out var entriesNode) &&
            entriesNode.ValueKind == JsonValueKind.Array &&
            root.TryGetProperty("totalEntries", out var totalEntriesNode) &&
            totalEntriesNode.ValueKind == JsonValueKind.Number &&
            totalEntriesNode.TryGetInt32(out var totalEntriesCount) &&
            totalEntriesCount != entriesNode.GetArrayLength())
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.totalEntries",
                IssueSeverity.Error,
                "totalEntries должен совпадать с фактическим числом codex entries",
                code: "codex_total_entries_mismatch",
                section: "Codex",
                expected: entriesNode.GetArrayLength().ToString(),
                actual: totalEntriesCount.ToString(),
                repairHint: "Синхронизируй totalEntries с реальным количеством объектов в lore/codex_entries.json.entries."));
        }

        if (contextPrefix.EndsWith("lore/codex_entries.json", StringComparison.OrdinalIgnoreCase) &&
            root.TryGetProperty("entries", out entriesNode) &&
            entriesNode.ValueKind == JsonValueKind.Array &&
            root.TryGetProperty("categories", out var categoriesNode) &&
            categoriesNode.ValueKind == JsonValueKind.Object)
        {
            var actualCategoryCounts = AllowedCodexCategories.ToDictionary(key => key, _ => 0, StringComparer.OrdinalIgnoreCase);
            foreach (var entry in entriesNode.EnumerateArray())
            {
                var category = GetFirstNonEmptyString(entry, "category");
                if (!string.IsNullOrWhiteSpace(category) && actualCategoryCounts.ContainsKey(category))
                    actualCategoryCounts[category]++;
            }

            foreach (var (categoryName, actualCount) in actualCategoryCounts)
            {
                if (!categoriesNode.TryGetProperty(categoryName, out var categoryValue) ||
                    categoryValue.ValueKind != JsonValueKind.Number ||
                    !categoryValue.TryGetInt32(out var storedCount))
                {
                    continue;
                }

                if (storedCount != actualCount)
                {
                    issues.Add(new ValidationIssue(
                        $"{contextPrefix}.categories.{categoryName}",
                        IssueSeverity.Error,
                        "Codex category bucket должен совпадать с фактическим числом entries этой категории",
                        code: "codex_category_count_mismatch",
                        section: "Codex",
                        expected: actualCount.ToString(),
                        actual: storedCount.ToString(),
                        repairHint: "Синхронизируй lore/codex_entries.json.categories с реальным распределением entries по category."));
                }
            }
        }
    }

    private void ValidateAchievementStatsObject(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("stats", out var stats))
            return;

        var statsContext = $"{contextPrefix}.stats";
        if (!RequireObject(stats, statsContext, issues))
            return;

        ValidateNonNegativeNumberField(stats, statsContext, issues, "totalUnlocked");

        foreach (var propName in new[] { "byCategory", "byRarity" })
        {
            if (!stats.TryGetProperty(propName, out var bucket))
                continue;

            if (!RequireObject(bucket, $"{statsContext}.{propName}", issues))
                continue;

            foreach (var entry in bucket.EnumerateObject())
            {
                var allowedBucketNames = string.Equals(propName, "byCategory", StringComparison.OrdinalIgnoreCase)
                    ? AllowedAchievementCategories
                    : AllowedAchievementRarities;

                if (!allowedBucketNames.Contains(entry.Name))
                {
                    issues.Add(new ValidationIssue(
                        $"{statsContext}.{propName}.{entry.Name}",
                        IssueSeverity.Error,
                        "Achievement stats содержит неподдерживаемый bucket",
                        code: "achievement_stats_unknown_bucket",
                        section: "Achievements",
                        expected: string.Join(" | ", allowedBucketNames),
                        actual: entry.Name,
                        repairHint: "Используй в achievements stats только canonical category/rarity buckets из spec."));
                    continue;
                }

                if (entry.Value.ValueKind != JsonValueKind.Number || !entry.Value.TryGetInt32(out var count) || count < 0)
                {
                    issues.Add(new ValidationIssue(
                        $"{statsContext}.{propName}.{entry.Name}",
                        IssueSeverity.Error,
                        "Achievement stats bucket должен содержать только неотрицательные integer counts",
                        code: "achievement_stats_invalid_bucket_value",
                        section: "Achievements",
                        repairHint: "Сохраняй stats.byCategory и stats.byRarity как объекты с неотрицательными integer counters."));
                }
            }

            var expectedBuckets = string.Equals(propName, "byCategory", StringComparison.OrdinalIgnoreCase)
                ? AllowedAchievementCategories
                : AllowedAchievementRarities;
            foreach (var requiredBucket in expectedBuckets)
            {
                if (!bucket.TryGetProperty(requiredBucket, out var _))
                {
                    issues.Add(new ValidationIssue(
                        $"{statsContext}.{propName}.{requiredBucket}",
                        IssueSeverity.Error,
                        "Achievement stats должен содержать полный набор canonical buckets",
                        code: "achievement_stats_missing_bucket",
                        section: "Achievements",
                        expected: string.Join(", ", expectedBuckets),
                        actual: requiredBucket,
                        repairHint: "Сохраняй в achievements stats полный canonical набор category/rarity buckets, даже если значение конкретного bucket равно 0."));
                }
            }
        }

        if (root.TryGetProperty("unlockedAchievements", out var unlockedAchievements) &&
            unlockedAchievements.ValueKind == JsonValueKind.Array &&
            stats.TryGetProperty("totalUnlocked", out var totalUnlocked) &&
            totalUnlocked.ValueKind == JsonValueKind.Number &&
            totalUnlocked.TryGetInt32(out var totalUnlockedCount) &&
            totalUnlockedCount != unlockedAchievements.GetArrayLength())
        {
            issues.Add(new ValidationIssue(
                $"{statsContext}.totalUnlocked",
                IssueSeverity.Error,
                "stats.totalUnlocked должен совпадать с числом unlockedAchievements",
                code: "achievement_total_unlocked_mismatch",
                section: "Achievements",
                expected: unlockedAchievements.GetArrayLength().ToString(),
                actual: totalUnlockedCount.ToString(),
                repairHint: "Синхронизируй stats.totalUnlocked с фактическим числом объектов в unlockedAchievements."));
        }

        if (root.TryGetProperty("unlockedAchievements", out unlockedAchievements) &&
            unlockedAchievements.ValueKind == JsonValueKind.Array)
        {
            if (stats.TryGetProperty("byCategory", out var byCategory) && byCategory.ValueKind == JsonValueKind.Object)
            {
                var actualByCategory = AllowedAchievementCategories.ToDictionary(key => key, _ => 0, StringComparer.OrdinalIgnoreCase);
                foreach (var achievement in unlockedAchievements.EnumerateArray())
                {
                    var category = GetFirstNonEmptyString(achievement, "category");
                    if (!string.IsNullOrWhiteSpace(category) && actualByCategory.ContainsKey(category))
                        actualByCategory[category]++;
                }

                foreach (var (bucketName, actualCount) in actualByCategory)
                {
                    if (!byCategory.TryGetProperty(bucketName, out var bucketValue) ||
                        bucketValue.ValueKind != JsonValueKind.Number ||
                        !bucketValue.TryGetInt32(out var parsedBucket))
                    {
                        continue;
                    }

                    if (parsedBucket != actualCount)
                    {
                        issues.Add(new ValidationIssue(
                            $"{statsContext}.byCategory.{bucketName}",
                            IssueSeverity.Error,
                            "stats.byCategory должен совпадать с фактическим числом unlockedAchievements по категориям",
                            code: "achievement_stats_category_count_mismatch",
                            section: "Achievements",
                            expected: actualCount.ToString(),
                            actual: parsedBucket.ToString(),
                            repairHint: "Синхронизируй achievements stats.byCategory с реальным распределением unlockedAchievements по category."));
                    }
                }
            }

            if (stats.TryGetProperty("byRarity", out var byRarity) && byRarity.ValueKind == JsonValueKind.Object)
            {
                var actualByRarity = AllowedAchievementRarities.ToDictionary(key => key, _ => 0, StringComparer.OrdinalIgnoreCase);
                foreach (var achievement in unlockedAchievements.EnumerateArray())
                {
                    var rarity = GetFirstNonEmptyString(achievement, "rarity");
                    if (!string.IsNullOrWhiteSpace(rarity) && actualByRarity.ContainsKey(rarity))
                        actualByRarity[rarity]++;
                }

                foreach (var (bucketName, actualCount) in actualByRarity)
                {
                    if (!byRarity.TryGetProperty(bucketName, out var bucketValue) ||
                        bucketValue.ValueKind != JsonValueKind.Number ||
                        !bucketValue.TryGetInt32(out var parsedBucket))
                    {
                        continue;
                    }

                    if (parsedBucket != actualCount)
                    {
                        issues.Add(new ValidationIssue(
                            $"{statsContext}.byRarity.{bucketName}",
                            IssueSeverity.Error,
                            "stats.byRarity должен совпадать с фактическим числом unlockedAchievements по rarity",
                            code: "achievement_stats_rarity_count_mismatch",
                            section: "Achievements",
                            expected: actualCount.ToString(),
                            actual: parsedBucket.ToString(),
                            repairHint: "Синхронизируй achievements stats.byRarity с реальным распределением unlockedAchievements по rarity."));
                    }
                }
            }
        }
    }

    private void ValidateAchievementEntryArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName, bool persisted)
    {
        if (!root.TryGetProperty(propName, out var arr))
            return;

        RequireArrayOfObjects(arr, $"{contextPrefix}.{propName}", issues);
        if (arr.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            if (item.ValueKind == JsonValueKind.Object)
            ValidateAchievementEntry(
                item,
                $"{contextPrefix}.{propName}[{index}]",
                issues,
                persisted,
                requireUnlockMetadata: persisted || propName.Equals("achievementUnlocks", StringComparison.OrdinalIgnoreCase));
            index++;
        }
    }

    private void ValidateAchievementTrackedProgress(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("trackedProgress", out var tracked))
            return;

        RequireArrayOfObjects(tracked, $"{contextPrefix}.trackedProgress", issues);
        if (tracked.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in tracked.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.trackedProgress[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            ValidateAchievementEntry(item, itemContext, issues, persisted: false, requireUnlockMetadata: false);
            ValidateAchievementProgressObject(item, itemContext, issues, required: true);
        }
    }

    private void ValidateAchievementEntry(JsonElement item, string itemContext, List<ValidationIssue> issues, bool persisted, bool requireUnlockMetadata)
    {
        RequireString(item, itemContext, issues, "achievementId");
        RequireString(item, itemContext, issues, "name");
        RequireString(item, itemContext, issues, "description");
        var category = RequireString(item, itemContext, issues, "category");
        var rarity = RequireString(item, itemContext, issues, "rarity");
        RequireString(item, itemContext, issues, "icon");

        if (!string.IsNullOrWhiteSpace(category) && !AllowedAchievementCategories.Contains(category))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.category",
                IssueSeverity.Error,
                "achievement category должен быть одним из canonical enum значений",
                code: "achievement_invalid_category",
                section: "Achievements",
                expected: string.Join(" | ", AllowedAchievementCategories),
                actual: category,
                repairHint: "Используй одну из achievement categories из CLI contract: combat, exploration, story, social, crafting, meta, death, secret."));
        }

        if (!string.IsNullOrWhiteSpace(rarity) && !AllowedAchievementRarities.Contains(rarity))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.rarity",
                IssueSeverity.Error,
                "achievement rarity должен быть одним из canonical enum значений",
                code: "achievement_invalid_rarity",
                section: "Achievements",
                expected: string.Join(" | ", AllowedAchievementRarities),
                actual: rarity,
                repairHint: "Используй canonical achievement rarity: common, uncommon, rare, epic или legendary."));
        }

        if (requireUnlockMetadata)
        {
            ValidateNonNegativeIntegerField(item, itemContext, issues, "incarnation", "Achievements");
            var unlockedAt = RequireString(item, itemContext, issues, "unlockedAt");
            if (!string.IsNullOrWhiteSpace(unlockedAt) && !DateTimeOffset.TryParse(unlockedAt, out _))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.unlockedAt",
                    IssueSeverity.Error,
                    "achievement unlockedAt должен быть ISO 8601 timestamp",
                    code: "achievement_invalid_unlocked_at",
                    section: "Achievements",
                    expected: "ISO 8601 timestamp",
                    actual: unlockedAt,
                    repairHint: "Записывай unlockedAt в ISO 8601 формате, чтобы chronology achievement unlocks оставалась воспроизводимой."));
            }
        }

        if (item.TryGetProperty("hidden", out var hidden) &&
            hidden.ValueKind is not (JsonValueKind.True or JsonValueKind.False))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.hidden",
                IssueSeverity.Error,
                "hidden должен быть boolean",
                code: "achievement_hidden_not_boolean",
                section: "Achievements",
                expected: "boolean",
                actual: hidden.ValueKind.ToString(),
                repairHint: "Передавай hidden только как true/false, если это поле присутствует в achievement object."));
        }

        ValidateAchievementProgressObject(item, itemContext, issues, required: false);

        if (item.TryGetProperty("reward", out var reward))
        {
            if (!RequireObject(reward, $"{itemContext}.reward", issues))
                return;

            var rewardType = GetFirstNonEmptyString(reward, "type");
            ValidateOptionalString(reward, $"{itemContext}.reward", issues, "type");
            if (!string.IsNullOrWhiteSpace(rewardType) && !AllowedAchievementRewardTypes.Contains(rewardType))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.reward.type",
                    IssueSeverity.Error,
                    "achievement reward.type должен быть одним из canonical enum значений",
                    code: "achievement_invalid_reward_type",
                    section: "Achievements",
                    expected: string.Join(" | ", AllowedAchievementRewardTypes),
                    actual: rewardType,
                    repairHint: "Используй achievement reward.type только из contract enum: inkFeathers, soulXP, title, none."));
            }
            if (reward.TryGetProperty("value", out var rewardValue) &&
                rewardValue.ValueKind is not (JsonValueKind.String or JsonValueKind.Number))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.reward.value",
                    IssueSeverity.Error,
                    "reward.value должен быть строкой или числом"));
            }
        }
    }

    private void ValidateAchievementProgressObject(JsonElement item, string itemContext, List<ValidationIssue> issues, bool required)
    {
        if (!item.TryGetProperty("progress", out var progress))
        {
            if (required)
                RequireObjectProperty(item, itemContext, issues, "progress");
            return;
        }

        if (!RequireObject(progress, $"{itemContext}.progress", issues))
            return;

        ValidateNonNegativeIntegerField(progress, $"{itemContext}.progress", issues, "current", "Achievements");
        ValidatePositiveIntegerField(progress, $"{itemContext}.progress", issues, "target");
    }

    private void ValidateCodexEntryArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var arr))
            return;

        RequireArrayOfObjects(arr, $"{contextPrefix}.{propName}", issues);
        if (arr.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            if (propName.Equals("loreCodexUpdates", StringComparison.OrdinalIgnoreCase))
            {
                var command = RequireString(item, itemContext, issues, "command");
                if (string.Equals(command, "add", StringComparison.OrdinalIgnoreCase))
                {
                    if (item.TryGetProperty("entry", out var entry) && entry.ValueKind == JsonValueKind.Object)
                        ValidateCodexEntry(entry, $"{itemContext}.entry", issues);
                    else
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.entry",
                            IssueSeverity.Error,
                            "loreCodexUpdates add command должен содержать entry",
                            code: "codex_add_missing_entry",
                            section: "Codex",
                            expected: "entry object for add command",
                            actual: "missing",
                            repairHint: "Для loreCodexUpdates add command передай полный entry object с entryId, title, category, content, discoveredAt, discoveryContext и incarnation."));
                }
                else if (string.Equals(command, "update", StringComparison.OrdinalIgnoreCase))
                {
                    RequireString(item, itemContext, issues, "entryId");
                    RequireObjectProperty(item, itemContext, issues, "updates");
                    if (item.TryGetProperty("updates", out var updates) && RequireObject(updates, $"{itemContext}.updates", issues))
                    {
                        ValidateCodexUpdatePayload(updates, $"{itemContext}.updates", issues);
                        var hasVisibleUpdateFields = updates.EnumerateObject()
                            .Any(prop => !prop.Name.StartsWith("_", StringComparison.OrdinalIgnoreCase));
                        if (!hasVisibleUpdateFields)
                        {
                            issues.Add(new ValidationIssue(
                                $"{itemContext}.updates",
                                IssueSeverity.Error,
                                "loreCodexUpdates update command должен содержать хотя бы одно изменяемое поле",
                                code: "codex_update_missing_changes",
                                section: "Codex",
                                repairHint: "Передай в updates только реально изменившиеся поля codex entry, а не пустой объект."));
                        }
                    }
                }
                else if (!string.IsNullOrWhiteSpace(command))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.command",
                        IssueSeverity.Error,
                        "loreCodexUpdates поддерживает только add или update",
                        code: "codex_update_invalid_command",
                        section: "Codex",
                        expected: "add | update",
                        actual: command,
                        repairHint: "Используй canonical loreCodexUpdates command add или update и не вводи собственные aliases."));
                }
            }
            else
            {
                ValidateCodexEntry(item, itemContext, issues);
            }
        }
    }

    private void ValidateCodexEntry(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        RequireString(item, itemContext, issues, "entryId");
        RequireString(item, itemContext, issues, "title");
        var category = RequireString(item, itemContext, issues, "category");
        RequireString(item, itemContext, issues, "content");
        var discoveredAt = RequireString(item, itemContext, issues, "discoveredAt");
        RequireString(item, itemContext, issues, "discoveryContext");
        ValidateNonNegativeIntegerField(item, itemContext, issues, "incarnation", "Codex");
        ValidateOptionalString(item, itemContext, issues, "subcategory");
        ValidateOptionalString(item, itemContext, issues, "sourceFile");

        if (!string.IsNullOrWhiteSpace(category) && !AllowedCodexCategories.Contains(category))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.category",
                IssueSeverity.Error,
                "Codex category должен быть одним из canonical enum значений",
                code: "codex_invalid_category",
                section: "Codex",
                expected: string.Join(" | ", AllowedCodexCategories),
                actual: category,
                repairHint: "Используй только canonical lore codex categories из CLI contract."));
        }

        if (!string.IsNullOrWhiteSpace(discoveredAt) && !DateTimeOffset.TryParse(discoveredAt, out _))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.discoveredAt",
                IssueSeverity.Error,
                "Codex discoveredAt должен быть ISO 8601 timestamp",
                code: "codex_invalid_discovered_at",
                section: "Codex",
                expected: "ISO 8601 timestamp",
                actual: discoveredAt,
                repairHint: "Записывай discoveredAt в ISO 8601 формате, чтобы codex chronology корректно сортировалась в UI."));
        }

        if (item.TryGetProperty("relatedEntries", out var relatedEntries))
            RequireArrayOfStrings(relatedEntries, $"{itemContext}.relatedEntries", issues);
        if (item.TryGetProperty("tags", out var tags))
            RequireArrayOfStrings(tags, $"{itemContext}.tags", issues);
    }

    private void ValidateCodexUpdatePayload(JsonElement updates, string context, List<ValidationIssue> issues)
    {
        ValidateOptionalString(updates, context, issues, "content");
        if (updates.TryGetProperty("relatedEntries", out var relatedEntries))
            RequireArrayOfStrings(relatedEntries, $"{context}.relatedEntries", issues);
        if (updates.TryGetProperty("tags", out var tags))
            RequireArrayOfStrings(tags, $"{context}.tags", issues);

        foreach (var prop in updates.EnumerateObject())
        {
            if (prop.Name.StartsWith("_", StringComparison.OrdinalIgnoreCase))
                continue;

            if (!string.Equals(prop.Name, "content", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(prop.Name, "relatedEntries", StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(prop.Name, "tags", StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.{prop.Name}",
                    IssueSeverity.Error,
                    "loreCodexUpdates.update содержит неподдерживаемое поле в update payload",
                    code: "codex_update_unknown_field",
                    section: "Codex",
                    expected: "content | relatedEntries | tags",
                    actual: prop.Name,
                    repairHint: "Для loreCodexUpdates.update передавай в updates только documented partial fields: content, relatedEntries, tags."));
            }
        }
    }

    private async Task ValidateAchievementUnlockNarrativeMarkersAsync(string responseText, List<ValidationIssue> issues)
    {
        var json = await _fs.ReadFileAsync("game_state/meta/achievements.json");
        if (string.IsNullOrWhiteSpace(json))
            return;

        JsonDocument? previousDoc = null;
        try
        {
            using var doc = JsonDocument.Parse(json);
            if (doc.RootElement.ValueKind != JsonValueKind.Object)
                return;

            var previousJson = await ReadPreTurnTrackedFileAsync("game_state/meta/achievements.json");
            if (!string.IsNullOrWhiteSpace(previousJson))
            {
                try
                {
                    previousDoc = JsonDocument.Parse(previousJson);
                }
                catch
                {
                    previousDoc = null;
                }
            }

            var unlockNames = CollectAchievementNamesRequiringNarrativeMarkers(doc.RootElement, previousDoc?.RootElement);
            if (unlockNames.Count == 0)
                return;

            var index = 0;
            foreach (var achievementName in unlockNames)
            {
                var itemContext = $"game_state/meta/achievements.json.unlockedAchievements[new:{index++}]";

                var expectedMarker = $"[ACHIEVEMENT_UNLOCK: {achievementName}]";
                if (!responseText.Contains(expectedMarker, StringComparison.Ordinal))
                {
                    issues.Add(new ValidationIssue(
                        "output/narrative_response.json.response",
                        IssueSeverity.Error,
                        "Нарратив обязан явно упомянуть achievement unlock marker для каждого achievementUnlocks entry",
                        code: "achievement_unlock_marker_missing_in_narrative",
                        section: "Achievements",
                        expected: expectedMarker,
                        actual: $"missing marker for achievement '{achievementName}'",
                        repairHint: "Добавь в narrative response exact marker вида [ACHIEVEMENT_UNLOCK: Achievement Name] для каждого achievementUnlocks entry этого хода."));
                }
            }
        }
        catch
        {
            // achievements.json shape is validated elsewhere; marker check is best-effort
        }
        finally
        {
            previousDoc?.Dispose();
        }
    }

    private void ValidateVehicleData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (root.TryGetProperty("UpdateVehicles", out var updates))
            ValidateVehicleArray(updates, $"{contextPrefix}.UpdateVehicles", issues, requireCanonicalStoredShape: false);
        if (root.TryGetProperty("vehicles", out var vehicles))
            ValidateVehicleArray(vehicles, $"{contextPrefix}.vehicles", issues, requireCanonicalStoredShape: true);
        if (root.TryGetProperty("removeVehicles", out var removals))
            RequireArrayOfStrings(removals, $"{contextPrefix}.removeVehicles", issues);
        if (root.TryGetProperty("activeVehicleChange", out var activeVehicle) &&
            activeVehicle.ValueKind != JsonValueKind.String &&
            activeVehicle.ValueKind != JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.activeVehicleChange",
                IssueSeverity.Error,
                "activeVehicleChange должен быть строкой или null",
                code: "active_vehicle_change_invalid_type",
                section: "Vehicles",
                expected: "string vehicleId or null",
                actual: activeVehicle.ValueKind.ToString(),
                repairHint: "Передавай в activeVehicleChange либо существующий string vehicleId, либо null для сброса активного транспорта."));
        }
    }

    private void ValidateStorageAccessData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        ValidateStorageAccessCommandArray(root, contextPrefix, issues, "grantStorageAccess");
        ValidateStorageAccessCommandArray(root, contextPrefix, issues, "revokeStorageAccess");
        ValidateStorageAccessCommandArray(root, contextPrefix, issues, "shareStorageAccess");
    }

    private void ValidateOtherPlayersInteractions(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("otherPlayersInteractions", out var interactions))
            return;

        var context = $"{contextPrefix}.otherPlayersInteractions";
        if (interactions.ValueKind == JsonValueKind.Object)
        {
            foreach (var playerEntry in interactions.EnumerateObject())
            {
                if (string.IsNullOrWhiteSpace(playerEntry.Name))
                {
                    issues.Add(new ValidationIssue(
                        context,
                        IssueSeverity.Error,
                        "otherPlayersInteractions object должен быть keyed by non-empty playerId"));
                    continue;
                }

                if (playerEntry.Value.ValueKind != JsonValueKind.Array)
                {
                    issues.Add(new ValidationIssue(
                        $"{context}.{playerEntry.Name}",
                        IssueSeverity.Error,
                        "Значение otherPlayersInteractions[playerId] должно быть массивом command objects",
                        code: "other_player_interactions_invalid_player_bucket",
                        section: "OtherPlayers",
                        expected: "array of command objects",
                        actual: playerEntry.Value.ValueKind.ToString(),
                        repairHint: "Для каждого target playerId передавай массив command objects, которые обычно шли бы на top-level."));
                    continue;
                }

                var index = 0;
                foreach (var command in playerEntry.Value.EnumerateArray())
                {
                    var commandContext = $"{context}.{playerEntry.Name}[{index++}]";
                    if (!RequireObject(command, commandContext, issues))
                        continue;

                    if (!command.EnumerateObject().Any())
                    {
                        issues.Add(new ValidationIssue(
                            commandContext,
                            IssueSeverity.Error,
                            "Command object для otherPlayersInteractions не должен быть пустым",
                            code: "other_player_interactions_empty_command",
                            section: "OtherPlayers",
                            repairHint: "Передавай в otherPlayersInteractions только непустые top-level command objects для целевого игрока."));
                    }
                }
            }
            return;
        }

        if (interactions.ValueKind == JsonValueKind.Array)
        {
            RequireArrayOfObjects(interactions, context, issues);
            return;
        }

        issues.Add(new ValidationIssue(context, IssueSeverity.Error,
            "otherPlayersInteractions должен быть объектом или массивом"));
    }

    private void ValidateCharacterChronicleUpdateObject(JsonElement item, string context, List<ValidationIssue> issues)
    {
        var entryToAppend = RequireString(item, context, issues, "entryToAppend");
        if (!string.IsNullOrWhiteSpace(entryToAppend) &&
            !CharacterChronicleEntryPrefixRegex.IsMatch(entryToAppend))
        {
            issues.Add(new ValidationIssue(
                $"{context}.entryToAppend",
                IssueSeverity.Error,
                "characterChronicleUpdates.entryToAppend должен начинаться с canonical turn prefix",
                code: "character_chronicle_entry_prefix_invalid",
                section: "CharacterChronicle",
                expected: "#[turn_number] - ...",
                actual: entryToAppend,
                repairHint: "Начинай каждую новую хронику с префикса '#[turn_number] - ' по правилам characterChronicleUpdates."));
        }
    }

    private void ValidateVehicleArray(JsonElement value, string context, List<ValidationIssue> issues, bool requireCanonicalStoredShape)
    {
        RequireArrayOfObjects(value, context, issues);
        if (value.ValueKind != JsonValueKind.Array)
            return;

        var simulatedVehicleStates = !requireCanonicalStoredShape
            ? TryResolvePreTurnVehicleStateMapSync() ?? new Dictionary<string, VehicleStateSnapshot>(StringComparer.OrdinalIgnoreCase)
            : null;
        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{context}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            var hasVehicleId = item.TryGetProperty("vehicleId", out var vehicleIdValue);
            var vehicleIdIsNull = false;
            if (!hasVehicleId)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.vehicleId",
                    IssueSeverity.Error,
                    "Vehicle object должен содержать обязательное поле vehicleId",
                    code: "vehicle_missing_vehicle_id",
                    section: "Vehicles",
                    expected: requireCanonicalStoredShape ? "non-empty string vehicleId" : "string vehicleId or null for brand-new vehicle creation",
                    actual: "missing",
                    repairHint: requireCanonicalStoredShape
                        ? "Сохраняй canonical vehicles[] только с непустым string vehicleId."
                        : "Для UpdateVehicles передай существующий string vehicleId или null для brand-new vehicle object по Block 10."));
                continue;
            }

            if (requireCanonicalStoredShape)
            {
                if (vehicleIdValue.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(vehicleIdValue.GetString()))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.vehicleId",
                        IssueSeverity.Error,
                        "Canonical vehicles[].vehicleId должен быть непустой строкой",
                        code: "vehicle_canonical_id_invalid",
                        section: "Vehicles",
                        expected: "non-empty string vehicleId",
                        actual: vehicleIdValue.ValueKind == JsonValueKind.String ? "empty string" : vehicleIdValue.ValueKind.ToString(),
                        repairHint: "В canonical vehicles[] сохраняй уже назначенный string vehicleId. Null допустим только в brand-new UpdateVehicles object до нормализации."));
                }
            }
            else if (vehicleIdValue.ValueKind == JsonValueKind.Null)
            {
                vehicleIdIsNull = true;
            }
            else if (vehicleIdValue.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(vehicleIdValue.GetString()))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.vehicleId",
                    IssueSeverity.Error,
                    "UpdateVehicles.vehicleId должен быть непустой строкой или null",
                    code: "vehicle_command_id_invalid",
                    section: "Vehicles",
                    expected: "non-empty string vehicleId or null for brand-new vehicle object",
                    actual: vehicleIdValue.ValueKind == JsonValueKind.String ? "empty string" : vehicleIdValue.ValueKind.ToString(),
                    repairHint: "Для существующего транспорта передавай string vehicleId. Для brand-new vehicle object Block 10 допускает vehicleId = null."));
            }

            var mustLookLikeFullVehicleObject = requireCanonicalStoredShape || vehicleIdIsNull;
            if (!mustLookLikeFullVehicleObject && item.EnumerateObject().Count() == 1)
            {
                issues.Add(new ValidationIssue(
                    itemContext,
                    IssueSeverity.Error,
                    "UpdateVehicles object должен содержать хотя бы одно изменение помимо vehicleId",
                    code: "vehicle_update_missing_changes",
                    section: "Vehicles",
                    expected: "vehicleId plus at least one changed property, or full vehicle object for a new vehicle",
                    actual: "vehicleId only",
                    repairHint: "Для существующего транспорта передай vehicleId и реально изменившиеся поля. Для выдачи нового транспорта передай полный Vehicle Object по Block 10."));
            }

            if (mustLookLikeFullVehicleObject)
            {
                RequireString(item, itemContext, issues, "name");
                RequireString(item, itemContext, issues, "description");
                RequireString(item, itemContext, issues, "image_prompt");
                RequireString(item, itemContext, issues, "type");
                RequireBooleanField(item, itemContext, issues, "isSentient");
                RequireString(item, itemContext, issues, "availability");
                ValidateRequiredNullableStringField(item, itemContext, issues, "currentLocationId");
                RequireString(item, itemContext, issues, "maxHealth");
                RequireString(item, itemContext, issues, "currentHealth");
                ValidateIntegerField(item, itemContext, issues, "speedBonus");
                RequireObjectArrayField(item, itemContext, issues, "actions");
                RequireObjectArrayField(item, itemContext, issues, "resistances");
                RequireObjectArrayField(item, itemContext, issues, "inventory");
            }
            else
            {
                ValidateOptionalString(item, itemContext, issues, "name");
                ValidateOptionalString(item, itemContext, issues, "description");
                ValidateOptionalString(item, itemContext, issues, "image_prompt");
            }

            var vehicleType = GetFirstNonEmptyString(item, "type");
            if (!mustLookLikeFullVehicleObject)
                ValidateOptionalString(item, itemContext, issues, "type");
            if (!string.IsNullOrWhiteSpace(vehicleType) && !AllowedVehicleTypes.Contains(vehicleType))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.type",
                    IssueSeverity.Error,
                    "Vehicle type должен быть одним из canonical enum значений",
                    code: "vehicle_invalid_type",
                    section: "Vehicles",
                    expected: string.Join(" | ", AllowedVehicleTypes),
                    actual: vehicleType,
                    repairHint: "Используй для vehicle.type только Mount, Vehicle или Summonable по Block 10 contract."));
            }

            var availability = GetFirstNonEmptyString(item, "availability");
            if (!mustLookLikeFullVehicleObject)
                ValidateOptionalString(item, itemContext, issues, "availability");
            if (!string.IsNullOrWhiteSpace(availability) && !AllowedVehicleAvailabilities.Contains(availability))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.availability",
                    IssueSeverity.Error,
                    "Vehicle availability должен быть одним из canonical enum значений",
                    code: "vehicle_invalid_availability",
                    section: "Vehicles",
                    expected: string.Join(" | ", AllowedVehicleAvailabilities),
                    actual: availability,
                    repairHint: "Используй для vehicle.availability только Active, Parked или Pocket по Block 10 contract."));
            }

            if (item.TryGetProperty("isSentient", out _) && !mustLookLikeFullVehicleObject)
                RequireBooleanField(item, itemContext, issues, "isSentient");
            if (item.TryGetProperty("currentLocationId", out _) && !mustLookLikeFullVehicleObject)
                ValidateRequiredNullableStringField(item, itemContext, issues, "currentLocationId");
            if (item.TryGetProperty("maxHealth", out _))
                ValidatePercentageStringField(item, itemContext, issues, "maxHealth", requirePositive: true);
            if (item.TryGetProperty("currentHealth", out _))
                ValidatePercentageStringField(item, itemContext, issues, "currentHealth", requirePositive: false);
            if (item.TryGetProperty("speedBonus", out _))
                ValidateIntegerField(item, itemContext, issues, "speedBonus");
            if (item.TryGetProperty("actions", out var actions))
                ValidateCombatActionArray(actions, $"{itemContext}.actions", issues, section: "Vehicles");
            if (item.TryGetProperty("resistances", out var resistances))
                ValidateCombatResistanceArray(resistances, $"{itemContext}.resistances", issues);
            if (item.TryGetProperty("inventory", out var inventory))
            {
                RequireArrayOfObjects(inventory, $"{itemContext}.inventory", issues);
                if (inventory.ValueKind == JsonValueKind.Array)
                {
                    var inventoryIndex = 0;
                    foreach (var inventoryItem in inventory.EnumerateArray())
                    {
                        var inventoryItemContext = $"{itemContext}.inventory[{inventoryIndex++}]";
                        if (!RequireObject(inventoryItem, inventoryItemContext, issues))
                            continue;

                        ValidateFullInventoryItemObject(inventoryItem, inventoryItemContext, issues, requireStringExistedId: false);
                    }
                }
            }

            var currentLocationId = item.TryGetProperty("currentLocationId", out var currentLocationNode) &&
                                    currentLocationNode.ValueKind == JsonValueKind.String
                ? currentLocationNode.GetString() ?? string.Empty
                : string.Empty;
            if ((string.Equals(availability, "Active", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(availability, "Pocket", StringComparison.OrdinalIgnoreCase)) &&
                !string.IsNullOrWhiteSpace(currentLocationId))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.currentLocationId",
                    IssueSeverity.Error,
                    "Vehicle с availability=Active или Pocket должен иметь currentLocationId = null",
                    code: "vehicle_active_or_pocket_requires_null_location",
                    section: "Vehicles",
                    expected: "null currentLocationId for Active/Pocket vehicle",
                    actual: currentLocationId,
                    repairHint: "Для availability=Active или Pocket оставляй currentLocationId = null. Указывай locationId только для Parked vehicle."));
            }

            var hasParkedLocationNode = item.TryGetProperty("currentLocationId", out var parkedLocationNode);
            if (string.Equals(availability, "Parked", StringComparison.OrdinalIgnoreCase) &&
                !hasParkedLocationNode)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.currentLocationId",
                    IssueSeverity.Error,
                    "Vehicle с availability=Parked должен явно содержать currentLocationId",
                    code: "vehicle_parked_missing_location",
                    section: "Vehicles",
                    expected: "parked vehicle location id",
                    actual: "missing",
                    repairHint: "Для availability=Parked передай currentLocationId локации, где транспорт припаркован."));
            }
            else if (string.Equals(availability, "Parked", StringComparison.OrdinalIgnoreCase) &&
                     hasParkedLocationNode &&
                     parkedLocationNode.ValueKind == JsonValueKind.Null)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.currentLocationId",
                    IssueSeverity.Error,
                    "Vehicle с availability=Parked не может иметь currentLocationId = null",
                    code: "vehicle_parked_null_location_forbidden",
                    section: "Vehicles",
                    expected: "non-null parked vehicle location id",
                    actual: "null",
                    repairHint: "Для availability=Parked передай currentLocationId конкретной локации, где оставлен транспорт."));
            }

            var vehicleId = vehicleIdValue.ValueKind == JsonValueKind.String
                ? vehicleIdValue.GetString()
                : null;
            if (!requireCanonicalStoredShape &&
                !mustLookLikeFullVehicleObject &&
                !string.IsNullOrWhiteSpace(vehicleId) &&
                simulatedVehicleStates != null &&
                (item.TryGetProperty("availability", out _) || item.TryGetProperty("currentLocationId", out _)))
            {
                if (simulatedVehicleStates.TryGetValue(vehicleId!, out var previousState))
                    ValidateMergedVehicleAvailabilityLocationInvariant(previousState, item, itemContext, issues);
            }

            if (!string.IsNullOrWhiteSpace(vehicleId) && simulatedVehicleStates != null)
                simulatedVehicleStates[vehicleId!] = MergeVehicleStateSnapshot(
                    simulatedVehicleStates.TryGetValue(vehicleId!, out var previousState) ? previousState : null,
                    item);
        }
    }

    private Dictionary<string, VehicleStateSnapshot>? TryResolvePreTurnVehicleStateMapSync()
        => TryReadVehicleStateMapFromJson(ReadPreTurnTrackedFileSync("game_state/misc/vehicles.json"));

    private static Dictionary<string, VehicleStateSnapshot>? TryReadVehicleStateMapFromJson(string? json)
    {
        if (string.IsNullOrWhiteSpace(json))
            return null;

        try
        {
            using var doc = JsonDocument.Parse(json);
            if (!doc.RootElement.TryGetProperty("vehicles", out var vehicles) || vehicles.ValueKind != JsonValueKind.Array)
                return null;

            var map = new Dictionary<string, VehicleStateSnapshot>(StringComparer.OrdinalIgnoreCase);
            foreach (var vehicle in vehicles.EnumerateArray())
            {
                if (vehicle.ValueKind != JsonValueKind.Object)
                    continue;

                var vehicleId = GetFirstNonEmptyString(vehicle, "vehicleId");
                if (string.IsNullOrWhiteSpace(vehicleId))
                    continue;

                map[vehicleId] = ReadVehicleStateSnapshot(vehicle);
            }

            return map;
        }
        catch
        {
            return null;
        }
    }

    private static VehicleStateSnapshot ReadVehicleStateSnapshot(JsonElement vehicle)
    {
        var hasCurrentLocationNode = vehicle.TryGetProperty("currentLocationId", out var currentLocationNode);
        return new VehicleStateSnapshot
        {
            Availability = GetFirstNonEmptyString(vehicle, "availability"),
            HasCurrentLocationNode = hasCurrentLocationNode,
            CurrentLocationExplicitNull = hasCurrentLocationNode && currentLocationNode.ValueKind == JsonValueKind.Null,
            CurrentLocationId = hasCurrentLocationNode && currentLocationNode.ValueKind == JsonValueKind.String
                ? currentLocationNode.GetString()
                : null
        };
    }

    private static VehicleStateSnapshot MergeVehicleStateSnapshot(VehicleStateSnapshot? previousState, JsonElement patch)
    {
        var hasCurrentLocationNode = patch.TryGetProperty("currentLocationId", out var currentLocationNode);
        return new VehicleStateSnapshot
        {
            Availability = GetFirstNonEmptyString(patch, "availability") ?? previousState?.Availability,
            HasCurrentLocationNode = hasCurrentLocationNode || previousState?.HasCurrentLocationNode == true,
            CurrentLocationExplicitNull = hasCurrentLocationNode
                ? currentLocationNode.ValueKind == JsonValueKind.Null
                : previousState?.CurrentLocationExplicitNull == true,
            CurrentLocationId = hasCurrentLocationNode
                ? currentLocationNode.ValueKind == JsonValueKind.String ? currentLocationNode.GetString() : null
                : previousState?.CurrentLocationId
        };
    }

    private static void ValidateMergedVehicleAvailabilityLocationInvariant(
        VehicleStateSnapshot previousState,
        JsonElement patch,
        string itemContext,
        List<ValidationIssue> issues)
    {
        var merged = MergeVehicleStateSnapshot(previousState, patch);
        var availability = merged.Availability;
        var currentLocationId = merged.CurrentLocationId;

        if ((string.Equals(availability, "Active", StringComparison.OrdinalIgnoreCase) ||
             string.Equals(availability, "Pocket", StringComparison.OrdinalIgnoreCase)) &&
            !string.IsNullOrWhiteSpace(currentLocationId))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.currentLocationId",
                IssueSeverity.Error,
                "Partial UpdateVehicles нарушает canonical invariant: Active/Pocket vehicle не может иметь currentLocationId",
                code: "vehicle_partial_update_active_or_pocket_with_location",
                section: "Vehicles",
                expected: "merged vehicle state with currentLocationId = null for Active/Pocket availability",
                actual: $"availability={availability}, currentLocationId={currentLocationId}",
                repairHint: "Если транспорт становится Active или Pocket, одновременно обнули currentLocationId. Если транспорт остаётся Parked, не присваивай ему Active/Pocket availability в partial update."));
        }

        if (string.Equals(availability, "Parked", StringComparison.OrdinalIgnoreCase) &&
            (!merged.HasCurrentLocationNode || merged.CurrentLocationExplicitNull || string.IsNullOrWhiteSpace(currentLocationId)))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.currentLocationId",
                IssueSeverity.Error,
                "Partial UpdateVehicles нарушает canonical invariant: Parked vehicle обязан иметь non-null currentLocationId",
                code: "vehicle_partial_update_parked_missing_location",
                section: "Vehicles",
                expected: "merged vehicle state with non-null currentLocationId for Parked availability",
                actual: merged.HasCurrentLocationNode
                    ? merged.CurrentLocationExplicitNull ? "null" : "missing/empty"
                    : "missing",
                repairHint: "Если транспорт остаётся или становится Parked, одновременно передай currentLocationId существующей локации. Если переносишь его в Active/Pocket, измени availability и обнули currentLocationId в этом же partial update."));
        }
    }

    private void ValidateStorageAccessCommandArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var value))
            return;

        var context = $"{contextPrefix}.{propName}";
        RequireArrayOfObjects(value, context, issues);
        if (value.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{context}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            var missingFields = GetMissingRequiredNonEmptyStringProperties(item, "storageId", "targetPlayerId", "targetPlayerName");
            if (missingFields.Count > 0)
            {
                issues.Add(new ValidationIssue(
                    itemContext,
                    IssueSeverity.Error,
                    $"{propName} object не содержит обязательные поля доступа к хранилищу",
                    code: "storage_access_missing_required_fields",
                    section: "StorageAccess",
                    expected: "storageId + targetPlayerId + targetPlayerName",
                    actual: string.Join(", ", missingFields),
                    repairHint: "Передавай storageId хранилища и полные targetPlayerId/targetPlayerName для grant/share/revoke storage access commands."));
            }
        }
    }

    private void ValidateQuestObject(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        ValidateRequiredNullableStringField(item, itemContext, issues, "questId");
        RequireString(item, itemContext, issues, "questName");
        var status = RequireString(item, itemContext, issues, "status");
        RequireString(item, itemContext, issues, "questGiver");
        RequireString(item, itemContext, issues, "questBackground");
        RequireString(item, itemContext, issues, "description");
        ValidateQuestObjectivesArray(
            item,
            itemContext,
            issues,
            AllowedQuestObjectiveStatuses,
            "Quest",
            "Используй для objectives только status = Active, Completed или Failed.");

        if (!string.IsNullOrWhiteSpace(status) && !AllowedQuestStatuses.Contains(status))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.status",
                IssueSeverity.Error,
                "Quest status должен быть одним из canonical enum значений",
                code: "quest_invalid_status",
                section: "Quest",
                expected: string.Join(" | ", AllowedQuestStatuses),
                actual: status,
                repairHint: "Используй для regular quests только status = Active, Completed, Failed или Updated."));
        }

        if (!item.TryGetProperty("detailsLog", out var detailsLog))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.detailsLog",
                IssueSeverity.Error,
                "Квест должен содержать detailsLog",
                code: "quest_missing_details_log",
                section: "Quests",
                expected: "detailsLog array",
                repairHint: "Для полного Quest Object передавай detailsLog как массив записей истории квеста, даже если он пока пустой."));
            return;
        }
        if (detailsLog.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.detailsLog",
                IssueSeverity.Error,
                "detailsLog должен быть массивом",
                code: "quest_invalid_details_log",
                section: "Quests",
                expected: "array",
                actual: detailsLog.ValueKind.ToString(),
                repairHint: "Передавай detailsLog как массив записей по canonical quest contract."));
            return;
        }
        RequireArrayOfStrings(detailsLog, $"{itemContext}.detailsLog", issues);
        if (detailsLog.ValueKind == JsonValueKind.Array)
        {
            var logIndex = 0;
            foreach (var entry in detailsLog.EnumerateArray())
            {
                if (entry.ValueKind != JsonValueKind.String)
                {
                    logIndex++;
                    continue;
                }

                var entryValue = entry.GetString() ?? string.Empty;
                if (!string.IsNullOrWhiteSpace(entryValue) && !MatchesHistoricalEntryContract(entryValue))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.detailsLog[{logIndex}]",
                        IssueSeverity.Error,
                        "Quest detailsLog entry должен начинаться с canonical turn anchor",
                        code: "quest_details_log_entry_prefix_invalid",
                        section: "Quest",
                        expected: "#[turn_number]. ... or #[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                        actual: entryValue,
                        repairHint: "Для full quest object сохраняй в detailsLog только turn-anchored записи. Минимально допустим legacy prefix '#[turn_number]. ...'; полный historical timestamp тоже допустим."));
                }

                logIndex++;
            }
        }
        ValidateQuestRewardsObject(item, itemContext, issues);
        ValidateOptionalString(item, itemContext, issues, "failureConsequences");
    }

    private void ValidateQuestPartialStateUpdateObject(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        RequireAnyString(item, itemContext, issues, "questId", "initialId");

        var hasAnyUpdateField =
            HasAnyNonEmptyString(item, "newDetailsLogEntry", "status", "questName", "questGiver", "questBackground", "description", "failureConsequences") ||
            item.TryGetProperty("objectives", out _) ||
            item.TryGetProperty("rewards", out _);
        if (!hasAnyUpdateField)
        {
            issues.Add(new ValidationIssue(
                itemContext,
                IssueSeverity.Error,
                "Quest partial update должен содержать хотя бы одно изменяемое поле",
                code: "quest_partial_update_missing_changes",
                section: "Quest",
                repairHint: "Для обновления существующего квеста передай questId или same-turn initialId и только реально изменившиеся поля; для append в журнал используй newDetailsLogEntry."));
            return;
        }

        ValidateOptionalString(item, itemContext, issues, "newDetailsLogEntry");
        var status = item.TryGetProperty("status", out _) ? RequireString(item, itemContext, issues, "status") : string.Empty;
        ValidateOptionalString(item, itemContext, issues, "questName");
        ValidateOptionalString(item, itemContext, issues, "questGiver");
        ValidateOptionalString(item, itemContext, issues, "questBackground");
        ValidateOptionalString(item, itemContext, issues, "description");
        ValidateOptionalString(item, itemContext, issues, "failureConsequences");
        if (item.TryGetProperty("objectives", out _))
            ValidateQuestObjectivesArray(
                item,
                itemContext,
                issues,
                AllowedQuestObjectiveStatuses,
                "Quest",
                "Используй для objectives только status = Active, Completed или Failed.");
        ValidateQuestRewardsObject(item, itemContext, issues);

        if (item.TryGetProperty("detailsLog", out _))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.detailsLog",
                IssueSeverity.Error,
                "Quest partial update не должен пересылать detailsLog целиком",
                code: "quest_partial_update_resends_details_log",
                section: "Quest",
                repairHint: "Для дописывания журнала используй questId или same-turn initialId + newDetailsLogEntry; полный detailsLog пересылай только при создании нового квеста."));
        }

        var newDetailsLogEntry = GetFirstNonEmptyString(item, "newDetailsLogEntry");
        if (!string.IsNullOrWhiteSpace(newDetailsLogEntry) &&
            !MatchesHistoricalEntryContract(newDetailsLogEntry))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.newDetailsLogEntry",
                IssueSeverity.Error,
                "newDetailsLogEntry должен начинаться с canonical turn anchor",
                code: "quest_log_entry_prefix_invalid",
                section: "Quest",
                expected: "#[turn_number]. ... or #[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                actual: newDetailsLogEntry,
                repairHint: "Для append-only записи журнала квеста используй canonical historical-entry timestamp из Block 18.A. Legacy prefix '#[turn_number]. ...' всё ещё принимается для старого контента, но не обязателен."));
        }

        if (!string.IsNullOrWhiteSpace(status) && !AllowedQuestStatuses.Contains(status))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.status",
                IssueSeverity.Error,
                "Quest status должен быть одним из canonical enum значений",
                code: "quest_invalid_status",
                section: "Quest",
                expected: string.Join(" | ", AllowedQuestStatuses),
                actual: status,
                repairHint: "Используй для regular quests только status = Active, Completed, Failed или Updated."));
        }
    }

    private void ValidateSoulQuestObject(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        RequireString(item, itemContext, issues, "questId");
        RequireString(item, itemContext, issues, "guardianId");
        RequireString(item, itemContext, issues, "title");
        RequireString(item, itemContext, issues, "description");
        ValidateQuestObjectivesArray(
            item,
            itemContext,
            issues,
            AllowedSoulQuestObjectiveStatuses,
            "SoulQuests",
            "Используй для soul quest objectives только status = Active, Pending, Completed или Failed.");
        var status = RequireString(item, itemContext, issues, "status");

        if (!string.IsNullOrWhiteSpace(status) && !AllowedSoulQuestStatuses.Contains(status))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.status",
                IssueSeverity.Error,
                "Soul quest status должен быть одним из canonical enum значений",
                code: "soul_quest_invalid_status",
                section: "SoulQuests",
                expected: string.Join(" | ", AllowedSoulQuestStatuses),
                actual: status,
                repairHint: "Используй для soul quests только status = active, completed, failed или abandoned."));
        }

        if (!item.TryGetProperty("progress", out var progress) ||
            !RequireObject(progress, $"{itemContext}.progress", issues))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.progress",
                IssueSeverity.Error,
                "Soul quest должен содержать progress object",
                code: "soul_quest_missing_progress_object",
                section: "SoulQuests",
                expected: "progress object",
                actual: !item.TryGetProperty("progress", out var missingProgressNode) ? "missing" : missingProgressNode.ValueKind.ToString(),
                repairHint: "Добавь в soul quest canonical объект progress с integer-полями completed и total."));
        }
        else
        {
            ValidateNonNegativeIntegerField(progress, $"{itemContext}.progress", issues, "completed", "SoulQuests");
            ValidateNonNegativeIntegerField(progress, $"{itemContext}.progress", issues, "total", "SoulQuests");
        }

        if (!item.TryGetProperty("rewards", out var rewards) ||
            !RequireObject(rewards, $"{itemContext}.rewards", issues))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.rewards",
                IssueSeverity.Error,
                "Soul quest должен содержать rewards object",
                code: "soul_quest_missing_rewards_object",
                section: "SoulQuests",
                expected: "rewards object",
                actual: !item.TryGetProperty("rewards", out var missingRewardsNode) ? "missing" : missingRewardsNode.ValueKind.ToString(),
                repairHint: "Добавь в soul quest canonical объект rewards. Даже минимальные награды должны приходить как object, а не как missing/scalar payload."));
        }
        else
        {
            ValidateNonNegativeIntegerField(rewards, $"{itemContext}.rewards", issues, "inkFeathers", "SoulQuests");
            ValidateNonNegativeIntegerField(rewards, $"{itemContext}.rewards", issues, "enlightenmentExperience", "SoulQuests");
            if (rewards.TryGetProperty("soulRelics", out var soulRelics))
            {
                RequireArrayOfObjects(soulRelics, $"{itemContext}.rewards.soulRelics", issues);
                if (soulRelics.ValueKind == JsonValueKind.Array)
                {
                    var relicIndex = 0;
                    foreach (var relic in soulRelics.EnumerateArray())
                    {
                        var relicContext = $"{itemContext}.rewards.soulRelics[{relicIndex++}]";
                        if (!RequireObject(relic, relicContext, issues))
                            continue;

                        ValidateMinimalSoulRelicObject(relic, relicContext, issues, "SoulQuests");
                    }
                }
            }
            if (rewards.TryGetProperty("reputationChanges", out var reputationChanges))
            {
                RequireArrayOfObjects(reputationChanges, $"{itemContext}.rewards.reputationChanges", issues);
                if (reputationChanges.ValueKind == JsonValueKind.Array)
                {
                    var repIndex = 0;
                    foreach (var repChange in reputationChanges.EnumerateArray())
                    {
                        var repContext = $"{itemContext}.rewards.reputationChanges[{repIndex++}]";
                        if (!RequireObject(repChange, repContext, issues))
                            continue;

                        RequireString(repChange, repContext, issues, "guardianId");
                        ValidateIntegerField(repChange, repContext, issues, "change");
                    }
                }
            }
        }

        RequireBooleanField(item, itemContext, issues, "crossIncarnation");
        if (!item.TryGetProperty("completionTimestamp", out var completionTimestamp) ||
            completionTimestamp.ValueKind == JsonValueKind.Null)
            return;

        if (completionTimestamp.ValueKind != JsonValueKind.String)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.completionTimestamp",
                IssueSeverity.Error,
                "completionTimestamp должен быть строкой ISO 8601 timestamp или null",
                code: "soul_quest_completion_timestamp_invalid_type",
                section: "SoulQuests",
                expected: "ISO 8601 timestamp or null",
                actual: completionTimestamp.ValueKind.ToString(),
                repairHint: "Для незавершённого soul quest оставляй completionTimestamp = null. Для завершённого передай completionTimestamp как ISO 8601 строку."));
            return;
        }

        var completionTimestampValue = completionTimestamp.GetString() ?? string.Empty;
        if (string.IsNullOrWhiteSpace(completionTimestampValue) || !DateTimeOffset.TryParse(completionTimestampValue, out _))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.completionTimestamp",
                IssueSeverity.Error,
                "completionTimestamp должен быть ISO 8601 timestamp или null",
                code: "soul_quest_completion_timestamp_invalid",
                section: "SoulQuests",
                expected: "ISO 8601 timestamp or null",
                actual: string.IsNullOrWhiteSpace(completionTimestampValue) ? "empty string" : completionTimestampValue,
                repairHint: "Для незавершённого soul quest оставляй completionTimestamp = null. Для завершённого передай completionTimestamp как ISO 8601 строку."));
        }
    }

