    private void ValidateQuestObjectivesArray(
        JsonElement item,
        string itemContext,
        List<ValidationIssue> issues,
        HashSet<string> allowedStatuses,
        string section,
        string repairHint)
    {
        if (!item.TryGetProperty("objectives", out var objectives))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.objectives",
                IssueSeverity.Error,
                "Квест должен содержать objectives"));
            return;
        }
        if (objectives.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.objectives",
                IssueSeverity.Error,
                "objectives должен быть массивом"));
            return;
        }

        var objectiveIndex = 0;
        foreach (var objective in objectives.EnumerateArray())
        {
            var objectiveContext = $"{itemContext}.objectives[{objectiveIndex++}]";
            if (!RequireObject(objective, objectiveContext, issues))
                continue;

            RequireString(objective, objectiveContext, issues, "description");
            var objectiveStatus = RequireString(objective, objectiveContext, issues, "status");
            ValidateRequiredNullableStringField(objective, objectiveContext, issues, "objectiveId");

            if (!string.IsNullOrWhiteSpace(objectiveStatus) && !allowedStatuses.Contains(objectiveStatus))
            {
                issues.Add(new ValidationIssue(
                    $"{objectiveContext}.status",
                    IssueSeverity.Error,
                    "Quest objective status должен быть одним из canonical enum значений",
                    code: "quest_objective_invalid_status",
                    section: section,
                    expected: string.Join(" | ", allowedStatuses),
                    actual: objectiveStatus,
                    repairHint: repairHint));
            }
        }
    }

    private void ValidateQuestRewardsObject(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        if (!item.TryGetProperty("rewards", out var rewards))
            return;

        if (!RequireObject(rewards, $"{itemContext}.rewards", issues))
            return;

        ValidateNonNegativeIntegerField(rewards, $"{itemContext}.rewards", issues, "experience", "Quest");
        ValidateNonNegativeIntegerField(rewards, $"{itemContext}.rewards", issues, "money", "Quest");
        if (rewards.TryGetProperty("items", out var rewardItems))
            RequireArrayOfStrings(rewardItems, $"{itemContext}.rewards.items", issues);
        ValidateOptionalString(rewards, $"{itemContext}.rewards", issues, "other");
    }

    private static bool LooksLikeFullQuestObject(JsonElement item)
    {
        return HasNonEmptyString(item, "status") &&
               HasNonEmptyString(item, "questGiver") &&
               HasNonEmptyString(item, "questBackground") &&
               HasNonEmptyString(item, "description") &&
               item.TryGetProperty("objectives", out var objectives) &&
               objectives.ValueKind == JsonValueKind.Array &&
               item.TryGetProperty("detailsLog", out var detailsLog) &&
               detailsLog.ValueKind == JsonValueKind.Array;
    }

    private void ValidateDifficultyProfileObject(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var profile))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} обязателен для локации",
                code: "location_missing_difficulty_profile",
                section: "Location",
                expected: $"{propName} object with combat/environment/social/exploration integer scales",
                actual: "missing property",
                repairHint: $"Добавь в location object поле {propName} с integer-полями combat, environment, social и exploration."));
            return;
        }

        if (!RequireObject(profile, $"{contextPrefix}.{propName}", issues))
            return;

        foreach (var scale in new[] { "combat", "environment", "social", "exploration" })
            ValidateNonNegativeIntegerField(profile, $"{contextPrefix}.{propName}", issues, scale, "Location");
    }

    private void ValidateFactionControlArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var value))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} обязателен и должен быть массивом или null",
                code: "location_missing_faction_control_array",
                section: "Location",
                expected: $"{propName} array or null",
                actual: "missing property",
                repairHint: $"Добавь в location object поле {propName}. Используй null, если контролирующих фракций нет, или массив canonical factionControl entries."));
            return;
        }

        if (value.ValueKind == JsonValueKind.Null)
            return;
        if (value.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} должен быть массивом или null",
                code: "location_invalid_faction_control_array_shape",
                section: "Location",
                expected: $"{propName} array or null",
                actual: value.ValueKind.ToString(),
                repairHint: $"Передавай {propName} как null или массив factionControl entries, а не как {value.ValueKind}."));
            return;
        }

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;
            RequireString(item, itemContext, issues, "factionId");
            RequireString(item, itemContext, issues, "factionName");
            var controlType = RequireString(item, itemContext, issues, "controlType");
            if (!string.IsNullOrWhiteSpace(controlType) && !AllowedLocationControlTypes.Contains(controlType))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.controlType",
                    IssueSeverity.Error,
                    "factionControl.controlType должен быть одним из canonical enum значений",
                    code: "location_faction_control_invalid_type",
                    section: "Location",
                    expected: string.Join(" | ", AllowedLocationControlTypes),
                    actual: controlType,
                    repairHint: "Используй в factionControl.controlType только Military, Economic, Social или Covert по Block 20.2.A."));
            }

            ValidateIntegerField(item, itemContext, issues, "controlLevel");
            if (TryReadInt(item, "controlLevel", out var controlLevel) &&
                (controlLevel < 0 || controlLevel > 100))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.controlLevel",
                    IssueSeverity.Error,
                    "factionControl.controlLevel должен быть в диапазоне 0..100",
                    code: "location_faction_control_level_out_of_bounds",
                    section: "Location",
                    expected: "0..100",
                    actual: controlLevel.ToString(),
                    repairHint: "Сохраняй factionControl.controlLevel как integer от 0 до 100 по Block 20.2.A."));
            }
        }
    }

    private void ValidateLocationAdjacencyArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var value))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} обязателен и должен быть массивом или null",
                code: "location_missing_adjacency_array",
                section: "Location",
                expected: $"{propName} array or null",
                actual: "missing property",
                repairHint: $"Добавь в location object поле {propName}. Используй null, если явных adjacency links нет, или массив canonical link objects."));
            return;
        }

        if (value.ValueKind == JsonValueKind.Null)
            return;
        if (value.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} должен быть массивом или null",
                code: "location_invalid_adjacency_array_shape",
                section: "Location",
                expected: $"{propName} array or null",
                actual: value.ValueKind.ToString(),
                repairHint: $"Передавай {propName} как null или массив canonical adjacency links, а не как {value.ValueKind}."));
            return;
        }

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            ValidateWorldMapAdjacencyLinkObject(item, itemContext, issues);
        }
    }

