    private void ValidateActiveThreatArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var value))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} обязателен и должен быть массивом или null",
                code: "location_missing_active_threat_array",
                section: "Location",
                expected: $"{propName} array or null",
                actual: "missing property",
                repairHint: $"Добавь в location object поле {propName}. Используй null, если активных угроз нет, или массив canonical Active Threat Objects."));
            return;
        }

        if (value.ValueKind == JsonValueKind.Null)
            return;
        if (value.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} должен быть массивом или null",
                code: "location_invalid_active_threat_array_shape",
                section: "Location",
                expected: $"{propName} array or null",
                actual: value.ValueKind.ToString(),
                repairHint: $"Передавай {propName} как null или массив canonical Active Threat Objects, а не как {value.ValueKind}."));
            return;
        }

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            ValidateActiveThreatObject(item, itemContext, issues, requireNullThreatId: false);
        }
    }

    private static bool IsLikelyFullFactionObject(JsonElement item)
    {
        return item.TryGetProperty("powerProfile", out _) ||
               item.TryGetProperty("resources", out _) ||
               item.TryGetProperty("ranks", out _) ||
               item.TryGetProperty("relations", out _) ||
               item.TryGetProperty("isPlayerFaction", out _) ||
               item.TryGetProperty("isPlayerMember", out _);
    }

    private void ValidateFullFactionObject(JsonElement item, string itemContext, List<ValidationIssue> issues,
        HashSet<string>? knownPermanentFactionIds, HashSet<string>? knownCanonicalFactionNames)
    {
        var factionId = GetFirstNonEmptyString(item, "factionId");
        var initialId = GetFirstNonEmptyString(item, "initialId");
        var factionName = GetFirstNonEmptyString(item, "name", "factionName");
        var hasFactionId = !string.IsNullOrWhiteSpace(factionId);
        var hasInitialId = !string.IsNullOrWhiteSpace(initialId);

        if (!hasFactionId && !hasInitialId)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.factionId",
                IssueSeverity.Error,
                "Faction Data Object должен содержать permanent factionId для existing faction или initialId для новой same-turn faction",
                code: "faction_full_object_missing_identity",
                section: "Factions",
                repairHint: "Для existing faction передай factionId. Для новой same-turn faction используй factionId=null и непустой initialId."));
        }

        if (hasFactionId && hasInitialId)
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.initialId",
                IssueSeverity.Error,
                "initialId допустим только для новой same-turn faction и не должен присутствовать у existing faction object",
                code: "faction_full_object_conflicting_identity",
                section: "Factions",
                repairHint: "У existing faction оставь только permanent factionId. initialId используй только при создании новой фракции в том же ходу."));
        }

        if (!hasFactionId && hasInitialId)
        {
            if (!TempFactionInitialIdRegex.IsMatch(initialId!))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.initialId",
                    IssueSeverity.Error,
                    "initialId новой фракции должен использовать canonical temp-faction-* формат",
                    code: "faction_full_object_initial_id_invalid_format",
                    section: "Factions",
                    expected: "temp-faction-[description]",
                    actual: initialId,
                    repairHint: "Для genuinely new same-turn faction используй initialId в формате temp-faction-[short-description]."));
            }

            if (!item.TryGetProperty("factionId", out var explicitFactionIdNode) ||
                explicitFactionIdNode.ValueKind != JsonValueKind.Null)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.factionId",
                    IssueSeverity.Error,
                    "Новая same-turn faction в factionDataChanges должна явно передавать factionId = null вместе с initialId",
                    code: "faction_full_object_requires_explicit_null_faction_id",
                    section: "Factions",
                    expected: "factionId = null for genuinely new same-turn faction",
                    actual: item.TryGetProperty("factionId", out var actualFactionIdNode)
                        ? actualFactionIdNode.ValueKind.ToString()
                        : "missing",
                    repairHint: "Для новой same-turn faction передай factionId: null и непустой initialId. Для existing faction используй permanent factionId."));
            }

            if (!item.TryGetProperty("isNewFaction", out var isNewFactionNode) ||
                isNewFactionNode.ValueKind != JsonValueKind.True)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.isNewFaction",
                    IssueSeverity.Error,
                    "Новая same-turn faction в factionDataChanges должна явно помечаться isNewFaction = true",
                    code: "faction_full_object_requires_explicit_create_flag",
                    section: "Factions",
                    expected: "isNewFaction = true for genuinely new same-turn faction",
                    actual: item.TryGetProperty("isNewFaction", out var actualCreateNode)
                        ? actualCreateNode.ValueKind.ToString()
                        : "missing",
                    repairHint: "Для действительно новой фракции передай isNewFaction: true. Existing faction всегда обновляй через permanent factionId без initialId."));
            }

            if (!HasAnyNonEmptyString(item, "image_prompt"))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.image_prompt",
                    IssueSeverity.Error,
                    "Новая same-turn faction в factionDataChanges должна содержать image_prompt",
                    code: "faction_full_object_new_requires_image_prompt",
                    section: "Factions",
                    expected: "non-empty image_prompt for newly created faction",
                    actual: "missing",
                    repairHint: "Для новой фракции передай английский image_prompt, описывающий символ, знамя или штаб-квартиру фракции."));
            }
            else
            {
                var imagePrompt = GetFirstNonEmptyString(item, "image_prompt") ?? string.Empty;
                if (!LooksLikeEnglishImagePrompt(imagePrompt))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.image_prompt",
                        IssueSeverity.Error,
                        "image_prompt новой фракции должен быть English-only и не длиннее 150 символов",
                        code: "faction_full_object_image_prompt_invalid",
                        section: "Factions",
                        expected: "English prompt, <= 150 chars",
                        actual: imagePrompt.Length > 150 ? $">150 chars ({imagePrompt.Length})" : imagePrompt,
                        repairHint: "Используй для новой фракции краткий English-only image_prompt без кириллицы и длиннее 150 символов."));
                }
            }
        }

        if (hasFactionId &&
            knownPermanentFactionIds != null &&
            !knownPermanentFactionIds.Contains(factionId!))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.factionId",
                IssueSeverity.Error,
                $"Full faction object ссылается на неизвестный factionId '{factionId}'",
                code: "faction_full_object_unknown_faction_id",
                section: "Factions",
                expected: "existing permanent factionId from faction_core.json",
                actual: factionId,
                repairHint: "Для existing faction используй существующий factionId. Новую same-turn faction создавай через factionId=null и непустой initialId."));
        }

        if (!hasFactionId &&
            hasInitialId &&
            knownPermanentFactionIds != null &&
            knownPermanentFactionIds.Contains(initialId!))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.initialId",
                IssueSeverity.Error,
                $"initialId '{initialId}' конфликтует с уже существующим permanent factionId",
                code: "faction_full_object_initial_id_conflicts_with_existing_faction_id",
                section: "Factions",
                expected: "new temporary initialId that does not collide with existing permanent factionId",
                actual: initialId,
                repairHint: "Для existing faction используй permanent factionId. Для genuinely new same-turn faction выбери новый temporary initialId, который не совпадает с существующими factionId."));
        }

        if (!hasFactionId &&
            hasInitialId &&
            knownCanonicalFactionNames != null &&
            !string.IsNullOrWhiteSpace(factionName) &&
            knownCanonicalFactionNames.Contains(factionName))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.initialId",
                IssueSeverity.Error,
                $"Full faction object использует initialId для уже существующей фракции '{factionName}'",
                code: "faction_full_object_existing_requires_faction_id",
                section: "Factions",
                expected: "permanent factionId for existing faction",
                actual: $"initialId={initialId}",
                repairHint: "Если фракция уже существует в canonical faction_core.json, передай её permanent factionId. initialId оставляй только для genuinely new same-turn faction."));
        }

        RequireString(item, itemContext, issues, "name");
        RequireString(item, itemContext, issues, "description");
        ValidateOptionalString(item, itemContext, issues, "factionColor");
        RequireObjectProperty(item, itemContext, issues, "powerProfile");
        RequireObjectProperty(item, itemContext, issues, "resources");
        RequireObjectProperty(item, itemContext, issues, "ranks");
        RequireBooleanField(item, itemContext, issues, "isPlayerFaction");
        RequireBooleanField(item, itemContext, issues, "isPlayerMember");
        RequireNumberOrString(item, itemContext, issues, "level");
        RequireNumberOrString(item, itemContext, issues, "experience");
        RequireNumberOrString(item, itemContext, issues, "experienceForNextLevel");
        RequireString(item, itemContext, issues, "developmentArchetype");
        RequireNumberOrString(item, itemContext, issues, "reputation");
        ValidateOptionalString(item, itemContext, issues, "playerRank");
        ValidateOptionalString(item, itemContext, issues, "playerBranch");
        ValidateOptionalString(item, itemContext, issues, "playerStrategyDirective");
        ValidateOptionalString(item, itemContext, issues, "reputationDescription");
        ValidateOptionalString(item, itemContext, issues, "image_prompt");

        if (item.TryGetProperty("powerProfile", out var powerProfile) &&
            RequireObject(powerProfile, $"{itemContext}.powerProfile", issues))
        {
            foreach (var scale in new[] { "military", "economic", "social", "covert", "logistics", "stability", "arcane_tech", "exploration" })
            {
                if (!powerProfile.TryGetProperty(scale, out _))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.powerProfile.{scale}",
                        IssueSeverity.Error,
                        "powerProfile scale обязателен в полном faction object",
                        code: "faction_full_object_missing_power_profile_scale",
                        section: "Factions",
                        expected: $"powerProfile.{scale}",
                        actual: "missing property",
                        repairHint: $"Для полного faction object добавь integer/number поле powerProfile.{scale}."));
                }
                else
                {
                    ValidateNonNegativeNumberField(powerProfile, $"{itemContext}.powerProfile", issues, scale);
                }
            }
        }

        if (item.TryGetProperty("resources", out var resources) &&
            RequireObject(resources, $"{itemContext}.resources", issues))
        {
            if (!resources.TryGetProperty("metaResources", out var metaResources))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.resources.metaResources",
                    IssueSeverity.Error,
                    "resources.metaResources обязателен в полном faction-core object",
                    code: "faction_full_object_missing_meta_resources",
                    section: "Factions",
                    expected: "resources.metaResources array",
                    actual: "missing property",
                    repairHint: "Для полного faction-core object добавь resources.metaResources как canonical array meta resource entries."));
            }
            else
            {
                ValidateFactionSidecarResourceArray(metaResources, $"{itemContext}.resources.metaResources", issues, requireUpkeep: true);
            }

            if (!resources.TryGetProperty("strategicGoods", out var strategicGoods))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.resources.strategicGoods",
                    IssueSeverity.Error,
                    "resources.strategicGoods обязателен в полном faction-core object",
                    code: "faction_full_object_missing_strategic_goods",
                    section: "Factions",
                    expected: "resources.strategicGoods array",
                    actual: "missing property",
                    repairHint: "Для полного faction-core object добавь resources.strategicGoods как canonical array strategic goods entries."));
            }
            else
            {
                ValidateFactionSidecarResourceArray(strategicGoods, $"{itemContext}.resources.strategicGoods", issues, requireUpkeep: false);
            }
        }

        var rankNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (item.TryGetProperty("ranks", out var ranks) &&
            RequireObject(ranks, $"{itemContext}.ranks", issues))
        {
            if (!TryGetArray(ranks, "branches", $"{itemContext}.ranks.branches", issues, out var branches))
                return;

            var branchIndex = 0;
            foreach (var branch in branches.EnumerateArray())
            {
                var branchContext = $"{itemContext}.ranks.branches[{branchIndex++}]";
                if (!RequireObject(branch, branchContext, issues))
                    continue;

                RequireString(branch, branchContext, issues, "branchId");
                RequireString(branch, branchContext, issues, "displayName");
                RequireBooleanField(branch, branchContext, issues, "isCoreBranch");
                if (!TryGetArray(branch, "ranks", $"{branchContext}.ranks", issues, out var branchRanks))
                    continue;

                var rankIndex = 0;
                foreach (var rank in branchRanks.EnumerateArray())
                {
                    var rankContext = $"{branchContext}.ranks[{rankIndex++}]";
                    if (!RequireObject(rank, rankContext, issues))
                        continue;

                    var rankNameMale = RequireString(rank, rankContext, issues, "rankNameMale");
                    var rankNameFemale = RequireString(rank, rankContext, issues, "rankNameFemale");
                    RequireNumberOrString(rank, rankContext, issues, "requiredReputation");
                    RequireString(rank, rankContext, issues, "unlockCondition");
                    RequireBooleanField(rank, rankContext, issues, "isJunctionPoint");
                    if (rank.TryGetProperty("availableBranches", out var availableBranches))
                        RequireArrayOfStrings(availableBranches, $"{rankContext}.availableBranches", issues);
                    if (rank.TryGetProperty("benefits", out var benefits) && benefits.ValueKind != JsonValueKind.String)
                        RequireArrayOfStrings(benefits, $"{rankContext}.benefits", issues);

                    if (!string.IsNullOrWhiteSpace(rankNameMale))
                        rankNames.Add(rankNameMale);
                    if (!string.IsNullOrWhiteSpace(rankNameFemale))
                        rankNames.Add(rankNameFemale);
                }
            }
        }

        var playerRank = GetFirstNonEmptyString(item, "playerRank");
        if (!string.IsNullOrWhiteSpace(playerRank) && rankNames.Count > 0 && !rankNames.Contains(playerRank))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.playerRank",
                IssueSeverity.Error,
                "playerRank должен совпадать с одним из rankNameMale/rankNameFemale в ranks.branches[].ranks[]"));
        }

        if (item.TryGetProperty("relations", out var relations))
        {
            if (relations.ValueKind == JsonValueKind.Array)
            {
                var relationIndex = 0;
                foreach (var relation in relations.EnumerateArray())
                {
                    var relationContext = $"{itemContext}.relations[{relationIndex++}]";
                    if (!RequireObject(relation, relationContext, issues))
                        continue;
                    RequireString(relation, relationContext, issues, "targetFactionId");
                    RequireString(relation, relationContext, issues, "status");
                    RequireString(relation, relationContext, issues, "description");
                }
            }
            else if (relations.ValueKind != JsonValueKind.Null)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.relations",
                    IssueSeverity.Error,
                    "relations должен быть массивом или null",
                    code: "faction_relations_invalid_array_shape",
                    section: "Factions",
                    expected: "relations array or null",
                    actual: relations.ValueKind.ToString(),
                    repairHint: "Передавай relations как null или массив canonical faction relation objects."));
            }
        }

        ValidateFactionExtendedFields(item, itemContext, issues);
        if (TryDescribeIncompleteFullFactionExtensionArray(item, out var extensionField, out var extensionActual))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.{extensionField}",
                IssueSeverity.Error,
                extensionField.Equals("customStates", StringComparison.OrdinalIgnoreCase)
                    ? "Full faction-core object must not use skeletal customStates"
                    : "Full faction-core object must not use partial optional extension data",
                code: extensionField.Equals("customStates", StringComparison.OrdinalIgnoreCase)
                    ? "faction_full_object_skeletal_custom_states"
                    : "faction_full_object_partial_optional_extension_data",
                section: "Factions",
                expected: "Canonical complete objects inside optional extension arrays of the full faction object",
                actual: extensionActual,
                repairHint: "Если полный faction-core object включает optional arrays вроде customStates/relations/projects/territories/structuredBonuses, каждый entry уже должен быть canonical complete data, а не skeletal delta."));

            issues.Add(new ValidationIssue(
                $"{itemContext}.{extensionField}",
                IssueSeverity.Error,
                itemContext.Contains(".factionDataChanges[", StringComparison.OrdinalIgnoreCase)
                    ? "Optional extension arrays inside factionDataChanges must already be canonical complete data"
                    : "Optional extension arrays inside full faction objects must already be canonical complete data",
                code: "faction_full_object_incomplete_optional_extension_array",
                section: "Factions",
                expected: "Canonical complete data in optional extension arrays",
                actual: extensionActual,
                repairHint: "Для full-object authoring не отправляй skeletal fragments в optional arrays. Передавай полностью заполненные canonical entries или используй отдельные sidecar/command surfaces для частичных изменений."));
        }
        if (item.TryGetProperty("customStates", out var customStates) &&
            customStates.ValueKind != JsonValueKind.Null)
        {
            ValidateArrayItems(customStates, $"{itemContext}.customStates", issues, ValidateCanonicalFactionCustomStateObject);
        }
        ValidateFactionProjectArray(item, itemContext, issues, "activeProjects", completed: false);
        ValidateFactionProjectArray(item, itemContext, issues, "completedProjects", completed: true);
    }

    private void ValidateFactionProjectArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName, bool completed)
    {
        if (!root.TryGetProperty(propName, out var value))
            return;
        if (value.ValueKind == JsonValueKind.Null)
            return;
        if (value.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} должен быть массивом или null",
                code: "faction_project_array_invalid_shape",
                section: "Factions",
                expected: $"{propName} array or null",
                actual: value.ValueKind.ToString(),
                repairHint: $"Передавай {propName} как null или массив canonical faction project objects."));
            return;
        }

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;
            ValidateFactionFullProjectObject(item, itemContext, issues, completed);
        }
    }

    private static bool TryDescribeIncompleteFullFactionExtensionArray(JsonElement item, out string fieldName, out string actual)
    {
        if (item.TryGetProperty("customStates", out var customStates) &&
            ArrayContainsIncompleteObjects(customStates, IsIncompleteFactionCustomState))
        {
            fieldName = "customStates";
            actual = "customStates contains skeletal entries without canonical currentValue/minValue/maxValue/description/progressionRule/thresholds";
            return true;
        }

        if (item.TryGetProperty("relations", out var relations) &&
            ArrayContainsIncompleteObjects(relations, relation =>
                !HasRequiredNonEmptyStrings(relation, "targetFactionId", "status", "description")))
        {
            fieldName = "relations";
            actual = "relations contains partial entries without targetFactionId/status/description";
            return true;
        }

        if (item.TryGetProperty("controlledTerritories", out var territories) &&
            ArrayContainsIncompleteObjects(territories, territory =>
                !HasRequiredNonEmptyStrings(territory, "locationId", "locationName")))
        {
            fieldName = "controlledTerritories";
            actual = "controlledTerritories contains partial entries without locationId/locationName";
            return true;
        }

        if (item.TryGetProperty("structuredBonuses", out var structuredBonuses) &&
            ArrayContainsIncompleteObjects(structuredBonuses, bonus =>
                !HasRequiredNonEmptyStrings(bonus, "description", "bonusType", "target", "valueType", "application") ||
                !HasRequiredProperties(bonus, "value")))
        {
            fieldName = "structuredBonuses";
            actual = "structuredBonuses contains partial bonus objects";
            return true;
        }

        if (item.TryGetProperty("activeProjects", out var activeProjects) &&
            ArrayContainsIncompleteObjects(activeProjects, project =>
                !HasRequiredNonEmptyStrings(project, "projectId", "projectName", "activeState")))
        {
            fieldName = "activeProjects";
            actual = "activeProjects contains partial project entries";
            return true;
        }

        if (item.TryGetProperty("completedProjects", out var completedProjects) &&
            ArrayContainsIncompleteObjects(completedProjects, project =>
                !HasRequiredNonEmptyStrings(project, "projectId", "projectName", "finalState") ||
                !HasRequiredProperties(project, "completionTurn")))
        {
            fieldName = "completedProjects";
            actual = "completedProjects contains partial project entries";
            return true;
        }

        fieldName = string.Empty;
        actual = string.Empty;
        return false;
    }

    private static bool ArrayContainsIncompleteObjects(JsonElement value, Func<JsonElement, bool> isIncomplete)
    {
        if (value.ValueKind != JsonValueKind.Array)
            return false;

        foreach (var item in value.EnumerateArray())
        {
            if (isIncomplete(item))
                return true;
        }

        return false;
    }

    private static bool IsIncompleteFactionCustomState(JsonElement item)
    {
        return item.ValueKind != JsonValueKind.Object ||
               !HasAnyNonEmptyString(item, "stateName", "stateKey", "key", "name", "title") ||
               !HasRequiredProperties(item, "currentValue", "minValue", "maxValue", "description", "progressionRule", "thresholds");
    }

    private static bool HasRequiredProperties(JsonElement item, params string[] propertyNames)
    {
        if (item.ValueKind != JsonValueKind.Object)
            return false;

        foreach (var propertyName in propertyNames)
        {
            if (!item.TryGetProperty(propertyName, out var value) || value.ValueKind == JsonValueKind.Null)
                return false;
        }

        return true;
    }

    private static bool HasRequiredNonEmptyStrings(JsonElement item, params string[] propertyNames)
    {
        if (item.ValueKind != JsonValueKind.Object)
            return false;

        foreach (var propertyName in propertyNames)
        {
            if (!HasNonEmptyString(item, propertyName))
                return false;
        }

        return true;
    }

    private void RequireBooleanField(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!root.TryGetProperty(propName, out var value))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"Отсутствует обязательное boolean поле: {propName}",
                code: "missing_required_boolean_field",
                expected: "boolean",
                actual: "missing",
                repairHint: $"Добавь обязательное boolean поле {propName} со значением true или false по canonical contract."));
            return;
        }

        if (value.ValueKind is not (JsonValueKind.True or JsonValueKind.False))
        {
            issues.Add(new ValidationIssue(
                $"{contextPrefix}.{propName}",
                IssueSeverity.Error,
                $"{propName} должен быть boolean",
                code: "invalid_boolean_field",
                expected: "boolean",
                actual: value.ValueKind.ToString(),
                repairHint: $"Сохраняй {propName} как boolean true/false по canonical contract."));
        }
    }

    private void ValidateLooseStringOrObjectArray(JsonElement value, string context, List<ValidationIssue> issues)
    {
        if (value.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "Поле должно быть массивом строк или объектов",
                code: "expected_string_or_object_array",
                expected: "JSON array of strings or objects",
                actual: value.ValueKind.ToString(),
                repairHint: "Сохрани поле как массив, где каждый элемент является строкой или JSON object."));
            return;
        }

        var index = 0;
        foreach (var item in value.EnumerateArray())
        {
            if (item.ValueKind is not (JsonValueKind.String or JsonValueKind.Object))
            {
                issues.Add(new ValidationIssue(
                    $"{context}[{index}]",
                    IssueSeverity.Error,
                    "Элемент должен быть строкой или объектом",
                    code: "invalid_string_or_object_array_item",
                    expected: "string or object",
                    actual: item.ValueKind.ToString(),
                    repairHint: "Исправь элемент массива до непустой строки или JSON object по canonical contract."));
            }
            index++;
        }
    }

    private void ValidateCurrentLocationData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        var found = false;
        if (root.TryGetProperty("currentLocationData", out var location))
        {
            found = true;
            var locationContext = $"{contextPrefix}.currentLocationData";
            ValidateCurrentLocationResponseObject(location, locationContext, issues);
        }
        else if (root.ValueKind == JsonValueKind.Object &&
                 (root.TryGetProperty("locationId", out _) || root.TryGetProperty("locationType", out _)))
        {
            found = true;
            ValidateLocationObject(root, contextPrefix, issues);
        }

        if (!found && contextPrefix.EndsWith("current_location.json", StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                contextPrefix,
                IssueSeverity.Warning,
                "Файл локации не содержит currentLocationData и не похож на нормализованный location object",
                code: "current_location_missing_root_object",
                section: "Location",
                expected: "currentLocationData object or normalized location object",
                actual: "missing recognizable location root",
                repairHint: "Сохрани либо currentLocationData, либо нормализованный location object. Не оставляй current_location.json пустым или с нерелевантным root shape."));
        }
    }

    private void ValidateCurrentLocationResponseObject(JsonElement location, string context, List<ValidationIssue> issues)
    {
        if (!RequireObject(location, context, issues))
            return;

        if (!location.TryGetProperty("locationId", out var locationId))
        {
            issues.Add(new ValidationIssue(
                $"{context}.locationId",
                IssueSeverity.Error,
                "currentLocationData должен явно задавать locationId: GUID для известной локации или null для новой",
                code: "current_location_missing_location_id",
                section: "Location",
                expected: "string locationId or null for a new location",
                actual: "missing",
                repairHint: "Для known location передай locationId существующей локации, её coordinates и only lastEventsDescription. Для новой локации передай полный объект с locationId = null."));
            return;
        }

        if (locationId.ValueKind == JsonValueKind.Null)
        {
            ValidateNewLocationObject(location, context, issues);
            return;
        }

        if (locationId.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(locationId.GetString()))
        {
            issues.Add(new ValidationIssue(
                $"{context}.locationId",
                IssueSeverity.Error,
                "currentLocationData.locationId должен быть непустым GUID или null",
                code: "current_location_invalid_location_id",
                section: "Location",
                expected: "non-empty string GUID or null",
                actual: locationId.ValueKind.ToString(),
                repairHint: "Для known location используй её existing GUID. Только для truly new location передавай locationId = null."));
            return;
        }

        if (!location.TryGetProperty("coordinates", out var coordinates))
        {
            issues.Add(new ValidationIssue(
                $"{context}.coordinates",
                IssueSeverity.Error,
                "Для известной currentLocationData обязательно передавать coordinates",
                code: "current_location_missing_coordinates",
                section: "Location",
                expected: "coordinates object from the known location",
                actual: "missing",
                repairHint: "При возврате в known location передай её existing locationId, coordinates и lastEventsDescription. Legacy локации без z всё ещё допускаются как x/y-only coordinates."));
            return;
        }

        ValidateLocationCoordinatesObject(
            coordinates,
            $"{context}.coordinates",
            issues,
            allowLegacyMissingZ: true,
            section: "Location");

        if (location.TryGetProperty("internalDifficultyProfile", out _))
            ValidateDifficultyProfileObject(location, context, issues, "internalDifficultyProfile");

        if (location.TryGetProperty("externalDifficultyProfile", out _))
            ValidateDifficultyProfileObject(location, context, issues, "externalDifficultyProfile");

        if (location.TryGetProperty("locationStorages", out _))
            ValidateLocationStorageArray(location, context, issues, "locationStorages");

        var lastEventsDescription = RequireString(location, context, issues, "lastEventsDescription");
        if (!string.IsNullOrWhiteSpace(lastEventsDescription) &&
            !MatchesHistoricalEntryContract(lastEventsDescription))
        {
            issues.Add(new ValidationIssue(
                $"{context}.lastEventsDescription",
                IssueSeverity.Error,
                "currentLocationData.lastEventsDescription должен использовать canonical historical-entry timestamp format",
                code: "current_location_last_events_timestamp_invalid",
                section: "Location",
                expected: "#[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                actual: lastEventsDescription,
                repairHint: "При переходе в известную локацию передавай locationId, coordinates и lastEventsDescription с canonical timestamp-префиксом из Block 18.A."));
        }

        var forbiddenFields = location.EnumerateObject()
            .Where(prop => !string.Equals(prop.Name, "locationId", StringComparison.OrdinalIgnoreCase) &&
                           !string.Equals(prop.Name, "coordinates", StringComparison.OrdinalIgnoreCase) &&
                           !string.Equals(prop.Name, "lastEventsDescription", StringComparison.OrdinalIgnoreCase) &&
                           !string.Equals(prop.Name, "internalDifficultyProfile", StringComparison.OrdinalIgnoreCase) &&
                           !string.Equals(prop.Name, "externalDifficultyProfile", StringComparison.OrdinalIgnoreCase) &&
                           !string.Equals(prop.Name, "locationStorages", StringComparison.OrdinalIgnoreCase))
            .Select(prop => prop.Name)
            .ToList();
        if (forbiddenFields.Count > 0)
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "Для известной currentLocationData запрещён полный location object resend",
                code: "current_location_known_location_resends_full_object",
                section: "Location",
                expected: "locationId + coordinates + lastEventsDescription, optionally internalDifficultyProfile/externalDifficultyProfile/locationStorages",
                actual: string.Join(", ", forbiddenFields),
                repairHint: "Для known location передавай только locationId, coordinates, lastEventsDescription и при необходимости обновляемые internalDifficultyProfile/externalDifficultyProfile/locationStorages. Полный объект допустим только для truly new location с locationId = null."));
        }
    }

    private void ValidateWorldMapUpdates(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        JsonElement updates;
        string context;
        if (root.TryGetProperty("worldMapUpdates", out updates))
        {
            context = $"{contextPrefix}.worldMapUpdates";
            if (!RequireObject(updates, context, issues))
                return;
        }
        else
        {
            updates = root;
            context = contextPrefix;
        }

        if (updates.TryGetProperty("newLocations", out var newLocations))
        {
            RequireArrayOfObjects(newLocations, $"{context}.newLocations", issues);
            if (newLocations.ValueKind == JsonValueKind.Array)
            {
                var index = 0;
                foreach (var item in newLocations.EnumerateArray())
                {
                    if (item.ValueKind == JsonValueKind.Object)
                        ValidateNewLocationObject(item, $"{context}.newLocations[{index}]", issues);
                    index++;
                }
            }
        }
        if (updates.TryGetProperty("newLinks", out var newLinks))
            ValidateWorldMapNewLinks(newLinks, $"{context}.newLinks", issues);
        if (updates.TryGetProperty("locationUpdates", out var locationUpdates))
            ValidateLocationUpdateArray(locationUpdates, $"{context}.locationUpdates", issues);
        if (updates.TryGetProperty("storageUpdates", out var storageUpdates))
            ValidateLocationStorageUpdates(storageUpdates, $"{context}.storageUpdates", issues);
        if (updates.TryGetProperty("storagesToRemove", out var storagesToRemove))
            ValidateLocationStorageRemovals(storagesToRemove, $"{context}.storagesToRemove", issues);
        if (updates.TryGetProperty("linkUpdates", out var linkUpdates))
            ValidateLocationLinkUpdates(linkUpdates, $"{context}.linkUpdates", issues);
        if (updates.TryGetProperty("linksToRemove", out var linksToRemove))
            ValidateLocationLinkRemovals(linksToRemove, $"{context}.linksToRemove", issues);
        if (updates.TryGetProperty("threatsToAdd", out var threatsToAdd))
            ValidateLocationThreatAdds(threatsToAdd, $"{context}.threatsToAdd", issues);
        if (updates.TryGetProperty("threatsToUpdate", out var threatsToUpdate))
            ValidateLocationThreatUpdates(threatsToUpdate, $"{context}.threatsToUpdate", issues);
        if (updates.TryGetProperty("threatsToRemove", out var threatsToRemove))
            ValidateLocationThreatRemovals(threatsToRemove, $"{context}.threatsToRemove", issues);
        if (updates.TryGetProperty("completeThreatActivities", out var completeThreatActivities))
            ValidateLocationThreatCompletions(completeThreatActivities, $"{context}.completeThreatActivities", issues);
    }

    private void ValidateLocationObject(JsonElement location, string context, List<ValidationIssue> issues)
    {
        if (!RequireObject(location, context, issues))
            return;

        if (!HasAnyNonEmptyString(location, "locationId", "name"))
        {
            issues.Add(new ValidationIssue(context, IssueSeverity.Error,
                "Локация должна содержать locationId или name",
                code: "location_missing_identity",
                section: "Location",
                expected: "locationId or name",
                actual: "missing identity fields",
                repairHint: "Для location object передай locationId и/или name, чтобы клиент мог однозначно разрешить или создать локацию."));
        }

        ValidateOptionalString(location, context, issues, "name");
        ValidateOptionalString(location, context, issues, "description");
        ValidateOptionalString(location, context, issues, "lastEventsDescription");
        var lastEventsDescription = GetFirstNonEmptyString(location, "lastEventsDescription");
        if (!string.IsNullOrWhiteSpace(lastEventsDescription) &&
            !MatchesHistoricalEntryContract(lastEventsDescription))
        {
            issues.Add(new ValidationIssue(
                $"{context}.lastEventsDescription",
                IssueSeverity.Error,
                "lastEventsDescription должен использовать canonical historical-entry timestamp format",
                code: "location_last_events_timestamp_invalid",
                section: "Location",
                expected: "#[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                actual: lastEventsDescription,
                repairHint: "Начинай lastEventsDescription с полного timestamp-префикса из Block 18.A. В переходный период также допустим legacy '#[turn_number]. ...' если ты выравниваешь старый контент."));
        }
        if ((context.Contains(".currentLocationData", StringComparison.OrdinalIgnoreCase) ||
             context.Contains(".newLocations[", StringComparison.OrdinalIgnoreCase) ||
             context.Contains(".locationUpdates[", StringComparison.OrdinalIgnoreCase)) &&
            location.TryGetProperty("eventDescriptions", out _))
        {
            issues.Add(new ValidationIssue(
                $"{context}.eventDescriptions",
                IssueSeverity.Error,
                "eventDescriptions является read-only историческим логом и не должен приходить из GM-authored location update",
                code: "location_event_descriptions_forbidden",
                section: "Location",
                repairHint: "Не отправляй eventDescriptions в currentLocationData / worldMapUpdates. Читай историю оттуда, а в ответ пиши только lastEventsDescription."));
        }

        var locationType = RequireString(location, context, issues, "locationType");
        if (!string.IsNullOrWhiteSpace(locationType) &&
            !string.Equals(locationType, "outdoor", StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(locationType, "indoor", StringComparison.OrdinalIgnoreCase))
        {
            issues.Add(new ValidationIssue(
                $"{context}.locationType",
                IssueSeverity.Error,
                "locationType должен быть 'outdoor' или 'indoor'",
                code: "location_type_invalid",
                section: "Location",
                expected: "outdoor or indoor",
                actual: locationType,
                repairHint: "Используй для locationType только canonical значения outdoor или indoor."));
        }

        if (location.TryGetProperty("coordinates", out var coordinates))
        {
            ValidateLocationCoordinatesObject(
                coordinates,
                $"{context}.coordinates",
                issues,
                allowLegacyMissingZ: HasNonEmptyString(location, "locationId"),
                section: "Location");
        }
        else
        {
            issues.Add(new ValidationIssue(
                $"{context}.coordinates",
                IssueSeverity.Error,
                "Локация должна содержать объект coordinates",
                code: "location_coordinates_missing",
                section: "Location",
                expected: "coordinates object",
                actual: "missing",
                repairHint: "Добавь coordinates с canonical x/y и при необходимости z. Даже для known-location shorthand coordinates остаются обязательными."));
        }

        ValidateDifficultyProfileObject(location, context, issues, "internalDifficultyProfile");
        ValidateDifficultyProfileObject(location, context, issues, "externalDifficultyProfile");

        if (string.Equals(locationType, "outdoor", StringComparison.OrdinalIgnoreCase) &&
            !HasNonEmptyString(location, "biome"))
        {
            issues.Add(new ValidationIssue(
                $"{context}.biome",
                IssueSeverity.Error,
                "Outdoor location обязан содержать biome"));
        }
        else if (string.Equals(locationType, "outdoor", StringComparison.OrdinalIgnoreCase))
        {
            var biome = GetFirstNonEmptyString(location, "biome");
            if (!string.IsNullOrWhiteSpace(biome) && !AllowedOutdoorBiomes.Contains(biome))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.biome",
                    IssueSeverity.Error,
                    "Outdoor biome должен быть одним из canonical enum значений",
                    code: "location_invalid_biome",
                    section: "Location",
                    expected: string.Join(" | ", AllowedOutdoorBiomes),
                    actual: biome,
                    repairHint: "Используй для outdoor locations только canonical biome values из Block 20.5."));
            }

            if (string.Equals(biome, "Unique", StringComparison.OrdinalIgnoreCase) &&
                !HasNonEmptyString(location, "biomeDescription"))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.biomeDescription",
                    IssueSeverity.Error,
                    "Outdoor biome = Unique требует непустой biomeDescription",
                    code: "location_unique_biome_missing_description",
                    section: "Location",
                    repairHint: "Для biome=Unique добавь biomeDescription, объясняющий уникальную природу среды."));
            }
        }

        if (!string.Equals(locationType, "outdoor", StringComparison.OrdinalIgnoreCase) &&
            location.TryGetProperty("biome", out var indoorBiome) &&
            indoorBiome.ValueKind != JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{context}.biome",
                IssueSeverity.Error,
                "biome используется только для outdoor locations",
                code: "location_biome_forbidden_for_indoor",
                section: "Location",
                repairHint: "Убери biome у indoor location и при необходимости используй indoorType."));
        }

        if (location.TryGetProperty("indoorType", out var indoorType) && indoorType.ValueKind != JsonValueKind.Null)
        {
            if (!string.Equals(locationType, "indoor", StringComparison.OrdinalIgnoreCase))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.indoorType",
                    IssueSeverity.Error,
                    "indoorType допустим только для indoor locations",
                    code: "location_indoor_type_forbidden_for_outdoor",
                    section: "Location",
                    repairHint: "Используй indoorType только при locationType = indoor."));
            }
            else if (indoorType.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(indoorType.GetString()))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.indoorType",
                    IssueSeverity.Error,
                    "indoorType должен быть непустой строкой из canonical indoor type enum",
                    code: "location_invalid_indoor_type",
                    section: "Location",
                    expected: string.Join(" | ", AllowedIndoorLocationTypes),
                    actual: indoorType.ValueKind.ToString(),
                    repairHint: "Используй для indoorType только Building, Dungeon, CaveSystem, Vehicle или UniqueIndoor."));
            }
            else if (!AllowedIndoorLocationTypes.Contains(indoorType.GetString()!))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.indoorType",
                    IssueSeverity.Error,
                    "indoorType должен быть одним из canonical enum значений",
                    code: "location_invalid_indoor_type",
                    section: "Location",
                    expected: string.Join(" | ", AllowedIndoorLocationTypes),
                    actual: indoorType.GetString(),
                    repairHint: "Используй для indoorType только Building, Dungeon, CaveSystem, Vehicle или UniqueIndoor."));
            }
        }

        ValidateOptionalString(location, context, issues, "image_prompt");
        if (!HasNonEmptyString(location, "locationId") && !HasNonEmptyString(location, "image_prompt"))
        {
            issues.Add(new ValidationIssue(
                $"{context}.image_prompt",
                IssueSeverity.Error,
                "Новая локация без locationId должна содержать image_prompt"));
        }
        ValidateFactionControlArray(location, context, issues, "factionControl");
        ValidateLocationAdjacencyArray(location, context, issues, "adjacencyMap");
        ValidateLocationStorageArray(location, context, issues, "locationStorages");
        ValidateActiveThreatArray(location, context, issues, "activeThreats");
    }

    private void ValidateNewLocationObject(JsonElement location, string context, List<ValidationIssue> issues)
    {
        ValidateLocationObject(location, context, issues);

        if (!location.TryGetProperty("locationId", out var locationId) || locationId.ValueKind != JsonValueKind.Null)
        {
            issues.Add(new ValidationIssue(
                $"{context}.locationId",
                IssueSeverity.Error,
                "newLocations entry должен явно передавать locationId = null",
                code: "world_map_new_location_requires_null_location_id",
                section: "WorldMap",
                expected: "locationId = null for a new off-screen location",
                actual: location.TryGetProperty("locationId", out var actualLocationId) ? actualLocationId.ValueKind.ToString() : "missing",
                repairHint: "Для создания новой off-screen location передай полный Location Object с locationId = null; permanent GUID назначит система."));
        }

        if (!HasNonEmptyString(location, "description"))
        {
            issues.Add(new ValidationIssue(
                $"{context}.description",
                IssueSeverity.Error,
                "newLocations entry должен содержать полное description",
                code: "world_map_new_location_missing_description",
                section: "WorldMap",
                repairHint: "Для новой off-screen location передай полный description, а не skeletal location stub."));
        }
    }

    private void ValidateLocationCoordinatesObject(
        JsonElement coordinates,
        string context,
        List<ValidationIssue> issues,
        bool allowLegacyMissingZ,
        string section)
    {
        if (!RequireObject(coordinates, context, issues))
            return;

        ValidateIntegerField(coordinates, context, issues, "x");
        ValidateIntegerField(coordinates, context, issues, "y");

        if (coordinates.TryGetProperty("z", out _))
        {
            ValidateIntegerField(coordinates, context, issues, "z");
            return;
        }

        if (allowLegacyMissingZ)
            return;

        issues.Add(new ValidationIssue(
            $"{context}.z",
            IssueSeverity.Error,
            "coordinates должен содержать обязательный z",
            code: "location_coordinates_missing_z",
            section: section,
            expected: "integer z coordinate",
            actual: "missing",
            repairHint: "Передай coordinates как { x, y, z }. Legacy x/y-only format временно допускается только для уже существующих старых локаций без Z-координаты."));
    }

    private void ValidateQuestArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!TryGetArray(root, propName, $"{contextPrefix}.{propName}", issues, out var arr))
            return;

        var isSoulQuestCollection =
            string.Equals(propName, "UpdateSoulQuests", StringComparison.OrdinalIgnoreCase) ||
            (string.Equals(propName, "quests", StringComparison.OrdinalIgnoreCase) &&
             contextPrefix.EndsWith("game_state/quests/soul_quests.json", StringComparison.OrdinalIgnoreCase));
        var knownRegularQuestIds =
            string.Equals(propName, "UpdateQuests", StringComparison.OrdinalIgnoreCase)
                ? ReadKnownRegularQuestIdsFromPreTurnSync()
                : null;
        var sameTurnNewQuestInitialIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues)) continue;

            var questId = GetFirstNonEmptyString(item, "questId");
            var initialId = GetFirstNonEmptyString(item, "initialId");
            var isQuestLogAppend = IsQuestPartialLogAppend(item);
            var isQuestPartialStateUpdate = IsQuestPartialStateUpdate(item);
            var isSameTurnInitialLink = !string.IsNullOrWhiteSpace(initialId) && sameTurnNewQuestInitialIds.Contains(initialId);
            var usesInitialIdQuestLink =
                string.IsNullOrWhiteSpace(questId) &&
                !string.IsNullOrWhiteSpace(initialId) &&
                (isQuestLogAppend || isQuestPartialStateUpdate);

            if (!item.TryGetProperty("questId", out _) && !usesInitialIdQuestLink)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.questId",
                    IssueSeverity.Error,
                    "Quest object должен содержать обязательное поле questId",
                    code: "quest_missing_quest_id_field",
                    section: "Quest",
                    expected: "questId field (GUID/string for existing quest, null for genuinely new quest)",
                    actual: "missing",
                    repairHint: "Передай questId явно: используй existing questId для известного квеста или questId = null для genuinely new quest/full object в этом accepted turn."));
            }

            if (knownRegularQuestIds != null)
            {
                if (!string.IsNullOrWhiteSpace(questId) && !knownRegularQuestIds.Contains(questId))
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.questId",
                        IssueSeverity.Error,
                        "UpdateQuests ссылается на questId, которого нет в pre-turn regular_quests state",
                        code: "quest_update_unknown_existing_quest",
                        section: "Quest",
                        expected: "existing questId from pre-turn regular_quests.json",
                        actual: questId,
                        repairHint: "Для existing quest update используй questId из pre-turn regular_quests.json. Для genuinely new quest оставь questId = null и передай полный Quest Object."));
                }

                if (string.IsNullOrWhiteSpace(questId) &&
                    !string.IsNullOrWhiteSpace(initialId) &&
                    (isQuestLogAppend || isQuestPartialStateUpdate) &&
                    !isSameTurnInitialLink)
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.initialId",
                        IssueSeverity.Error,
                        "Quest partial update использует initialId, который не был создан более ранним full Quest Object в этом же accepted turn",
                        code: "quest_partial_unknown_same_turn_initial_id",
                        section: "Quest",
                        expected: "initialId of a new full quest object created earlier in the same UpdateQuests array",
                        actual: initialId,
                        repairHint: "Для same-turn linking сначала создай новый Quest Object с questId = null и initialId, а уже потом ссылайся на него через initialId в partial update или log append."));
                }
            }

            if (isSoulQuestCollection)
            {
                ValidateSoulQuestObject(item, itemContext, issues);
            }
            else if (isQuestLogAppend)
            {
                ValidateQuestPartialLogUpdateObject(item, itemContext, issues);
            }
            else if (string.Equals(propName, "UpdateQuests", StringComparison.OrdinalIgnoreCase) && isQuestPartialStateUpdate)
            {
                ValidateQuestPartialStateUpdateObject(item, itemContext, issues);
            }
            else
            {
                ValidateQuestObject(item, itemContext, issues);
                if (string.Equals(propName, "UpdateQuests", StringComparison.OrdinalIgnoreCase) &&
                    string.IsNullOrWhiteSpace(questId) &&
                    !string.IsNullOrWhiteSpace(initialId))
                {
                    sameTurnNewQuestInitialIds.Add(initialId);
                }
            }
        }

        if (isSoulQuestCollection)
        {
            var activeSoulQuestCount = CountMergedActiveSoulQuests(contextPrefix, propName, arr);
            if (activeSoulQuestCount > 8)
            {
                issues.Add(new ValidationIssue(
                    $"{contextPrefix}.{propName}",
                    IssueSeverity.Error,
                    "UpdateSoulQuests не должен активировать более 8 soul quests за одну жизнь",
                    code: "soul_quests_active_cap_exceeded",
                    section: "SoulQuests",
                    expected: "<= 8 active soul quests",
                    actual: activeSoulQuestCount.ToString(),
                repairHint: "Сохрани не более 8 active soul quests. Заверши, отмени или не активируй лишние задачи в этой жизни."));
            }
        }
    }

    private HashSet<string> ReadKnownRegularQuestIdsFromPreTurnSync()
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var preTurnJson = ReadPreTurnTrackedFileSync("game_state/quests/regular_quests.json");
        if (string.IsNullOrWhiteSpace(preTurnJson))
            return ids;

        try
        {
            using var doc = JsonDocument.Parse(preTurnJson);
            foreach (var propName in new[] { "quests", "UpdateQuests" })
            {
                if (!doc.RootElement.TryGetProperty(propName, out var arr) || arr.ValueKind != JsonValueKind.Array)
                    continue;

                foreach (var item in arr.EnumerateArray())
                {
                    var questId = GetFirstNonEmptyString(item, "questId");
                    if (!string.IsNullOrWhiteSpace(questId))
                        ids.Add(questId);
                }
            }
        }
        catch
        {
            // ignored
        }

        return ids;
    }

    private static bool IsQuestPartialStateUpdate(JsonElement item)
    {
        if (!HasAnyNonEmptyString(item, "questId", "initialId"))
            return false;

        if (item.TryGetProperty("detailsLog", out _))
            return false;

        return !LooksLikeFullQuestObject(item);
    }

    private int CountMergedActiveSoulQuests(string contextPrefix, string propName, JsonElement currentArray)
    {
        static void CollectStatusesFromArray(JsonElement array, Dictionary<string, string> statuses)
        {
            if (array.ValueKind != JsonValueKind.Array)
                return;

            foreach (var item in array.EnumerateArray())
            {
                if (item.ValueKind != JsonValueKind.Object)
                    continue;

                var questId = GetFirstNonEmptyString(item, "questId");
                var status = GetFirstNonEmptyString(item, "status");
                if (string.IsNullOrWhiteSpace(questId) || string.IsNullOrWhiteSpace(status))
                    continue;

                statuses[questId] = status;
            }
        }

        if (string.Equals(propName, "quests", StringComparison.OrdinalIgnoreCase) &&
            contextPrefix.EndsWith("game_state/quests/soul_quests.json", StringComparison.OrdinalIgnoreCase))
        {
            return currentArray.EnumerateArray().Count(item =>
                item.ValueKind == JsonValueKind.Object &&
                string.Equals(GetFirstNonEmptyString(item, "status"), "active", StringComparison.OrdinalIgnoreCase));
        }

        var mergedStatuses = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var preTurnJson = ReadPreTurnTrackedFileSync("game_state/quests/soul_quests.json");
        if (!string.IsNullOrWhiteSpace(preTurnJson))
        {
            try
            {
                using var doc = JsonDocument.Parse(preTurnJson);
                if (doc.RootElement.TryGetProperty("quests", out var storedQuests))
                    CollectStatusesFromArray(storedQuests, mergedStatuses);
                else if (doc.RootElement.TryGetProperty("UpdateSoulQuests", out var legacyUpdates))
                    CollectStatusesFromArray(legacyUpdates, mergedStatuses);
            }
            catch
            {
                // Ignore malformed pre-turn snapshot here; generic state validation will surface it separately.
            }
        }

        CollectStatusesFromArray(currentArray, mergedStatuses);
        return mergedStatuses.Values.Count(status => string.Equals(status, "active", StringComparison.OrdinalIgnoreCase));
    }

    private void ValidateLocationUpdateArray(JsonElement arr, string context, List<ValidationIssue> issues)
    {
        RequireArrayOfObjects(arr, context, issues);
        if (arr.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{context}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            RequireString(item, itemContext, issues, "locationId");
            var hasAnyUpdateField =
                HasAnyNonEmptyString(item, "newName", "newDescription", "newLastEventsDescription", "newImagePrompt") ||
                item.TryGetProperty("coordinates", out _) ||
                item.TryGetProperty("newInternalDifficultyProfile", out _) ||
                item.TryGetProperty("newExternalDifficultyProfile", out _) ||
                item.TryGetProperty("factionControl", out _);
            if (!hasAnyUpdateField)
            {
                issues.Add(new ValidationIssue(
                    itemContext,
                    IssueSeverity.Error,
                    "locationUpdates partial update должен содержать хотя бы одно реально изменяемое поле",
                    code: "location_update_missing_changes",
                    section: "Location",
                    expected: "locationId plus at least one changed field (new*, coordinates, or factionControl)",
                    actual: "locationId only",
                    repairHint: "Для locationUpdates передай locationId и хотя бы одно изменяемое поле: newName/newDescription/newLastEventsDescription/newImagePrompt, coordinates, difficulty profile или factionControl. Не отправляй пустой no-op update только с locationId."));
            }

            ValidateOptionalString(item, itemContext, issues, "newName");
            ValidateOptionalString(item, itemContext, issues, "newDescription");
            ValidateOptionalString(item, itemContext, issues, "newLastEventsDescription");
            ValidateOptionalString(item, itemContext, issues, "newImagePrompt");
            if (item.TryGetProperty("coordinates", out var updatedCoordinates))
                ValidateLocationCoordinatesObject(updatedCoordinates, $"{itemContext}.coordinates", issues, allowLegacyMissingZ: false, section: "Location");
            if (item.TryGetProperty("factionControl", out _))
                ValidateFactionControlArray(item, itemContext, issues, "factionControl");

            var newLastEventsDescription = GetFirstNonEmptyString(item, "newLastEventsDescription");
            if (!string.IsNullOrWhiteSpace(newLastEventsDescription) &&
                !MatchesHistoricalEntryContract(newLastEventsDescription))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.newLastEventsDescription",
                    IssueSeverity.Error,
                    "newLastEventsDescription должен использовать canonical historical-entry timestamp format",
                    code: "location_update_last_events_prefix_invalid",
                    section: "Location",
                    expected: "#[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                    actual: newLastEventsDescription,
                    repairHint: "Начинай newLastEventsDescription с полного timestamp-префикса из Block 18.A. Из-за старых примеров также допустим legacy формат '#[turn_number]. ...', но не произвольная строка без turn anchor."));
            }

            if (item.TryGetProperty("newInternalDifficultyProfile", out var newInternal) &&
                RequireObject(newInternal, $"{itemContext}.newInternalDifficultyProfile", issues))
            {
                foreach (var scale in new[] { "combat", "environment", "social", "exploration" })
                    ValidateNonNegativeIntegerField(newInternal, $"{itemContext}.newInternalDifficultyProfile", issues, scale, "Location");
            }

            if (item.TryGetProperty("newExternalDifficultyProfile", out var newExternal) &&
                RequireObject(newExternal, $"{itemContext}.newExternalDifficultyProfile", issues))
            {
                foreach (var scale in new[] { "combat", "environment", "social", "exploration" })
                    ValidateNonNegativeIntegerField(newExternal, $"{itemContext}.newExternalDifficultyProfile", issues, scale, "Location");
            }

            if (item.TryGetProperty("eventDescriptions", out _))
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.eventDescriptions",
                    IssueSeverity.Error,
                    "locationUpdates не должен пересылать eventDescriptions; это read-only исторический архив",
                    code: "location_update_event_descriptions_forbidden",
                    section: "Location",
                    repairHint: "Для off-screen обновлений локации используй newLastEventsDescription, а не eventDescriptions."));
            }
        }
    }

    private void ValidateWorldMapNewLinks(JsonElement arr, string context, List<ValidationIssue> issues)
    {
        RequireArrayOfObjects(arr, context, issues);
        if (arr.ValueKind != JsonValueKind.Array)
            return;

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{context}[{index++}]";
            if (!RequireObject(item, itemContext, issues))
                continue;

            var missingFields = GetMissingRequiredNonEmptyStringProperties(item, "sourceLocationId");
            if (missingFields.Count > 0 || !item.TryGetProperty("link", out _))
            {
                var actualMissing = new List<string>(missingFields);
                if (!item.TryGetProperty("link", out _))
                    actualMissing.Add("link");

                issues.Add(new ValidationIssue(
                    itemContext,
                    IssueSeverity.Error,
                    "worldMapUpdates.newLinks entry не содержит обязательные корневые поля",
                    code: "world_map_new_link_missing_required_fields",
                    section: "WorldMap",
                    expected: "sourceLocationId + link adjacency entry object",
                    actual: string.Join(", ", actualMissing),
                    repairHint: "Для dynamic path discovery передай sourceLocationId локации-источника и nested link с полным adjacency entry object."));
                continue;
            }

            RequireString(item, itemContext, issues, "sourceLocationId");
            if (!item.TryGetProperty("link", out var link) || !RequireObject(link, $"{itemContext}.link", issues))
                continue;

            ValidateWorldMapAdjacencyLinkObject(link, $"{itemContext}.link", issues);
        }
    }

    private void ValidateWorldMapAdjacencyLinkObject(JsonElement link, string context, List<ValidationIssue> issues)
    {
        RequireString(link, context, issues, "name");
        RequireString(link, context, issues, "shortDescription");
        RequireString(link, context, issues, "linkType");
        RequireString(link, context, issues, "linkState");

        if (!link.TryGetProperty("targetCoordinates", out var targetCoordinates) ||
            !RequireObject(targetCoordinates, $"{context}.targetCoordinates", issues))
        {
            issues.Add(new ValidationIssue(
                $"{context}.targetCoordinates",
                IssueSeverity.Error,
                "Adjacency link должен содержать targetCoordinates object",
                code: "world_map_link_missing_target_coordinates",
                section: "WorldMap",
                expected: "targetCoordinates object with x/y and optional z",
                actual: link.TryGetProperty("targetCoordinates", out var actualTargetCoordinates)
                    ? actualTargetCoordinates.ValueKind.ToString()
                    : "missing",
                repairHint: "Для adjacency link всегда передавай targetCoordinates object с canonical integer x/y и optional z."));
        }
        else
        {
            ValidateIntegerField(targetCoordinates, $"{context}.targetCoordinates", issues, "x");
            ValidateIntegerField(targetCoordinates, $"{context}.targetCoordinates", issues, "y");
            if (targetCoordinates.TryGetProperty("z", out _))
                ValidateIntegerField(targetCoordinates, $"{context}.targetCoordinates", issues, "z");
        }

        foreach (var propName in new[] { "estimatedInternalDifficultyProfile", "estimatedExternalDifficultyProfile" })
        {
            if (!link.TryGetProperty(propName, out var profile) ||
                !RequireObject(profile, $"{context}.{propName}", issues))
            {
                issues.Add(new ValidationIssue(
                    $"{context}.{propName}",
                    IssueSeverity.Error,
                    $"{propName} обязателен для adjacency link preview",
                    code: "world_map_link_preview_missing_difficulty_profile",
                    section: "WorldMap",
                    expected: $"{propName} object with combat/environment/social/exploration integer scales",
                    actual: "missing or non-object",
                    repairHint: $"Добавь в adjacency link preview объект {propName} с integer-полями combat, environment, social и exploration."));
                continue;
            }

            foreach (var scale in new[] { "combat", "environment", "social", "exploration" })
                ValidateNonNegativeIntegerField(profile, $"{context}.{propName}", issues, scale, "WorldMap");
        }
    }

    private static HashSet<string> GetExpectedNpcAttitudeValues(int relationshipLevel)
    {
        return relationshipLevel switch
        {
            <= -201 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Непримиримый Враг",
                "Implacable Foe"
            },
            <= -51 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Противник",
                "Adversary"
            },
            <= -1 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Неприязнь",
                "Dislike"
            },
            <= 100 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Нейтралитет",
                "Neutral"
            },
            <= 250 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Доверие и Расположение",
                "Familiarity & Trust"
            },
            <= 350 => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Глубокая Связь",
                "Deep Bond"
            },
            _ => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Легендарная Преданность",
                "Legendary Bond"
            }
        };
    }

    private void ValidateQuestHistoryData(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (root.TryGetProperty("questHistory", out var questHistory))
        {
            if (questHistory.ValueKind != JsonValueKind.Array)
            {
                issues.Add(new ValidationIssue(
                    $"{contextPrefix}.questHistory",
                    IssueSeverity.Error,
                    "questHistory должен быть массивом",
                    code: "quest_history_invalid_array",
                    section: "QuestHistory",
                    expected: "array of quest history entries",
                    actual: questHistory.ValueKind.ToString(),
                    repairHint: "Сохраняй questHistory как массив записей завершённых или заархивированных квестов, а не как scalar/object заглушку."));
            }
            else
            {
                var index = 0;
                foreach (var item in questHistory.EnumerateArray())
                {
                    var itemContext = $"{contextPrefix}.questHistory[{index++}]";
                    if (!RequireObject(item, itemContext, issues))
                        continue;

                    if (!HasAnyNonEmptyString(item, "questId", "questName", "title", "name"))
                    {
                        issues.Add(new ValidationIssue(
                            itemContext,
                            IssueSeverity.Error,
                            "История квеста должна содержать questId или title/name",
                            code: "quest_history_entry_missing_identity",
                            section: "QuestHistory",
                            expected: "questId or questName/title/name",
                            actual: "missing identity fields",
                            repairHint: "Для каждой записи questHistory передай questId и/или читаемое имя квеста, чтобы запись можно было однозначно связать с canonical quest history."));
                    }

                    RequireString(item, itemContext, issues, "outcome");
                    ValidateOptionalString(item, itemContext, issues, "completionDate");
                    ValidateOptionalString(item, itemContext, issues, "reputation");
                    ValidateNonNegativeNumberField(item, itemContext, issues, "experience");
                    ValidateNonNegativeNumberField(item, itemContext, issues, "incarnationNumber");
                }
            }
        }

        if (root.TryGetProperty("questRewards", out var questRewards))
        {
            if (questRewards.ValueKind != JsonValueKind.Array)
            {
                issues.Add(new ValidationIssue(
                    $"{contextPrefix}.questRewards",
                    IssueSeverity.Error,
                    "questRewards должен быть массивом",
                    code: "quest_rewards_invalid_array",
                    section: "QuestHistory",
                    expected: "array of quest reward records",
                    actual: questRewards.ValueKind.ToString(),
                    repairHint: "Сохраняй questRewards как массив reward records, а не как scalar/object заглушку."));
            }
            else
            {
                var index = 0;
                foreach (var item in questRewards.EnumerateArray())
                {
                    var itemContext = $"{contextPrefix}.questRewards[{index++}]";
                    if (!RequireObject(item, itemContext, issues))
                        continue;

                    RequireString(item, itemContext, issues, "questId");
                    if (item.TryGetProperty("itemsReceived", out var itemsReceived))
                        RequireArrayOfStrings(itemsReceived, $"{itemContext}.itemsReceived", issues);
                    if (item.TryGetProperty("skillsUnlocked", out var skillsUnlocked))
                        RequireArrayOfStrings(skillsUnlocked, $"{itemContext}.skillsUnlocked", issues);
                    if (item.TryGetProperty("relationshipChanges", out var relationshipChanges))
                        RequireArrayOfStrings(relationshipChanges, $"{itemContext}.relationshipChanges", issues);
                }
            }
        }

        if (root.TryGetProperty("questChains", out var questChains))
        {
            if (questChains.ValueKind != JsonValueKind.Array)
            {
                issues.Add(new ValidationIssue(
                    $"{contextPrefix}.questChains",
                    IssueSeverity.Error,
                    "questChains должен быть массивом",
                    code: "quest_chains_invalid_array",
                    section: "QuestHistory",
                    expected: "array of quest chain records",
                    actual: questChains.ValueKind.ToString(),
                    repairHint: "Сохраняй questChains как массив chain records, а не как scalar/object заглушку."));
            }
            else
            {
                var index = 0;
                foreach (var item in questChains.EnumerateArray())
                {
                    var itemContext = $"{contextPrefix}.questChains[{index++}]";
                    if (!RequireObject(item, itemContext, issues))
                        continue;

                    RequireString(item, itemContext, issues, "chainId");
                    RequireString(item, itemContext, issues, "currentQuest");
                    ValidateOptionalString(item, itemContext, issues, "progress");
                    if (item.TryGetProperty("unlocked", out var unlocked) &&
                        unlocked.ValueKind is not (JsonValueKind.True or JsonValueKind.False))
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.unlocked",
                            IssueSeverity.Error,
                            "questChains.unlocked должен быть boolean",
                            code: "quest_chain_unlocked_invalid",
                            section: "QuestHistory",
                            expected: "true or false",
                            actual: unlocked.ValueKind.ToString(),
                            repairHint: "Сохраняй questChains.unlocked как boolean-флаг, а не как число/строку."));
                    }
                }
            }
        }
    }

    private void ValidateQuestLog(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("questLog", out var value))
            return;

        var context = $"{contextPrefix}.questLog";
        if (value.ValueKind == JsonValueKind.Array)
        {
            var index = 0;
            foreach (var item in value.EnumerateArray())
            {
                if (item.ValueKind is not (JsonValueKind.Object or JsonValueKind.String))
                {
                    issues.Add(new ValidationIssue(
                        $"{context}[{index}]",
                        IssueSeverity.Error,
                        "Элемент questLog должен быть объектом или строкой",
                        code: "quest_log_entry_invalid_shape",
                        section: "QuestHistory",
                        expected: "questLog entry as object or string",
                        actual: item.ValueKind.ToString(),
                        repairHint: "В legacy questLog используй либо строковые заметки, либо object entries. Не смешивай с number/bool/null."));
                }
                index++;
            }
            return;
        }

        if (value.ValueKind != JsonValueKind.Object)
        {
            issues.Add(new ValidationIssue(
                context,
                IssueSeverity.Error,
                "questLog должен быть объектом или массивом",
                code: "quest_log_invalid_shape",
                section: "QuestHistory",
                expected: "legacy questLog object or array",
                actual: value.ValueKind.ToString(),
                repairHint: "Если используешь legacy questLog shorthand, сохраняй его как object или array. Для canonical stored shape предпочитай questHistory, questRewards и questChains."));
        }
    }

    private static bool IsQuestPartialLogAppend(JsonElement item)
    {
        return HasAnyNonEmptyString(item, "questId", "initialId") &&
               item.TryGetProperty("newDetailsLogEntry", out var newEntry) &&
               newEntry.ValueKind == JsonValueKind.String &&
               !string.IsNullOrWhiteSpace(newEntry.GetString());
    }

    private void ValidateQuestPartialLogUpdateObject(JsonElement item, string itemContext, List<ValidationIssue> issues)
    {
        RequireAnyString(item, itemContext, issues, "questId", "initialId");
        var newDetailsLogEntry = RequireString(item, itemContext, issues, "newDetailsLogEntry");

        if (!string.IsNullOrWhiteSpace(newDetailsLogEntry) &&
            !MatchesHistoricalEntryContract(newDetailsLogEntry))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.newDetailsLogEntry",
                IssueSeverity.Error,
                "newDetailsLogEntry должен начинаться с canonical turn anchor",
                code: "quest_log_entry_prefix_invalid",
                section: "Quest",
                expected: "#[turn_number]. ... or #[Turn] - [Day] [Month] [Year] г., [HH:MM]: ...",
                actual: newDetailsLogEntry,
                repairHint: "Для append-only записи журнала квеста используй canonical historical-entry timestamp из Block 18.A. Legacy prefix '#[turn_number]. ...' всё ещё принимается для старого контента, но не обязателен."));
        }

        if (item.TryGetProperty("detailsLog", out _))
        {
            issues.Add(new ValidationIssue(
                $"{itemContext}.detailsLog",
                IssueSeverity.Error,
                "Quest partial log update не должен пересылать detailsLog вместе с newDetailsLogEntry",
                code: "quest_partial_update_resends_details_log",
                section: "Quest",
                repairHint: "Для append-only обновления журнала отправляй questId или same-turn initialId вместе с newDetailsLogEntry без полного detailsLog."));
        }
    }

    private void ValidatePlotOutline(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("plotOutline", out var value))
            return;

        var context = $"{contextPrefix}.plotOutline";
        if (!RequireObject(value, context, issues))
            return;

        if (!value.TryGetProperty("mainArc", out var mainArc) || !RequireObject(mainArc, $"{context}.mainArc", issues))
        {
            issues.Add(new ValidationIssue(
                $"{context}.mainArc",
                IssueSeverity.Error,
                "plotOutline должен содержать объект mainArc",
                code: "plot_outline_missing_main_arc",
                section: "PlotOutline",
                expected: "mainArc object",
                actual: value.TryGetProperty("mainArc", out var actualMainArc) ? actualMainArc.ValueKind.ToString() : "missing",
                repairHint: "Сохрани canonical plotOutline object с обязательным mainArc, characterSubplots, loomingThreatsOrOpportunities и lastUpdatedTurn."));
            return;
        }

        RequireString(mainArc, $"{context}.mainArc", issues, "summary");
        RequireString(mainArc, $"{context}.mainArc", issues, "nextImmediateStep");
        RequireString(mainArc, $"{context}.mainArc", issues, "potentialClimax");

        if (!TryGetArray(value, "characterSubplots", $"{context}.characterSubplots", issues, out var characterSubplots))
            return;

        var subplotIndex = 0;
        foreach (var subplot in characterSubplots.EnumerateArray())
        {
            var subplotContext = $"{context}.characterSubplots[{subplotIndex++}]";
            if (!RequireObject(subplot, subplotContext, issues))
                continue;

            RequireString(subplot, subplotContext, issues, "characterName");
            RequireString(subplot, subplotContext, issues, "arcSummary");
            RequireString(subplot, subplotContext, issues, "nextStep");
            RequireString(subplot, subplotContext, issues, "potentialConflictOrResolution");
        }

        if (!value.TryGetProperty("loomingThreatsOrOpportunities", out var threats) || threats.ValueKind != JsonValueKind.Array)
        {
            issues.Add(new ValidationIssue(
                $"{context}.loomingThreatsOrOpportunities",
                IssueSeverity.Error,
                "plotOutline должен содержать массив loomingThreatsOrOpportunities",
                code: "plot_outline_missing_threats",
                section: "PlotOutline",
                expected: "array of strings",
                actual: value.TryGetProperty("loomingThreatsOrOpportunities", out var actualThreats) ? actualThreats.ValueKind.ToString() : "missing",
                repairHint: "Заполни loomingThreatsOrOpportunities массивом строк с текущими фоновыми угрозами или возможностями."));
        }
        else
        {
            RequireArrayOfStrings(threats, $"{context}.loomingThreatsOrOpportunities", issues);
        }

        if (!value.TryGetProperty("lastUpdatedTurn", out var lastUpdatedTurn))
        {
            issues.Add(new ValidationIssue(
                $"{context}.lastUpdatedTurn",
                IssueSeverity.Error,
                "plotOutline должен содержать integer lastUpdatedTurn",
                code: "plot_outline_missing_last_updated_turn",
                section: "PlotOutline",
                expected: "integer lastUpdatedTurn",
                actual: "missing",
                repairHint: "Сохрани в plotOutline текущий integer turn number в поле lastUpdatedTurn."));
        }
        else if (lastUpdatedTurn.ValueKind != JsonValueKind.Number || !lastUpdatedTurn.TryGetInt32(out var parsedTurn) || parsedTurn < 0)
        {
            issues.Add(new ValidationIssue(
                $"{context}.lastUpdatedTurn",
                IssueSeverity.Error,
                "plotOutline.lastUpdatedTurn должен быть неотрицательным integer turn number",
                code: "plot_outline_invalid_last_updated_turn",
                section: "PlotOutline",
                expected: "non-negative integer",
                actual: lastUpdatedTurn.ValueKind == JsonValueKind.Number ? lastUpdatedTurn.ToString() : lastUpdatedTurn.ValueKind.ToString(),
                repairHint: "Передай в lastUpdatedTurn текущий номер хода как неотрицательное целое число."));
        }
    }

    private void ValidateCombatantArray(JsonElement root, string contextPrefix, List<ValidationIssue> issues, string propName)
    {
        if (!TryGetArray(root, propName, $"{contextPrefix}.{propName}", issues, out var arr))
            return;

        var index = 0;
        foreach (var item in arr.EnumerateArray())
        {
            var itemContext = $"{contextPrefix}.{propName}[{index++}]";
            if (!RequireObject(item, itemContext, issues)) continue;

            if (!HasAnyNonEmptyString(item, "name", "enemyName", "allyName"))
            {
                issues.Add(new ValidationIssue(itemContext, IssueSeverity.Error,
                    "Боевой объект должен содержать name/enemyName/allyName"));
            }

            ValidateRequiredNullableStringField(item, itemContext, issues, "NPCId");
            RequireString(item, itemContext, issues, "image_prompt");
            RequireString(item, itemContext, issues, "description");
            RequireString(item, itemContext, issues, "type");
            RequireBooleanField(item, itemContext, issues, "isGroup");
            ValidatePercentageStringField(item, itemContext, issues, "maxHealth", requirePositive: true);
            RequireString(item, itemContext, issues, "maxPoise");
            ValidateRequiredNullableStringField(item, itemContext, issues, "currentHealth");
            ValidateRequiredNullableStringField(item, itemContext, issues, "currentPoise");
            RequireObjectArrayField(item, itemContext, issues, "actions");
            RequireObjectArrayField(item, itemContext, issues, "resistances");
            RequireObjectArrayField(item, itemContext, issues, "activeBuffs");
            RequireObjectArrayField(item, itemContext, issues, "activeDebuffs");

            if (item.TryGetProperty("actions", out var actions))
                ValidateCombatActionArray(actions, $"{itemContext}.actions", issues, section: "Combat");
            if (item.TryGetProperty("resistances", out var resistances))
                ValidateCombatResistanceArray(resistances, $"{itemContext}.resistances", issues);
            if (item.TryGetProperty("activeBuffs", out var activeBuffs))
                ValidateCombatantActiveEffectArray(activeBuffs, $"{itemContext}.activeBuffs", issues);
            if (item.TryGetProperty("activeDebuffs", out var activeDebuffs))
                ValidateCombatantActiveEffectArray(activeDebuffs, $"{itemContext}.activeDebuffs", issues);

            if (item.TryGetProperty("currentHealth", out var currentHealthNode) &&
                currentHealthNode.ValueKind == JsonValueKind.String)
            {
                ValidatePercentageStringField(item, itemContext, issues, "currentHealth", requirePositive: false);
            }

            if (item.TryGetProperty("maxPoise", out var maxPoiseNode) &&
                maxPoiseNode.ValueKind == JsonValueKind.String)
            {
                ValidatePercentageStringField(item, itemContext, issues, "maxPoise", requirePositive: true);
            }

            if (item.TryGetProperty("currentPoise", out var currentPoiseNode) &&
                currentPoiseNode.ValueKind == JsonValueKind.String)
            {
                ValidatePercentageStringField(item, itemContext, issues, "currentPoise", requirePositive: false);
            }

            if (item.TryGetProperty("isGroup", out var isGroup) &&
                isGroup.ValueKind is JsonValueKind.True)
            {
                ValidatePositiveIntegerField(item, itemContext, issues, "count");
                RequireString(item, itemContext, issues, "unitName");
                ValidateRequiredNullableStringArrayField(item, itemContext, issues, "healthStates");
                if (!item.TryGetProperty("healthStates", out var healthStates) || healthStates.ValueKind == JsonValueKind.Null)
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.healthStates",
                        IssueSeverity.Error,
                        "Group combatant обязан содержать массив healthStates",
                        code: "combat_group_missing_health_states",
                        section: "Combat",
                        repairHint: "Для isGroup=true передай healthStates[] с состоянием каждого юнита; null недопустим."));
                }
                else if (healthStates.ValueKind == JsonValueKind.Array)
                {
                    ValidatePercentageStringArrayValues(healthStates, $"{itemContext}.healthStates", issues);
                    if (item.TryGetProperty("count", out var countNode) &&
                        countNode.ValueKind == JsonValueKind.Number &&
                        countNode.TryGetInt32(out var count) &&
                        count > 0 &&
                        healthStates.GetArrayLength() != count)
                    {
                        issues.Add(new ValidationIssue(
                            $"{itemContext}.healthStates",
                            IssueSeverity.Error,
                            "Group combatant.healthStates должен содержать ровно count percentage entries",
                            code: "combat_group_health_states_count_mismatch",
                            section: "Combat",
                            expected: count.ToString(),
                            actual: healthStates.GetArrayLength().ToString(),
                            repairHint: "Для isGroup=true заполни healthStates[] состоянием каждого юнита; длина массива должна совпадать с count."));
                    }
                }
                if (item.TryGetProperty("currentHealth", out var currentHealth) && currentHealth.ValueKind != JsonValueKind.Null)
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.currentHealth",
                        IssueSeverity.Error,
                        "Group combatant должен передавать currentHealth = null",
                        code: "combat_group_current_health_must_be_null",
                        section: "Combat",
                        repairHint: "Для isGroup=true используй healthStates[] и оставляй currentHealth = null."));
                }

                if (item.TryGetProperty("currentPoise", out var currentPoise) && currentPoise.ValueKind != JsonValueKind.Null)
                {
                    issues.Add(new ValidationIssue(
                        $"{itemContext}.currentPoise",
                        IssueSeverity.Error,
                        "Group combatant должен передавать currentPoise = null",
                        code: "combat_group_current_poise_must_be_null",
                        section: "Combat",
                        repairHint: "Для isGroup=true оставляй currentPoise = null и описывай состояние группы через unitName/healthStates/actions."));
                }
            }
            else if (item.TryGetProperty("currentHealth", out var currentHealth) && currentHealth.ValueKind == JsonValueKind.Null)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.currentHealth",
                    IssueSeverity.Error,
                    "Individual combatant не должен передавать currentHealth = null",
                    code: "combat_individual_current_health_null",
                    section: "Combat",
                    repairHint: "Для одиночного combatant передай currentHealth как percentage string; null допустим только для групп."));
            }
            else if (item.TryGetProperty("currentPoise", out var currentPoise) && currentPoise.ValueKind == JsonValueKind.Null)
            {
                issues.Add(new ValidationIssue(
                    $"{itemContext}.currentPoise",
                    IssueSeverity.Error,
                    "Individual combatant не должен передавать currentPoise = null",
                    code: "combat_individual_current_poise_null",
                    section: "Combat",
                    repairHint: "Для одиночного combatant передай currentPoise как строку текущей стойкости; null допустим только для групп."));
            }
        }
    }

    private void ValidateCombatLog(JsonElement root, string contextPrefix, List<ValidationIssue> issues)
    {
        if (!root.TryGetProperty("combat_log_markdown", out var value))
            return;

        if (value.ValueKind != JsonValueKind.String)
